using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class BattleAI_CoordinationIntent
{
    private readonly BattleAI _ai;
    private PairStrategyIntent OpponentPrimaryStrategy;
    private readonly float[] _stageModifier = new float[] { 1f, 1.5f, 2f, 2.5f, 3f, 3.5f, 4f };

    public BattleAI_CoordinationIntent( BattleAI ai )
    {
        _ai = ai;
    }

    public CoordinationIntentResult GetCoordinationIntentResult( PairIntentResult pir, bool oneOpponentRemains = false )
    {
        OpponentPrimaryStrategy = pir.PrimaryStrategy;

        HashSet<StrategyPressureEvidence> primaryPressureEvidence = ExtractPressures( pir.PrimaryStrategy, pir.Poe );
        HashSet<StrategyPressureEvidence> secondaryPressuresEvidence = new();

        if( pir.Strategies.Count > 1 )
            secondaryPressuresEvidence = ExtractPressures( pir.SecondaryStrategy, pir.Poe );

        CustomLogSession cirLog = new();
        cirLog.Add( $"===================================" );
        cirLog.Add( $"===[Primary Pressure Extraction]===" );
        cirLog.Add( $"===================================" );
        cirLog.Add( $"" );
        cirLog.Add( $"Primary Strategy: {pir.PrimaryStrategy.Strategy}" );

        foreach( var e in primaryPressureEvidence )
            cirLog.Add( $"Found....{e.Pressure}" );
        
        cirLog.Add( $"" );

        //--Our Units
        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = GetPokemonBench( ourActive[0].Pokemon ).ToList();

        Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets = new();

        FindActionControlCapability( ourActive, ourBench, capabilitySets );
        FindProtectionCapability( ourActive, ourBench, capabilitySets );
        FindPressureCapability( ourActive, ourBench, capabilitySets );
        FindBoardControlCapability( ourActive, ourBench, capabilitySets );
        FindPositioningCapability( ourActive, ourBench, capabilitySets );
        FindEnablementCapability( ourActive, ourBench, capabilitySets );

        cirLog.Add( $"=============================" );
        cirLog.Add( $"===[Response Observations]===" );
        cirLog.Add( $"=============================" );
        cirLog.Add( $"" );

        foreach( var kvp in capabilitySets )
        {
            var responses = kvp.Value;

            cirLog.Add( $"{kvp.Key.NickName} had {kvp.Value.Count} responses" );
            foreach( var response in responses )
                cirLog.Add( $"{response}" );

            cirLog.Add( $"" );
        }

        var pressureResponses = GatherPressureResponses( capabilitySets, primaryPressureEvidence );

        cirLog.Add( $"==============================" );
        cirLog.Add( $"===[Responses to Pressures]===" );
        cirLog.Add( $"==============================" );
        cirLog.Add( $"" );

        foreach( var kvp in pressureResponses )
        {
            var pressure = kvp.Key;
            var spe = kvp.Value;
            int i = 1;

            cirLog.Add( $"Pressure: {pressure}" );
            foreach( var capability in spe.ResponseCapabilities )
            {
                var responses = capability.Value;
                foreach( var response in responses )
                    cirLog.Add( $"{i}. {response}" );

                i++;
            }

            cirLog.Add( $"" );
        }

        Dictionary<CoordinationAction, CoordinationActionScores> coordinationResponses = new();
        Dictionary<CoordinationAction, CoordinationActionScores> coordinationOpportunities = new();

        if( HasCapabilityOfActionType( ActionType.Attack, pressureResponses ) )
        {
            var responses = GetAttackResponses( pressureResponses );
            var opportunities = GetAttackOpportunities( capabilitySets );

            foreach( var kvp in responses )
                coordinationResponses.Add( kvp.Key, kvp.Value );

            foreach( var kvp in opportunities )
                coordinationOpportunities.Add( kvp.Key, kvp.Value );
        }

        if( HasCapabilityOfActionType( ActionType.DefensiveSwitch, pressureResponses ) )
        {
            // Debug.LogError( $"defensive capability found!" );
            var responses = GetSwitchResponses( pressureResponses );
            var opportunities = GetSwitchOpportunities( capabilitySets );

            foreach( var kvp in responses )
                coordinationResponses.Add( kvp.Key, kvp.Value );

            foreach( var kvp in opportunities )
                coordinationOpportunities.Add( kvp.Key, kvp.Value );
        }

        if( HasCapabilityOfActionType( ActionType.Setup, pressureResponses ) )
        {
            var responses = GetSetupResponses( pressureResponses );
            var opportunities = GetSetupOpportunities( capabilitySets );

            foreach( var kvp in responses )
                coordinationResponses.Add( kvp.Key, kvp.Value );

            foreach( var kvp in opportunities )
                coordinationOpportunities.Add( kvp.Key, kvp.Value );
        }

        if( HasCapabilityOfActionType( ActionType.OffensiveStatus, pressureResponses ) )
        {
            var responses = GetOffensiveStatusResponses( pressureResponses );
            var opportunities = GetOffensiveStatusOpportunities( capabilitySets );

            foreach( var kvp in responses )
                coordinationResponses.Add( kvp.Key, kvp.Value );

            foreach( var kvp in opportunities )
                coordinationOpportunities.Add( kvp.Key, kvp.Value );
        }

        if( HasCapabilityOfActionType( ActionType.SupportiveStatus, pressureResponses ) )
        {
            var responses = GetSupportiveStatusResponses( pressureResponses );

            foreach( var kvp in responses )
                coordinationResponses.Add( kvp.Key, kvp.Value );

            var opportunities = GetSupportiveStatusOpportunities( capabilitySets );

            foreach( var kvp in opportunities )
                coordinationOpportunities.Add( kvp.Key, kvp.Value );
        }

        if( HasCapabilityOfActionType( ActionType.Protect, pressureResponses ) )
        {
            var responses = GetProtectResponses( pressureResponses );

            foreach( var kvp in responses )
                coordinationResponses.Add( kvp.Key, kvp.Value );

            var opportunities = GetProtectOpportunities( capabilitySets );

            foreach( var kvp in opportunities )
                coordinationResponses.Add( kvp.Key, kvp.Value );
        }

        static Dictionary<CoordinationAction, CoordinationActionScores> TakeTopThree( Dictionary<CoordinationAction, CoordinationActionScores> cooardinationActions )
        {
            int unit1Count = 0;
            int unit2Count = 0;

            Pokemon unit1 = null;
            Pokemon unit2 = null;

            Dictionary<CoordinationAction, CoordinationActionScores> topThree = new();

            var sortedForPicking = cooardinationActions.OrderByDescending( kvp => kvp.Value.FinalScore ).ToDictionary( kvp => kvp.Key, kvp => kvp.Value );

            //--Take Top 2 for Unit 1
            foreach( var kvp in sortedForPicking )
            {
                var action = kvp.Key;
                var scores = kvp.Value;

                var mon = action.Actor;

                unit1 ??= mon;

                if( mon != unit1 )
                    continue;

                if( unit1Count < 3 )
                {
                    topThree.Add( action, scores );
                    unit1Count++;
                }
                else
                    break;
            }

            //--Take Top 2 for Unit 2
            foreach( var kvp in sortedForPicking )
            {
                var action = kvp.Key;
                var scores = kvp.Value;

                var mon = action.Actor;

                if( mon == unit1 )
                    continue;

                unit2 ??= mon;

                if( mon != unit2 )
                    continue;

                if( unit2Count < 3 )
                {
                    topThree.Add( action, scores );
                    unit2Count++;
                }
                else
                    break;
            }

            return topThree;
        }

        coordinationResponses = TakeTopThree( coordinationResponses );
        coordinationOpportunities = TakeTopThree( coordinationOpportunities );

        Dictionary<CoordinationAction, CoordinationActionScores> finalSort = new();

        foreach( var kvp in coordinationResponses )
            finalSort.Add( kvp.Key, kvp.Value );

        foreach( var kvp in coordinationOpportunities )
            finalSort.Add( kvp.Key, kvp.Value );

        finalSort = finalSort.OrderByDescending( kvp => kvp.Value.FinalScore ).ToDictionary( kvp => kvp.Key, kvp => kvp.Value );

        cirLog.Add( $"" );
        cirLog.Add( $"================================" );
        cirLog.Add( $"=====[Coordination Actions]=====" );
        cirLog.Add( $"================================" );
        cirLog.Add( $"" );
        cirLog.Add( $"Coordination Response Candidate Count: {finalSort.Count}" );
        foreach( var kvp in finalSort )
        {
            var coordAction = kvp.Key;
            var scores = kvp.Value;

            cirLog.Add( $"===[{coordAction.Type} Capability: {coordAction.Capability}]===" );
            cirLog.Add( $"" );
            cirLog.Add( $"Action Type: {coordAction.Action}" );
            cirLog.Add( $"Actor: {coordAction.Actor.NickName}" );
            cirLog.Add( $"Target: {coordAction.Target.NickName}" );
            cirLog.Add( $"Move: {coordAction.MoveCandidate?.MoveSO.Name}" );
            cirLog.Add( $"Switch Candidate: {coordAction.SwitchCandidate?.NickName}" );
            cirLog.Add( $"" );

            if( coordAction.Type == CoordinationActionType.Response )
            {
                cirLog.Add( $"Relevant Pressures" );
                foreach( var spe in coordAction.RelevantPressures )
                    cirLog.Add( $"{spe.Pressure}" );
            }

            if( coordAction.Action == ActionType.DefensiveSwitch || coordAction.Action == ActionType.OffensiveSwitch )
            {
                cirLog.Add( $"" );
                cirLog.Add( $"Defensive Alignment: {scores.DefensiveAlignment}" );
                cirLog.Add( $"Offensive Alignment: {scores.OffensiveAlignment}" );
            }

            cirLog.Add( $"" );
            if( coordAction.Type == CoordinationActionType.Opportunity )
                cirLog.Add( $"Creation Score: {scores.PressureFitScore}" );
            else
                cirLog.Add( $"Pressure Fit Score: {scores.PressureFitScore}" );

            cirLog.Add( $"Board Fit Score: {scores.BoardFitScore}" );
            cirLog.Add( $"Unit Fit Score: {scores.UnitFitScore}" );
            cirLog.Add( $"Plan Fit Score: {scores.PlanFitScore}" );
            cirLog.Add( $"Cost/Risk Score: {scores.CostRiskScore}" );
            cirLog.Add( $"" );
            cirLog.Add( $"Final Score: {scores.FinalScore}" );
            cirLog.Add( $"" );
            cirLog.Add( $"================================" );
            cirLog.Add( $"================================" );
            cirLog.Add( $"================================" );
            cirLog.Add( $"" );
            cirLog.Add( $"" );
        }

        cirLog.Add( $"" );
        cirLog.Add( $"=================================" );
        cirLog.Add( $"=====[Building Action Pairs]=====" );
        cirLog.Add( $"=================================" );
        cirLog.Add( $"" );

        var actionPairs = BuildActionPairs( finalSort.Keys.ToList(), cirLog );

        if( actionPairs == null || actionPairs?.Count <= 0 )
        {
            Debug.LogError( $"We have no legal pairs! Relying entirely on local scoring..." );
            //--build jobs where there's a target pulled from the highest scoring action candidate but no actual job action
            //--so that the ai has a target to build a local decision from
        }

        cirLog.Add( $"================================" );
        cirLog.Add( $"================================" );
        cirLog.Add( $"================================" );
        cirLog.Add( $"" );
        cirLog.Add( $"" );

        foreach( var pair in actionPairs )
        {
            FindSynergies( pair.Unit1Action, pair.Unit2Action, pair );
            FindSynergies( pair.Unit2Action, pair.Unit1Action, pair );
        }

        cirLog.Add( $"" );
        cirLog.Add( $"=================================" );
        cirLog.Add( $"=====[Action Pair Synergies]=====" );
        cirLog.Add( $"=================================" );
        cirLog.Add( $"" );
        foreach( var pair in actionPairs )
        {
            cirLog.Add( $"Pair: {pair.Unit1Action.Actor?.NickName} ({pair.Unit1Action.Capability}), {pair.Unit2Action.Actor?.NickName} ({pair.Unit2Action.Capability})" );
            cirLog.Add( $"" );
            cirLog.Add( $"Synergies:" );
            cirLog.Add( $"" );
            foreach( var synergy in pair.Synergies )
                cirLog.Add( $"{synergy}" );

            cirLog.Add( $"================================" );
            cirLog.Add( $"================================" );
            cirLog.Add( $"================================" );
            cirLog.Add( $"" );
            cirLog.Add( $"" );
        }

        string path = Application.persistentDataPath + "/Strategy Pressure_Log.txt";
        System.IO.File.AppendAllText( path, cirLog.ToString() + "\n" + "\n" + "\n" + "\n" + "\n" );
        cirLog.Clear();

        Dictionary<Pokemon, CurrentJob> jobs = new()
        {
            { ourActive[0].Pokemon, CreateJob( finalSort.First( kvp => kvp.Key.Actor == ourActive[0].Pokemon ).Key, pir.PrimaryStrategy ) },
            { ourActive[1].Pokemon, CreateJob( finalSort.First( kvp => kvp.Key.Actor == ourActive[1].Pokemon ).Key, pir.PrimaryStrategy ) },
        };

        return new()
        {
            Jobs = jobs.ToDictionary( kvp => kvp.Key, kvp => kvp.Value ),
            Pir = pir,
            Active = true,
        };
    }

    private CurrentJob CreateJob( CoordinationAction candidate, PairStrategyIntent psi )
    {
        return new()
        {
            Active                  = true,

            Actor                   = candidate.Actor,
            ActionType              = candidate.Action,
            Move                    = candidate.MoveCandidate,
            SwitchCandidate         = candidate.SwitchCandidate,

            Target                  = candidate.Target,
            TargetsAction           = candidate.TargetsAction,
            TargetsActionResult     = GetOpponentActionResult_FromStrategy( candidate.Target, psi ),
            TargetsMove             = candidate.TargetsMove,
            TargetsSwitchCandidate  = candidate.TargetsSwitchCandidate,

            SourceCapability        = candidate.Capability,
            CoveredPressures        = candidate.RelevantPressures,
        };
    }

    private List<CoordinationActionPair> BuildActionPairs( List<CoordinationAction> actions, CustomLogSession log = null )
    {
        Dictionary<Pokemon, List<CoordinationAction>> assignments = new();

        log?.Add( $"Total action count: {actions.Count}" );
        log?.Add( $"" );

        Pokemon unit1 = null;
        Pokemon unit2 = null;

        foreach( var a in actions )
        {
            if( unit1 == null )
                unit1 = a.Actor;
            else if( unit1 != null && unit1 != a.Actor && unit2 == null )
                unit2 = a.Actor;

            if( assignments.TryGetValue( a.Actor, out var ca ) )
                ca.Add( a );
            else
                assignments.Add( a.Actor, new(){ a } );
        }

        List<CoordinationAction> unit1Actions = new();
        List<CoordinationAction> unit2Actions = new();

        bool unit1Exists = false;
        bool unit2Exists = false;

        log?.Add( $"=============================================" );
        log?.Add( $"=====[Merging Responses & Opportunities]=====" );
        log?.Add( $"=============================================" );
        log?.Add( $"" );

        if( assignments.TryGetValue( unit1, out unit1Actions ) )
        {
            unit1Exists = true;
            log?.Add( $"Unit 1 is: {unit1.NickName}, with {unit1Actions.Count} actions found. Beginning to find actions to merge..." );
            log?.Add( $"" );
            log?.Add( $"" );
            unit1Actions = MergeActions( unit1, unit1Actions, log );
            log?.Add( $"" );
            log?.Add( $"" );
            log?.Add( $"Unit 1 is: {unit1.NickName}, with {unit1Actions.Count} actions after attempting to merge." );
            log?.Add( $"" );
            log?.Add( $"" );
        }

        if( assignments.TryGetValue( unit2, out unit2Actions ) )
        {
            unit2Exists = true;
            log?.Add( $"Unit 2 is: {unit2.NickName}, with {unit2Actions.Count} actions found. Beginning to find actions to merge..." );
            log?.Add( $"" );
            log?.Add( $"" );
            unit2Actions = MergeActions( unit2, unit2Actions, log );
            log?.Add( $"" );
            log?.Add( $"" );
            log?.Add( $"Unit 2 is: {unit2.NickName}, with {unit2Actions.Count} actions after attempting to merge." );
            log?.Add( $"" );
            log?.Add( $"" );
        }

        if( !unit1Exists || !unit2Exists )
        {
            Debug.LogError( $"Units not assigned properly, wtf happened dawg this shit suck" );
            log?.Add( $"Units not assigned properly, wtf happened dawg this shit suck" );
        }

        List<CoordinationActionPair> actionPairs = new();
        foreach( var a1 in unit1Actions )
        {
            foreach( var a2 in unit2Actions )
            {
                bool a1switch = a1.Action == ActionType.DefensiveSwitch || a1.Action == ActionType.OffensiveSwitch;
                bool a2switch = a2.Action == ActionType.DefensiveSwitch || a1.Action == ActionType.OffensiveSwitch;

                if( a1switch && a2switch )
                {
                    if( a1.SwitchCandidate != null && a2.SwitchCandidate != null && a1.SwitchCandidate == a2.SwitchCandidate )
                        continue;
                }

                bool a1helpingyou = a1.Capability == CapabilityObservation.HelpingHand || a1.Capability == CapabilityObservation.AfterYou;
                bool a2helpingyou = a2.Capability == CapabilityObservation.HelpingHand || a2.Capability == CapabilityObservation.AfterYou;

                if( ( a1helpingyou && a2switch ) || ( a2helpingyou && a1switch ) )
                    continue;

                bool a1attack = a1.Action == ActionType.Attack;
                bool a2attack = a2.Action == ActionType.Attack;

                if( ( a1.Capability == CapabilityObservation.HelpingHand && !a2attack ) || ( a2.Capability == CapabilityObservation.HelpingHand && !a1attack ) )
                    continue;

                CoordinationActionPair pair = new()
                {
                    Unit1Action = a1,
                    Unit2Action = a2,
                    Synergies = new(),
                };

                actionPairs.Add( pair );
            }
        }

        log?.Add( $"Total Action Pairs: {actionPairs.Count}" );
        log?.Add( $"" );
        foreach( var pair in actionPairs )
        {
            log?.Add( $"Unit 1: Actor {pair.Unit1Action.Actor.NickName}, Capability {pair.Unit1Action.Capability}" );
            log?.Add( $"" );
            log?.Add( $"Unit 2 Actor {pair.Unit2Action.Actor.NickName}, Capability {pair.Unit2Action.Capability}" );
            log?.Add( $"" );
        }

        return actionPairs;
    }

    private List<CoordinationAction> MergeActions( Pokemon pokemon, List<CoordinationAction> actions, CustomLogSession log = null )
    {
        List<CoordinationAction> merged = new();
        List<CoordinationAction> responses = new();
        List<CoordinationAction> opportunities = new();
        List<CoordinationAction> removal = new();

        foreach( var a in actions )
        {
            if( a.Type == CoordinationActionType.Response )
                responses.Add( a );
            else if( a.Type == CoordinationActionType.Opportunity )
                opportunities.Add( a );
            else
                Debug.LogError( $"You fucka up" );
        }

        log?.Add( $"Searching for Responses and Opportunities to merge for actor {pokemon.NickName}..." );
        log?.Add( $"" );

        foreach( var r in responses )
        {
            if( r.Remove )
                continue;

            foreach( var o in opportunities )
            {
                if( o.Remove )
                    continue;

                bool capabilityMatch = r.Capability == o.Capability;
                bool actorMatch = r.Actor == o.Actor;
                bool targetMatch = r.Target == o.Target;
                bool switchCandidateMatch = r.SwitchCandidate != null && o.SwitchCandidate != null && r.SwitchCandidate == o.SwitchCandidate;
                bool bothAreSwitchActions = ( r.Action == ActionType.DefensiveSwitch && o.Action == ActionType.DefensiveSwitch ) || ( r.Action == ActionType.OffensiveSwitch && o.Action == ActionType.OffensiveSwitch );
                
                bool switchActionFitForMerging = bothAreSwitchActions && switchCandidateMatch;
                bool moveActionFitForMerging = capabilityMatch && actorMatch && targetMatch;

                if( switchActionFitForMerging || moveActionFitForMerging )
                {
                    log?.Add( $"" );
                    log?.Add( $"Switch Match: {switchActionFitForMerging}, Move Match: {moveActionFitForMerging}" );
                    log?.Add( $"" );
                    log?.Add( $"Types: {r.Type}, {o.Type}" );
                    log?.Add( $"" );
                    log?.Add( $"Actor: {r.Actor?.NickName}, {o.Actor?.NickName}" );
                    log?.Add( $"Action: {r.Action}, {o.Action}" );
                    log?.Add( $"Move: {r.MoveCandidate?.MoveSO.Name}, {o.MoveCandidate?.MoveSO.Name}" );
                    log?.Add( $"Switch: {r.SwitchCandidate?.NickName}, {o.SwitchCandidate?.NickName}" );
                    log?.Add( $"" );
                    log?.Add( $"Target: {r.Target?.NickName}, {o.Target?.NickName}" );
                    log?.Add( $"Targets Action: {r.TargetsAction}, {o.TargetsAction}" );
                    log?.Add( $"Targets Move: {r.TargetsMove?.MoveSO.Name}, {o.TargetsMove?.MoveSO.Name}" );

                    if( r.TargetsSwitchCandidate != null && o.TargetsSwitchCandidate != null )
                        log?.Add( $"Targets Switch: {r.TargetsSwitchCandidate}, {o.TargetsSwitchCandidate}" );

                    log?.Add( $"" );
                    log?.Add( $"Capability: {r.Capability}, {o.Capability}" );
                    log?.Add( $"" );

                    CoordinationAction mergedAction = new()
                    {
                        Type = CoordinationActionType.Merged,

                        Actor = r.Actor ?? null,
                        Action = r.Action,
                        MoveCandidate = r.MoveCandidate ?? null,
                        SwitchCandidate = r.SwitchCandidate ?? null,

                        Target = r.Target ?? null,
                        TargetsAction = r.TargetsAction,
                        TargetsMove = r.TargetsMove ?? null,
                        TargetsSwitchCandidate = r.TargetsSwitchCandidate ?? null,

                        Capability = r.Capability,
                        RelevantPressures = r.RelevantPressures != null ? r.RelevantPressures.ToHashSet() : new(),
                    };

                    merged.Add( mergedAction );

                    removal.Add( r );
                    removal.Add( o );

                    log?.Add( $"" );
                    log?.Add( $"" );
                    log?.Add( $"" );
                }
            }
        }

        foreach( var action in actions )
        {
            if( removal.Contains( action ) )
                continue;
            else
                merged.Add( action );
        }

        return merged;
    }

    private bool TryGetObservationProfile( PairObservationEvidence evidence, PairObservation observation, out PairObservationProfile profile )
    {
        if( evidence.Type == observation )
        {
            profile = ExtractObservationProfile( evidence );
            return true;
        }
        else
        {
            profile = default;
            return false;
        }
    }

    private PairObservationProfile ExtractObservationProfile( PairObservationEvidence evidence )
    {
        var intentResult = evidence.IsPrimary ? evidence.SourceIntent.PrimaryIntent.IntentResult : evidence.SourceIntent.SecondaryIntent.IntentResult;
        var top = intentResult.Top;
        var us = top.Opponent;
        var ourAlly = _ai.GetActiveAllyAs_Adapter( us.Pokemon );
        var them = top.Attacker;
        var theirAlly = _ai.GetActiveAllyAs_Adapter( them.Pokemon );
        var move = intentResult.Move;

        bool weHaveAlly = ourAlly != null;
        bool theyHaveAlly = theirAlly != null;

        return new()
        {
            IntentResult = intentResult,
            Top = top,
            Us = us,
            OurAlly = ourAlly,
            Them = them,
            TheirAlly = theirAlly,
            Move = move,
            WeHaveAlly = weHaveAlly,
            TheyHaveAlly = theyHaveAlly,
        };
    }

#region "Gather Pressure Responses"

    private Dictionary<StrategyPressure, StrategyPressureEvidence> GatherPressureResponses( Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets, HashSet<StrategyPressureEvidence> pressures )
    {
        Dictionary<StrategyPressure, StrategyPressureEvidence> pressureResponses = new();

        foreach( var kvp in capabilitySets )
        {
            var pokemon = kvp.Key;
            var capabilities = kvp.Value;

            foreach( var capability in capabilities )
            {
                foreach( var spe in pressures )
                {
                    spe.InitRC();
                    bool addResponse = CheckIfPressureResponse( spe.Pressure, capability );
                    
                    if( addResponse )
                    {
                        if( pressureResponses.TryGetValue( spe.Pressure, out var res ) )
                        {
                            if( res.ResponseCapabilities.TryGetValue( pokemon, out var obvs ) )
                            {
                                obvs.Add( capability );
                            }
                            else
                            {
                                res.ResponseCapabilities.Add( pokemon, new(){ capability } );
                            }
                        }
                        else
                        {
                            pressureResponses.Add( spe.Pressure, spe );
                            spe.ResponseCapabilities.Add( pokemon, new(){ capability } );
                        }
                    }
                }
            }
        }

        return pressureResponses;
    }

    private bool CheckIfPressureResponse( StrategyPressure pressure, CapabilityObservation observation )
    {
        return pressure switch
        {
            StrategyPressure.WeatherChange => CheckIfWeatherChangeResponse( observation ),
            StrategyPressure.PreserveUnit => CheckIfPreserveUnitResponse( observation ),
            StrategyPressure.EnableSafePivot => CheckIfEnableSafePivotResponse( observation ),
            StrategyPressure.MaintainMomentum => CheckIfMaintainMomentumResponse( observation ),
            StrategyPressure.EstablishSpeedControl => CheckIfEstablishSpeedControlResponse( observation ),
            StrategyPressure.EnableSafeSetup => CheckIfEnableSafeSetupResponse( observation ),
            StrategyPressure.ProtectSetter => CheckIfProtectSetterResponse( observation ),
            StrategyPressure.SetupMomentum => CheckIfSetupMomentumResponse( observation ),
            StrategyPressure.ImmediateRemoval => CheckIfImmediateRemovalResponse( observation ),
            StrategyPressure.ConcentrateDamage => CheckIfConcentrateDamageResponse( observation ),
            StrategyPressure.GuaranteeRemoval => CheckIfGuaranteeRemovalResponse( observation ),
            StrategyPressure.PunishWeakTarget => CheckIfPunishWeakTargetResponse( observation ),
            StrategyPressure.ApplyOffensivePressure => CheckIfApplyOffensivePressureResponse( observation ),
            StrategyPressure.ThreatenMultipleLines => CheckIfThreatenMultipleLinesResponse( observation ),
            StrategyPressure.RetainInitiative => CheckIfRetainInitiativeResponse( observation ),
            StrategyPressure.InterruptSetup => CheckIfInterruptSetupResponse( observation ),
            StrategyPressure.DenyResources => CheckIfDenyResourcesResponse( observation ),
            StrategyPressure.ActFirst => CheckIfActFirstResponse( observation ),
            StrategyPressure.ProtectDisruptor => CheckIfProtectDisruptorResponse( observation ),
            StrategyPressure.ReduceIncomingPressure => CheckIfReduceIncomingPressureResponse( observation ),
            StrategyPressure.IncreaseBoardStability => CheckIfIncreaseBoardStabilityResponse( observation ),
            StrategyPressure.ProtectImportantUnit => CheckIfProtectImportantUnitResponse( observation ),
            StrategyPressure.CreateDefensiveResources => CheckIfCreateDefensiveResourcesResponse( observation ),
