    private bool TryGetCapabilityUser( CapabilityObservation capability, Dictionary<StrategyPressure, Dictionary<Pokemon, HashSet<CapabilityObservation>>> pressureSets, out Pokemon user )
    {
        user = null;

        foreach( var set in pressureSets )
        {
            var observations = set.Value;

            foreach( var kvp in observations )
            {
                var mon = kvp.Key;
                var capabilities = kvp.Value;

                if( capabilities.Contains( capability ) )
                {
                    user = mon;
                    return true;
                }
            }
        }

        return false;
    }

    private bool PokemonIsActive( Pokemon pokemon )
    {
        var ourActive = _ai.Blackboard.OurActiveBattleAIUnits;

        foreach( var unit in ourActive )
        {
            if( unit.Pokemon == pokemon )
                return true;
        }

        return false;
    }

    private bool PokemonIsBenched( Pokemon pokemon )
    {
        var ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = _ai.GetRemainingPartyAs_IBattleAIUnits( ourActive[0].Pokemon ).Where( u => !ourActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        foreach( var unit in ourBench )
        {
            if( unit.Pokemon == pokemon )
                return true;
        }

        return false;
    }

    private bool CapabilityIsActiveAbility( CapabilityObservation capability )
    {
        return capability switch
        {
            CapabilityObservation.CloudNine => true,
            CapabilityObservation.Prankster => true,
            CapabilityObservation.AbilityPriorityBlock => true,
            _ => false,
        };
    }

    private bool HasCapabilityOfActionType( ActionType action, Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        foreach( var set in pressureSets )
        {
            var spe = set.Value;
            foreach( var kvp in spe.ResponseCapabilities )
            {
                var capabilities = kvp.Value;
                foreach( var capability in capabilities )
                {
                    if( GetCapabilityActionType( capability ) == action )
                        return true;
                }
            }
        }

        return false;
    }

    private ActionType GetCapabilityActionType( CapabilityObservation capability )
    {
        return capability switch
        {
            //--Attack Action Capabilities
            CapabilityObservation.StrongestAttack   => ActionType.Attack,
            CapabilityObservation.CoverageMove      => ActionType.Attack,
            CapabilityObservation.FakeOut           => ActionType.Attack,
            CapabilityObservation.HybridDebuff      => ActionType.Attack,
            CapabilityObservation.KnockOff          => ActionType.Attack,
            CapabilityObservation.ThroatChop        => ActionType.Attack,
            CapabilityObservation.PivotMove         => ActionType.Attack,
            CapabilityObservation.TrapMove          => ActionType.Attack,
            CapabilityObservation.BrickBreak        => ActionType.Attack,
            CapabilityObservation.PsychicFangs      => ActionType.Attack,
            CapabilityObservation.RapidSpin         => ActionType.Attack,
            CapabilityObservation.MortalSpin        => ActionType.Attack,

            //--Switch Action Capabilities. We'll group Defensive and Offensive Switch together here as a "switch action", and let the nuance during scoring determine which one we'll use
            CapabilityObservation.RawSwitch => ActionType.DefensiveSwitch,
            CapabilityObservation.AbilityPriorityBlock => ActionType.DefensiveSwitch,
            CapabilityObservation.Intimidate => ActionType.DefensiveSwitch,
            CapabilityObservation.Demoralize => ActionType.DefensiveSwitch,
            CapabilityObservation.WeatherSetAbility => ActionType.DefensiveSwitch,
            CapabilityObservation.TerrainSetAbility => ActionType.DefensiveSwitch,
            CapabilityObservation.BatonPass => ActionType.DefensiveSwitch,
            CapabilityObservation.TrapAbility => ActionType.DefensiveSwitch,
            CapabilityObservation.CloudNine => ActionType.DefensiveSwitch,
            CapabilityObservation.Hospitality => ActionType.DefensiveSwitch,

            //--Setup Action Capabilities
            CapabilityObservation.StatBoost => ActionType.Setup,
            CapabilityObservation.Substitute => ActionType.Setup,

            //--Offensive Status Action Capabilities
            CapabilityObservation.Taunt => ActionType.OffensiveStatus,
            CapabilityObservation.Encore => ActionType.OffensiveStatus,
            CapabilityObservation.Disable => ActionType.OffensiveStatus,
            CapabilityObservation.Torment => ActionType.OffensiveStatus,
            CapabilityObservation.Imprison => ActionType.OffensiveStatus,
            CapabilityObservation.Phazing => ActionType.OffensiveStatus,
            CapabilityObservation.Wisp => ActionType.OffensiveStatus,
            CapabilityObservation.Hoarfrost => ActionType.OffensiveStatus,
            CapabilityObservation.Paralysis => ActionType.OffensiveStatus,
            CapabilityObservation.Sleep => ActionType.OffensiveStatus,
            CapabilityObservation.Poison => ActionType.OffensiveStatus,
            CapabilityObservation.Toxic => ActionType.OffensiveStatus,
            CapabilityObservation.StatDebuff => ActionType.OffensiveStatus,
            CapabilityObservation.HazardSetting => ActionType.OffensiveStatus,
            CapabilityObservation.Quash => ActionType.OffensiveStatus,

            //--Supportive Status Action Capabilities
            CapabilityObservation.Redirection => ActionType.SupportiveStatus,
            CapabilityObservation.Reflect => ActionType.SupportiveStatus,
            CapabilityObservation.LightScreen => ActionType.SupportiveStatus,
            CapabilityObservation.AuroraVeil => ActionType.SupportiveStatus,
            CapabilityObservation.WeatherSetMove => ActionType.SupportiveStatus,
            CapabilityObservation.TerrainSetMove => ActionType.SupportiveStatus,
            CapabilityObservation.Tailwind => ActionType.SupportiveStatus,
            CapabilityObservation.TrickRoom => ActionType.SupportiveStatus,
            CapabilityObservation.StatReset => ActionType.SupportiveStatus,
            CapabilityObservation.TidyUp => ActionType.SupportiveStatus,
            CapabilityObservation.SubstituteBypass => ActionType.SupportiveStatus,
            CapabilityObservation.Defog => ActionType.SupportiveStatus,
            CapabilityObservation.AllySwitch => ActionType.SupportiveStatus,
            CapabilityObservation.HelpingHand => ActionType.SupportiveStatus,
            CapabilityObservation.AfterYou => ActionType.SupportiveStatus,
            CapabilityObservation.SideHeal => ActionType.SupportiveStatus,

            _ => default,
        };
    }

    private bool IsSwitchBasedPressure( StrategyPressure pressure )
    {
        switch( pressure )
        {
            case StrategyPressure.PreserveUnit:
                return true;

            case StrategyPressure.WeatherChange:
                if( OpponentPrimaryStrategy.Strategy == PairStrategy.WeatherPivot )
                    return true;
                else
                    return false;
            
            
            default: return false;
        }
    }

    private bool TryExtractSwitchBasedPressures( HashSet<StrategyPressureEvidence> pressures, out HashSet<StrategyPressureEvidence> switchBasedPressures )
    {
        switchBasedPressures = new();
        foreach( var spe in pressures )
        {
            if( IsSwitchBasedPressure( spe.Pressure ) )
                switchBasedPressures.Add( spe );
        }

        return switchBasedPressures.Count > 0;
    }

    private bool StrategyPressureEvidenceContainsPressure( StrategyPressure pressure, HashSet<StrategyPressureEvidence> spe )
    {
        foreach( var e in spe )
        {
            if( e.Pressure == pressure )
                return true;
        }

        return false;
    }

    private bool CheckIfActionAnswersPressure( ActionType action, StrategyPressure pressure )
    {
        switch( action )
        {
            case ActionType.Attack:

                bool fakeOut = CheckIfPressureResponse( pressure, CapabilityObservation.FakeOut );
                bool knockOff = CheckIfPressureResponse( pressure, CapabilityObservation.KnockOff );
                bool throatChop = CheckIfPressureResponse( pressure, CapabilityObservation.ThroatChop );
                bool brickBreak = CheckIfPressureResponse( pressure, CapabilityObservation.BrickBreak );
                bool psychicFangs = CheckIfPressureResponse( pressure, CapabilityObservation.PsychicFangs );

                if( fakeOut || knockOff || throatChop || brickBreak || psychicFangs )
                    return true;
                else
                    return false;
        }

        return false;
    }

    private bool CheckIfPokemonHasRelevantSwitchCapability( Pokemon pokemon, Dictionary<CapabilityObservation, HashSet<StrategyPressureEvidence>> activeCapabilitySets )
    {
        foreach( var kvp in activeCapabilitySets )
        {
            var capability = kvp.Key;
            var pressureSets = kvp.Value;

            if( GetCapabilityActionType( capability ) != ActionType.DefensiveSwitch )
                continue;

            foreach( var spe in pressureSets )
            {
                if( spe.ResponseCapabilities.TryGetValue( pokemon, out var capabilities ) )
                {
                    if( capabilities.Contains( capability ) )
                        return true;
                }
            }
        }

        return false;
    }

    private bool CheckIfPokemonHasSpecificCapability( Pokemon pokemon, CapabilityObservation capability, Dictionary<CapabilityObservation, HashSet<StrategyPressureEvidence>> capabilitySets )
    {
        foreach( var kvp in capabilitySets )
        {
            var pressureSets = kvp.Value;

            foreach( var spe in pressureSets )
            {
                if( spe.ResponseCapabilities.TryGetValue( pokemon, out var capabilities ) )
                {
                    if( capabilities.Contains( capability ) )
                        return true;
                }
            }
        }

        return false;
    }

    private bool CheckIfPokemonHasSpecificCapability( Pokemon pokemon, CapabilityObservation capability, Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets )
    {
        if( capabilitySets.TryGetValue( pokemon, out var capabilities ) && capabilities.Contains( capability ) )
            return true;
        else
            return false;
    }
    private Dictionary<CapabilityObservation, HashSet<StrategyPressureEvidence>> ExtractUniqueCapabilities( ActionType action, Pokemon pokemon, Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        Dictionary<CapabilityObservation, HashSet<StrategyPressureEvidence>> capabilitySets = new();

        foreach( var set in pressureSets )
        {
            var pressure = set.Key;
            var spe = set.Value;

            foreach( var kvp in spe.ResponseCapabilities )
            {
                var mon = kvp.Key;
                var responses = kvp.Value;

                if( mon != pokemon )
                    continue;

                foreach( var capability in responses )
                {
                    // Debug.LogError( $"Found {capability}" );
                    //--Need to exclude all irrelevant capabilities to a given action!
                    if( GetCapabilityActionType( capability ) != action )
                        continue;

                    if( capabilitySets.TryGetValue( capability, out var pressures ) )
                    {
                        pressures.Add( spe );
                    }
                    else
                    {
                        capabilitySets.Add( capability, new(){ spe } );
                    }
                }
            }

            switch( action )
            {
                case ActionType.Attack:

                    if( _ai.UnitSim.PokemonHasMove_DamagingAttack( pokemon ) )
                    {
                        if( CheckIfActionAnswersPressure( ActionType.Attack, pressure ) )
                        {
                            if( capabilitySets.TryGetValue( CapabilityObservation.StrongestAttack, out var strongestAttack ) )
                                strongestAttack.Add( spe );
                            else
                                capabilitySets.Add( CapabilityObservation.StrongestAttack, new(){ spe } );
                        }

                        foreach( var kvp in spe.ResponseCapabilities )
                        {
                            if( IsSwitchBasedPressure( pressure ) )
                            {
                                if( capabilitySets.TryGetValue( CapabilityObservation.CoverageMove, out var coverageMove ) )
                                    coverageMove.Add( spe );
                                else
                                    capabilitySets.Add( CapabilityObservation.CoverageMove, new(){ spe } );
                            }
                        }
                    }

                break;

                case ActionType.OffensiveSwitch:
                case ActionType.DefensiveSwitch:

                    if( pokemon.BindingStatuses?.Count <= 0 )
                    {
                        if( capabilitySets.TryGetValue( CapabilityObservation.RawSwitch, out var rawSwitch ) )
                            rawSwitch.Add( spe );
                        else
                            capabilitySets.Add( CapabilityObservation.RawSwitch, new(){ spe } );
                    }

                break;

                case ActionType.Setup:

                    if( _ai.UnitSim.GetSetupMoves( pokemon.ActiveMoves ).Count > 0 )
                    {
                        if( capabilitySets.TryGetValue( CapabilityObservation.StatBoost, out var statBuff ) )
                            statBuff.Add( spe );
                        else
                            capabilitySets.Add( CapabilityObservation.StatBoost, new(){ spe } );
                    }
                    
                break;
            }
        }

        return capabilitySets;
    }
    private Dictionary<Pokemon, HashSet<CapabilityObservation>> ExtractBaseCapabilities( ActionType action, Pokemon pokemon )
    {
        Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets = new();

        switch( action )
        {
            case ActionType.Attack:

                if( _ai.UnitSim.PokemonHasMove_DamagingAttack( pokemon ) )
                {
                    if( capabilitySets.TryGetValue( pokemon, out var attackCapabilities ) )
                        attackCapabilities.Add( CapabilityObservation.StrongestAttack );
                    else
                        capabilitySets.Add( pokemon, new(){ CapabilityObservation.StrongestAttack } );
                }

                if( _ai.UnitSim.PokemonHasMove_Coverage( pokemon ) )
                {
                    if( capabilitySets.TryGetValue( pokemon, out var attackCapabilities ) )
                        attackCapabilities.Add( CapabilityObservation.CoverageMove );
                    else
                        capabilitySets.Add( pokemon, new(){ CapabilityObservation.CoverageMove } );
                }

            break;

            case ActionType.OffensiveSwitch:
            case ActionType.DefensiveSwitch:

                if( pokemon.BindingStatuses?.Count <= 0 )
                {
                    if( capabilitySets.TryGetValue( pokemon, out var switchCapabilities ) )
                        switchCapabilities.Add( CapabilityObservation.RawSwitch );
                    else
                        capabilitySets.Add( pokemon, new(){ CapabilityObservation.RawSwitch } );
                }

            break;

            case ActionType.Setup:

                if( _ai.UnitSim.GetSetupMoves( pokemon.ActiveMoves ).Count > 0 )
                {
                    if( capabilitySets.TryGetValue( pokemon, out var statBuffs ) )
                        statBuffs.Add( CapabilityObservation.StatBoost );
                    else
                        capabilitySets.Add( pokemon, new(){ CapabilityObservation.StatBoost } );
                }
                
            break;
        }

        return capabilitySets;
    }

    private bool TryExtractMoveFromPokemon( string name, IBattleAIUnit unit, out Move extractedMove )
    {
        extractedMove = null;
        foreach( var move in unit.ActiveMoves )
        {
            if( move.MoveSO.Name == name )
            {
                extractedMove = move;
                return true;
            }
        }

        return false;
    }

    private EstimatedDamageResult GetEDROnSwitchCandidate( IBattleAIUnit attacker, IBattleAIUnit switchCandidate, Move attackerMove )
    {
        var attackerAlly = _ai.GetActiveAllyAs_Adapter( attacker.Pokemon );
        var switchesAlly = _ai.GetActiveAllyAs_Adapter( switchCandidate.Pokemon );

        List<IBattleAIUnit> targets = new(){ switchCandidate };
        int targetCount = 1;
        if( attackerMove.MoveSO.MoveTarget == MoveTarget.OpposingSide && switchesAlly != null )
        {
            targetCount = 2;
            targets.Add( switchesAlly );
        }

        if( attackerMove.MoveSO.MoveTarget == MoveTarget.AllAdjacent )
        {
            if( attackerAlly != null )
            {
                targetCount++;
                targets.Add( attackerAlly );
            }

            if( switchesAlly != null )
            {
                targetCount++;
                targets.Add( switchesAlly );
            }
        }

        float modifier = _ai.UnitSim.Get_MoveEffectiveness( switchCandidate, attackerMove ) * _ai.UnitSim.Get_MoveModifier( attacker, switchCandidate, attackerMove );
        MoveThreatResult mtr = new(){ Score = 0, Modifier = modifier, Move = attackerMove, TargetCount = targetCount, Targets = targets };

        return _ai.Projection.Get_EstimatedDamageResult( attacker, switchCandidate, mtr );
    }

    private List<IBattleAIUnit> GetPokemonBench( Pokemon pokemon )
    {
        var active = _ai.GetActiveAllyUnits_AsBattleAIUnits( pokemon );
        var bench = _ai.GetRemainingPartyAs_IBattleAIUnits( active[0].Pokemon ).Where( u => !active.Any( a => a.Pokemon == u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        return bench;
    }

    private bool TryGetAlly( Pokemon pokemon, out IBattleAIUnit ally )
    {
        var tryAlly = _ai.GetActiveAllyAs_Adapter( pokemon );

        if( tryAlly != null )
        {
            ally = tryAlly;
            return true;
        }
        else
        {
            ally = null;
            return false;
        }
    }

    private bool TryGetOpponentAlly_FromStrategy( Pokemon pokemon, StrategyPressureEvidence spe, out IBattleAIUnit ally )
    {
        var leftOpponent = spe.SourceStrategy != null ? spe.SourceStrategy?.LeftIntent.IntentResult?.Top.Attacker?.Pokemon : OpponentPrimaryStrategy?.LeftIntent.IntentResult?.Top.Attacker?.Pokemon;
        var rightOpponent = spe.SourceStrategy != null ? spe.SourceStrategy?.RightIntent.IntentResult?.Top.Attacker?.Pokemon : OpponentPrimaryStrategy?.RightIntent.IntentResult?.Top.Attacker?.Pokemon;

        if( leftOpponent == null || rightOpponent == null )
        {
            ally = null;
            return false;
        }

        if( pokemon != leftOpponent && pokemon == rightOpponent )
        {
            ally = _ai.GetPokemonAs_IBattleAIUnit( leftOpponent );
            return true;
        }
        else if( pokemon != rightOpponent && pokemon == leftOpponent )
        {
            ally = _ai.GetPokemonAs_IBattleAIUnit( rightOpponent );
            return true;
        }
        else
        {
            ally = null;
            return false;
        }
    }

    private bool TryGetOpponentAllyIntent_FromStrategy( Pokemon pokemon, StrategyPressureEvidence spe, out Intent intent )
    {
        var leftOpponent = spe.SourceStrategy != null ? spe.SourceStrategy?.LeftIntent.IntentResult?.Top.Attacker?.Pokemon : OpponentPrimaryStrategy?.LeftIntent.IntentResult?.Top.Attacker?.Pokemon;
        var rightOpponent = spe.SourceStrategy != null ? spe.SourceStrategy?.RightIntent.IntentResult?.Top.Attacker?.Pokemon : OpponentPrimaryStrategy?.RightIntent.IntentResult?.Top.Attacker?.Pokemon;

        if( leftOpponent == null || rightOpponent == null )
        {
            intent = default;
            return false;
        }

        if( pokemon != leftOpponent && pokemon == rightOpponent )
        {
            intent = spe.SourceStrategy.LeftIntent;
            return true;
        }
        else if( pokemon != rightOpponent && pokemon == leftOpponent )
        {
            intent = spe.SourceStrategy.RightIntent;
            return true;
        }
        else
        {
            intent = default;
            return false;
        }
    }

    private IActionResult GetOpponentActionResult_FromStrategy( Pokemon pokemon, PairStrategyIntent psi )
    {
        var left = psi.LeftIntent;
        var right = psi.RightIntent;

        if( psi.LeftIntent.IntentResult == null )
            Debug.LogError( $"Left Intent is Null in PSI!!" );

        if( psi.RightIntent.IntentResult == null )
            Debug.LogError( $"Right Intent is Null in PSI!!" );

        if( left.IntentResult?.CurrentActor.Pokemon == pokemon )
            return left.IntentResult;
        else if( right.IntentResult?.CurrentActor.Pokemon == pokemon )
            return right.IntentResult;

        Debug.LogError( $"No Intent Result Found in Pair Strategy Intent!!!" );

        return null;
    }

    private struct TurnOrderCommand
    {
        public int MovePriority;
        public bool AfterYou;
        public bool Quash;
    }

    private Dictionary<Pokemon, int> GetTurnOrder( Dictionary<IBattleAIUnit, Move> units, StrategyPressureEvidence spe, SimulatedField field )
    {
        const int priorityOffset = 7;

        Dictionary<IBattleAIUnit, TurnOrderCommand> orderInfo = new();

        spe.TryGet_AfterYouInfo( out IBattleAIUnit afterYouTarget );
        spe.TryGet_QuashInfo( out IBattleAIUnit quashTarget );

        foreach( var kvp in units )
        {
            var unit = kvp.Key;
            var move = kvp.Value;

            int movePriority = move != null ? (int)move.Priority - priorityOffset : 0;

            if( move?.MoveSO.MoveCategory == MoveCategory.Status && unit.Ability == AbilityID.Prankster )
                movePriority += 1;

            TurnOrderCommand toc = new()
            {
                MovePriority = movePriority,
                AfterYou = unit.Pokemon == afterYouTarget?.Pokemon,
                Quash = unit.Pokemon == quashTarget?.Pokemon,
            };

            orderInfo.Add( unit, toc );
        }

        if( field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
            orderInfo = orderInfo.OrderByDescending( kvp => kvp.Value.MovePriority ).ThenByDescending( kvp => kvp.Value.AfterYou ).ThenBy( kvp => kvp.Key.Speed ).ThenByDescending( kvp => kvp.Value.Quash ).ThenBy( kvp => kvp.Key.Speed ).ToDictionary( kvp => kvp.Key, kvp => kvp.Value );
        else
            orderInfo = orderInfo.OrderByDescending( kvp => kvp.Value.MovePriority ).ThenByDescending( kvp => kvp.Value.AfterYou ).ThenByDescending( kvp => kvp.Key.Speed ).ThenByDescending( kvp => kvp.Value.Quash ).ThenByDescending( kvp => kvp.Key.Speed ).ToDictionary( kvp => kvp.Key, kvp => kvp.Value );

        Dictionary<Pokemon, int> turnOrder = new();
        int order = 0;

        foreach( var kvp in orderInfo )
        {
            order++;
            turnOrder.Add( kvp.Key.Pokemon, order );
        }

        return turnOrder;
    }

    private bool MovesBefore( IBattleAIUnit first, IBattleAIUnit second, Dictionary<Pokemon, int> turnOrder )
    {
        if( turnOrder != null && turnOrder.Count > 0 )
        {
            if( turnOrder.TryGetValue( first.Pokemon, out var firstOrder ) && turnOrder.TryGetValue( second.Pokemon, out var secondOrder ) )
            {
                if( firstOrder > secondOrder )
                    return true;
                else
                    return false;
            }
            else if( turnOrder.ContainsKey( first.Pokemon ) && !turnOrder.ContainsKey( second.Pokemon ) )
                return false;
            else if( !turnOrder.ContainsKey( first.Pokemon ) && turnOrder.ContainsKey( second.Pokemon ) )
                return true;
            else
                return false;
        }

        return false;
    }

    private bool MovesFirst( IBattleAIUnit unit, Dictionary<Pokemon, int> turnOrder )
    {
        if( turnOrder != null && turnOrder.Count > 0 )
        {
            if( turnOrder.Keys.First() == unit.Pokemon )
                return true;
            else
                return false;
        }

        return false;
    }

    private InteractionProfile GetInteractionProfile( IBattleAIUnit attacker, IBattleAIUnit target, CoordinationAction actionCandidate, StrategyPressureEvidence spe )
    {   
        //--This builder must be purely descriptive. what can the opponent do overall? what can do that is relevant to the pressure, from our ResponseCapabilities?
        //--Then every candidate check becomes "if they can do x, can we do y" score +/- 1

        if( spe == null )
        {
            var sourceActionResult = GetOpponentActionResult_FromStrategy( target.Pokemon, OpponentPrimaryStrategy );
            spe = new()
            {
                Pressure = StrategyPressure.None,
                SourceStrategy = OpponentPrimaryStrategy,
                SourceAction = sourceActionResult.ActionType,
                SourceActionResult = sourceActionResult,
                ResponseCapabilities = new(),
            };
        }

        var ourRP = attacker.RoleProfile;
        var ourTraits = ourRP.Traits;

        var theirAction = spe.SourceAction;
        var theirActionResult = spe.SourceActionResult;

        var theirRP = target.RoleProfile;
        var theirTraits = theirRP.Traits;

        InteractionFlags weCan = new()
        {
            SetAbilityWeather = _ai.UnitSim.PokemonHasWeatherSetter_Ability( attacker.Pokemon ),
            SetMoveWeather = _ai.UnitSim.PokemonHasWeatherSetter_Move( attacker.Pokemon ),
            SetAbilityTerrain = _ai.UnitSim.PokemonHasTerrainSetter_Ability( attacker.Pokemon ),
            SetMoveTerrain = _ai.UnitSim.PokemonHasTerrainSetter_Move( attacker.Pokemon ),

            SetTrickRoom = ourTraits.Contains( RoleTrait.TrickRoomSetter ),
            SetTailwind = ourTraits.Contains( RoleTrait.TailwindSetter ),
            SetReflect = attacker.Pokemon.CheckHasActiveMove( "Reflect" ),
            SetLightScreen = attacker.Pokemon.CheckHasActiveMove( "Light Screen" ),
            SetAuroraVeil = attacker.Pokemon.CheckHasActiveMove( "Aurora Veil" ),

            FakeOut = _ai.CanUseFakeOut( attacker, attacker ),
            KnockOff = attacker.Pokemon.CheckHasActiveMove( "Knock Off" ),
            ThroatChop = attacker.Pokemon.CheckHasActiveMove( "Throat Chop" ),

            FlipVoltTurn = attacker.Pokemon.CheckHasActiveMove( "Flip Turn" ) || attacker.Pokemon.CheckHasActiveMove( "Volt Switch" ) || attacker.Pokemon.CheckHasActiveMove( "U-Turn" ),
            PartingShot = attacker.Pokemon.CheckHasActiveMove( "Parting Shot" ),

            SelfSetup = ourTraits.Contains( RoleTrait.PhysicallyOffensiveSetup ) || ourTraits.Contains( RoleTrait.SpeciallyOffensiveSetup ) || ourTraits.Contains( RoleTrait.PhysicallyDefensiveSetup ) || ourTraits.Contains( RoleTrait.SpeciallyDefensiveSetup ),
            StatDebuff = ourTraits.Contains( RoleTrait.StatDebuffer ),

            FollowMe = attacker.Pokemon.CheckHasActiveMove( "Follow Me" ),
            RagePowder = attacker.Pokemon.CheckHasActiveMove( "Rage Powder" ),

            HelpingHand = attacker.Pokemon.CheckHasActiveMove( "Helping Hand" ),

            Taunt = ourTraits.Contains( RoleTrait.Taunt ),
            Encore = ourTraits.Contains( RoleTrait.Encore ),
            Disable = attacker.Pokemon.CheckHasActiveMove( "Disable" ),
            PerishSong = ourTraits.Contains( RoleTrait.PerishSong ),

            Wisp = attacker.Pokemon.CheckHasActiveMove( "Will-O-Wisp" ),
            Hoarfrost = attacker.Pokemon.CheckHasActiveMove( "Hoarfrost Spirit" ),
            TWave = attacker.Pokemon.CheckHasActiveMove( "Thunder Wave" ),
            StunSpore = attacker.Pokemon.CheckHasActiveMove( "Stun Spore" ),
            Toxic = attacker.Pokemon.CheckHasActiveMove( "Toxic" ),
            Poison = ourTraits.Contains( RoleTrait.PoisonPressure ),
            SleepPowder = attacker.Pokemon.CheckHasActiveMove( "Sleep Powder" ),
            Spore = attacker.Pokemon.CheckHasActiveMove( "Spore" ),

            Protect = _ai.CanUseProtect( attacker.Pokemon ),
        };

        //--Things they CAN do
        InteractionFlags theyCan = new()
        {
            SetAbilityWeather = _ai.UnitSim.PokemonHasWeatherSetter_Ability( target.Pokemon ),
            SetMoveWeather = _ai.UnitSim.PokemonHasWeatherSetter_Move( target.Pokemon ),
            SetAbilityTerrain = _ai.UnitSim.PokemonHasTerrainSetter_Ability( target.Pokemon ),
            SetMoveTerrain = _ai.UnitSim.PokemonHasTerrainSetter_Move( target.Pokemon ),

            SetTrickRoom = theirTraits.Contains( RoleTrait.TrickRoomSetter ),
            SetTailwind = theirTraits.Contains( RoleTrait.TailwindSetter ),
            SetReflect = target.Pokemon.CheckHasActiveMove( "Reflect" ),
            SetLightScreen = target.Pokemon.CheckHasActiveMove( "Light Screen" ),
            SetAuroraVeil = target.Pokemon.CheckHasActiveMove( "Aurora Veil" ),

            FakeOut = _ai.CanUseFakeOut( target, attacker ),
            KnockOff = target.Pokemon.CheckHasActiveMove( "Knock Off" ),
            ThroatChop = target.Pokemon.CheckHasActiveMove( "Throat Chop" ),

            FlipVoltTurn = target.Pokemon.CheckHasActiveMove( "Flip Turn" ) || target.Pokemon.CheckHasActiveMove( "Volt Switch" ) || target.Pokemon.CheckHasActiveMove( "U-Turn" ),
            PartingShot = target.Pokemon.CheckHasActiveMove( "Parting Shot" ),

            SelfSetup = theirTraits.Contains( RoleTrait.PhysicallyOffensiveSetup ) || theirTraits.Contains( RoleTrait.SpeciallyOffensiveSetup ) || theirTraits.Contains( RoleTrait.PhysicallyDefensiveSetup ) || theirTraits.Contains( RoleTrait.SpeciallyDefensiveSetup ),
            StatDebuff = theirTraits.Contains( RoleTrait.StatDebuffer ),

            FollowMe = target.Pokemon.CheckHasActiveMove( "Follow Me" ),
            RagePowder = target.Pokemon.CheckHasActiveMove( "Rage Powder" ),

            HelpingHand = target.Pokemon.CheckHasActiveMove( "Helping Hand" ),

            Taunt = theirTraits.Contains( RoleTrait.Taunt ),
            Encore = theirTraits.Contains( RoleTrait.Encore ),
            Disable = target.Pokemon.CheckHasActiveMove( "Disable" ),
            PerishSong = theirTraits.Contains( RoleTrait.PerishSong ),

            Wisp = target.Pokemon.CheckHasActiveMove( "Will-O-Wisp" ),
            Hoarfrost = target.Pokemon.CheckHasActiveMove( "Hoarfrost Spirit" ),
            TWave = target.Pokemon.CheckHasActiveMove( "Thunder Wave" ),
            StunSpore = target.Pokemon.CheckHasActiveMove( "Stun Spore" ),
            Toxic = target.Pokemon.CheckHasActiveMove( "Toxic" ),
            Poison = theirTraits.Contains( RoleTrait.PoisonPressure ),
            SleepPowder = target.Pokemon.CheckHasActiveMove( "Sleep Powder" ),
            Spore = target.Pokemon.CheckHasActiveMove( "Spore" ),

            Protect = _ai.CanUseProtect( target.Pokemon ),
        };

        //--Things they want to do relative to their pressure/strategy/TIR
        InteractionFlags theyWant = new();

        switch( theirAction )
        {
            case ActionType.Attack:

                var theirAttack = theirActionResult.Move;

                switch( theirAttack.MoveSO.Name )
                {
                    case "Fake Out":
                        theyWant.FakeOut = true;
                    break;

                    case "Knock Off":
                        theyWant.KnockOff = true;
                    break;

                    case "Throat Chop":
                        theyWant.ThroatChop = true;
                    break;

                    case "Flip Turn":
                    case "Volt Switch":
                    case "U-Turn":
                        theyWant.FlipVoltTurn = true;
                    break;

                    case "Parting Shot":
                        theyWant.PartingShot = true;
                    break;

                    default:
                        theyWant.StrongestAttack = theirAttack != null;
                    break;
                }

            break;

            case ActionType.DefensiveSwitch:
            case ActionType.OffensiveSwitch:

                theyWant.RawSwitch = true;

                if( theyCan.SetAbilityWeather && spe.Pressure == StrategyPressure.WeatherChange )
                    theyWant.SetAbilityWeather = true;

                else if( theyCan.SetAbilityTerrain && spe.Pressure == StrategyPressure.TerrainChange )
                    theyWant.SetAbilityTerrain = true;                    

            break;

            case ActionType.Setup:

                var theirSetup = theirActionResult.Move;
                theyWant.SelfSetup = theirSetup != null;

            break;

            case ActionType.OffensiveStatus:

                var theirOffStatus = theirActionResult.Move;
                if( theirOffStatus == null )
                    break;

                if( _ai.UnitSim.Move_ChangesWeather( theirOffStatus ) && spe.Pressure == StrategyPressure.WeatherChange )
                    theyWant.SetMoveWeather = true;

                if( _ai.UnitSim.Move_ChangesTerrain( theirOffStatus ) && spe.Pressure == StrategyPressure.TerrainChange )
                    theyWant.SetMoveTerrain = true;

                switch( theirOffStatus.MoveSO.Name )
                {
                    case "Taunt":
                        theyWant.Taunt = true;
                    break;

                    case "Encore":
                        theyWant.Encore = true;
                    break;

                    case "Disable":
                        theyWant.Disable = true;
                    break;

                    case "Perish Song":
                        theyWant.PerishSong = true;
                    break;

                    case "Will-O-Wisp":
                        theyWant.Wisp = true;
                    break;

                    case "Hoarfrost Spirit":
                        theyWant.Hoarfrost = true;
                    break;

                    case "Thunder Wave":
                        theyWant.TWave = true;
                    break;

                    case "Stun Spore":
                        theyWant.StunSpore = true;
                    break;

                    case "Toxic":
                        theyWant.Toxic = true;
                    break;

                    case "Sleep Powder":
                        theyWant.SleepPowder = true;
                    break;

                    case "Spore":
                        theyWant.Spore = true;
                    break;

                    case "Spikes":
                    case "Toxic Spikes":
                    case "Stealth Rock":
                    case "Sticky Web":
                    case "Leech Seed":
                        theyWant.SetEntryHazard = true;
                    break;
                }

                if( theirOffStatus.MoveEffects.SevereStatus == SevereConditionID.PSN )
                    theyWant.Poison = true;

                if( _ai.UnitSim.MoveIsDebuff( theirOffStatus ) )
                    theyWant.StatDebuff = true;

            break;

            case ActionType.SupportiveStatus:

                var theirSuppStatus = theirActionResult.Move;

                switch( theirSuppStatus.MoveSO.Name )
                {
                    case "Trick Room":
                        theyWant.SetTrickRoom = true;
                    break;

                    case "Tailwind":
                        theyWant.SetTailwind = true;
                    break;

                    case "Reflect":
                        theyWant.SetReflect = true;
                    break;

                    case "Light Screen":
                        theyWant.SetLightScreen = true;
                    break;

                    case "Aurora Veil":
                        theyWant.SetAuroraVeil = true;
                    break;

                    case "Follow Me":
                        theyWant.FollowMe = true;
                    break;

                    case "Rage Powder":
                        theyWant.RagePowder = true;
                    break;

                    case "Helping Hand":
                        theyWant.HelpingHand = true;
                    break;
                }

            break;

            case ActionType.Protect:

                var theirProtect = theirActionResult.Move;

                // switch( theirProtect.MoveSO.Name )
                // {
                //     case "Protect":
                //         theyWant.Protect = true;
                //     break;
                // }

            break;
        };

        //--Attack Exchange
        var ourAlly = (IBattleAIUnit)_ai.GetActiveAllyAs_Adapter( attacker.Pokemon );
        var theirAlly = (IBattleAIUnit)_ai.GetActiveAllyAs_Adapter( target.Pokemon );

        var usVsThem = _ai.Projection.MakeUnitComparison( attacker, target );
        var usVsTheirAlly = theirAlly != null ? _ai.Projection.MakeUnitComparison( attacker, theirAlly ) : default;

        var ourAllyVsThem = ourAlly != null ? _ai.Projection.MakeUnitComparison( ourAlly, target ) : default;
        var ourAllyVsTheirAlly = ourAlly != null && theirAlly != null ? _ai.Projection.MakeUnitComparison( ourAlly, theirAlly ) : default;

        Intent theirAllyIntent = default;
        bool theirAllyHasIntent = spe.SourceStrategy != null && TryGetOpponentAllyIntent_FromStrategy( target.Pokemon, spe, out theirAllyIntent );

        if( !theirAllyHasIntent )
        {
            
        }

        Dictionary<IBattleAIUnit, Move> units = new();

        if( actionCandidate.Type != CoordinationActionType.SwitchCandidatePotential && actionCandidate.Action != ActionType.OffensiveSwitch && actionCandidate.Action != ActionType.DefensiveSwitch )
        {
            units.Add( attacker, actionCandidate.MoveCandidate );
        }
        else if( actionCandidate.Type == CoordinationActionType.SwitchCandidatePotential )
        {
            var ptkoThem = usVsThem.Attacker.BestCurrentPTKO;
            var ptkoAlly = usVsTheirAlly.Attacker.BestCurrentPTKO;

            if( ptkoThem > ptkoAlly )
                units.Add( attacker, usVsThem.Attacker.CurrentPTKOs.Keys.First() );
            else
                units.Add( attacker, usVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() );
        }

        if( theirAction != ActionType.OffensiveSwitch && theirAction != ActionType.DefensiveSwitch && theirActionResult?.Move != null )
            units.Add( target, theirActionResult.Move );

        if( ourAlly != null )
        {
            var ptkoThem = ourAllyVsThem.Attacker.BestCurrentPTKO;
            var ptkoAlly = theirAlly != null ? ourAllyVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;

            if( ptkoThem > ptkoAlly )
                units.Add( ourAlly, ourAllyVsThem.Attacker.CurrentPTKOs.Keys.First() );
            else if( theirAlly != null )
                units.Add( ourAlly, ourAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() );
            else
                units.Add( ourAlly, ourAllyVsThem.Attacker.CurrentPTKOs.Keys.First() );
        }

        if( theirAlly != null )
        {
            var ptkoUs = usVsTheirAlly.Target.BestCurrentPTKO;
            var ptkoAlly = ourAlly != null ? ourAllyVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

            if( ptkoUs > ptkoAlly )
                units.Add( theirAlly, usVsTheirAlly.Target.CurrentPTKOs.Keys.First() );
            else if( ourAlly != null )
                units.Add( theirAlly, ourAllyVsTheirAlly.Target.CurrentPTKOs.Keys.First() );
            else
                units.Add( theirAlly, usVsTheirAlly.Target.CurrentPTKOs.Keys.First() );
        }

        var turnOrder = GetTurnOrder( units, spe, _ai.Blackboard.CurrentFieldSnapshot );

        return new()
        {
            Attacker = attacker,
            Target = target,

            AttackerAlly = ourAlly,
            TargetAlly = theirAlly,

            AttackerPTKO = usVsThem.Attacker.BestCurrentPTKO,
            TargetPTKO = usVsThem.Target.BestCurrentPTKO,

            AttackerMovesFirst = MovesFirst( attacker, turnOrder ),
            TurnOrder = turnOrder.ToDictionary( kvp => kvp.Key, kvp => kvp.Value ),

            UsVsThem = usVsThem,
            UsVsTheirAlly = usVsTheirAlly,
            OurAllyVsThem = ourAllyVsThem,
            OurAllyVsTheirAlly = ourAllyVsTheirAlly,

            OurAction = actionCandidate.Action,
            OurAllyAction = ActionType.Attack,
            TheirAction = theirAction,
            TheirAllyAction = theirAllyIntent.IntentResult != null ? theirAllyIntent.IntentResult.ActionType : ActionType.Attack,

            TheirAllyHasIntent = theirAllyHasIntent,
            TheirActionResult = theirActionResult,
            TheirAllyActionResult = theirAllyIntent.IntentResult != null ? theirAllyIntent.IntentResult : null,

            WeCan = weCan,
            TheyCan = theyCan,
            TheyWant = theyWant,
        };
    }

