    private CoordinationAction GetOffensiveStatusCandidate( CapabilityObservation capability, IBattleAIUnit us, IBattleAIUnit them, CoordinationActionType type )
    {
        Move moveCandidate = null;

        switch( capability )
        {
            case CapabilityObservation.Taunt:
            
                if( TryExtractMoveFromPokemon( "Taunt", us, out var taunt ) )
                    moveCandidate = taunt;
            
            break;

            case CapabilityObservation.Encore:
            
                if( TryExtractMoveFromPokemon( "Encore", us, out var encore ) )
                    moveCandidate = encore;
            
            break;

            case CapabilityObservation.Disable:
            
                if( TryExtractMoveFromPokemon( "Disable", us, out var disable ) )
                    moveCandidate = disable;
            
            break;

            case CapabilityObservation.Torment:
            
                if( TryExtractMoveFromPokemon( "Torment", us, out var torment ) )
                    moveCandidate = torment;
            
            break;

            case CapabilityObservation.Imprison:
            
                if( TryExtractMoveFromPokemon( "Imprison", us, out var imprison ) )
                    moveCandidate = imprison;
            
            break;

            case CapabilityObservation.Phazing:
            
                foreach( var move in us.ActiveMoves )
                {
                    if( _ai.UnitSim.MoveIsPhaze( move ) )
                    {
                        moveCandidate = move;
                        break;
                    }
                }
            
            break;

            case CapabilityObservation.Wisp:
            
                if( TryExtractMoveFromPokemon( "will-O-Wisp", us, out var wisp ) )
                    moveCandidate = wisp;
            
            break;

            case CapabilityObservation.Hoarfrost:
            
                if( TryExtractMoveFromPokemon( "Hoarfrost Spirit", us, out var hoarfrost ) )
                    moveCandidate = hoarfrost;
            
            break;

            case CapabilityObservation.StatDebuff:
            
                foreach( var move in us.ActiveMoves )
                {
                    if( _ai.UnitSim.MoveIsDebuff( move ) )
                    {
                        moveCandidate = move;
                        break;
                    }
                }
            
            break;

            case CapabilityObservation.HazardSetting:
            
                foreach( var move in us.ActiveMoves )
                {
                    if( _ai.UnitSim.MoveIsEntryHazard( move ) )
                    {
                        moveCandidate = move;
                        break;
                    }
                }
            
            break;

            case CapabilityObservation.Quash:
            
                if( TryExtractMoveFromPokemon( "Quash", us, out var quash ) )
                    moveCandidate = quash;
            
            break;

        }

        return new()
        {
            Type = type,
            Action = ActionType.OffensiveStatus,

            Actor = us.Pokemon,
            Target = them.Pokemon,

            MoveCandidate = moveCandidate,
            SwitchCandidate = null,

            Capability = capability,
        };
    }

    private CoordinationAction GetSupportiveStatusCandidate( CapabilityObservation capability, IBattleAIUnit us, IBattleAIUnit them, CoordinationActionType type )
    {
        Move moveCandidate = null;

        switch( capability )
        {
            case CapabilityObservation.Redirection:

                if( TryExtractMoveFromPokemon( "Follow Me", us, out var followMe ) )
                    moveCandidate = followMe;

                if( TryExtractMoveFromPokemon( "Rage Powder", us, out var ragePowder ) )
                    moveCandidate = ragePowder;

            break;

            case CapabilityObservation.WeatherSetMove:

                if( _ai.UnitSim.GetWeatherFrom_Moveset( us.Pokemon ) is var moveWeather && moveWeather != WeatherConditionID.None )
                {
                    switch( moveWeather )
                    {
                        case WeatherConditionID.Sun: 
                            if( TryExtractMoveFromPokemon( "Sunny Day", us, out var sunnyDay ) )
                                moveCandidate = sunnyDay;

                        break;

                        case WeatherConditionID.Rain:
                            if( TryExtractMoveFromPokemon( "Rain Dance", us, out var rainDance ) )
                                moveCandidate = rainDance;

                        break;

                        case WeatherConditionID.Sand:
                            if( TryExtractMoveFromPokemon( "Sandstorm", us, out var sandStorm ) )
                                moveCandidate = sandStorm;


                        break;

                        case WeatherConditionID.Snow:
                            if( TryExtractMoveFromPokemon( "Snowscape", us, out var snowScape ) )
                                moveCandidate = snowScape;

                        break;
                    }
                }
                
            break;

            case CapabilityObservation.TerrainSetMove:

                if( _ai.UnitSim.GetTerrainFrom_Moveset( us.Pokemon ) is var moveTerrain && moveTerrain != TerrainID.None )
                {
                    switch( moveTerrain )
                    {
                        case TerrainID.Blighted: 
                            if( TryExtractMoveFromPokemon( "Blighted Terrain", us, out var blighted ) )
                                moveCandidate = blighted;

                        break;

                        case TerrainID.Electric:
                            if( TryExtractMoveFromPokemon( "Electric Terrain", us, out var electric ) )
                                moveCandidate = electric;

                        break;

                        case TerrainID.Grassy:
                            if( TryExtractMoveFromPokemon( "Grassy Terrain", us, out var grassy ) )
                                moveCandidate = grassy;

                        break;

                        case TerrainID.Misty:
                            if( TryExtractMoveFromPokemon( "Misty Terrain", us, out var misty ) )
                                moveCandidate = misty;

                        break;

                        case TerrainID.Psychic:
                            if( TryExtractMoveFromPokemon( "Psychic Terrain", us, out var psychic ) )
                                moveCandidate = psychic;

                        break;
                    }
                }

            break;

            case CapabilityObservation.Tailwind:

                if( TryExtractMoveFromPokemon( "Tailwind", us, out var tailwind ) )
                    moveCandidate = tailwind;

            break;

            case CapabilityObservation.TrickRoom:

                if( TryExtractMoveFromPokemon( "Trick Room", us, out var trickRoom ) )
                    moveCandidate = trickRoom;

            break;

            case CapabilityObservation.StatReset:

                if( TryExtractMoveFromPokemon( "Clear Smog", us, out var clearSmog ) )
                    moveCandidate = clearSmog;

                if( TryExtractMoveFromPokemon( "Haze", us, out var haze ) )
                    moveCandidate = haze;

            break;

            case CapabilityObservation.Defog:

                if( TryExtractMoveFromPokemon( "Defog", us, out var defog ) )
                    moveCandidate = defog;

            break;

            case CapabilityObservation.AllySwitch:

                if( TryExtractMoveFromPokemon( "Ally Switch", us, out var allySwitch ) )
                    moveCandidate = allySwitch;

            break;

            case CapabilityObservation.HelpingHand:

                if( TryExtractMoveFromPokemon( "Helping Hand", us, out var helpingHand ) )
                    moveCandidate = helpingHand;

            break;

            case CapabilityObservation.AfterYou:

                if( TryExtractMoveFromPokemon( "After You", us, out var afterYou ) )
                    moveCandidate = afterYou;

            break;

            case CapabilityObservation.SideStatBuff:

                if( _ai.UnitSim.TryExtractFirstFoundSidebuff( us.Pokemon, out var sideBuff ) )
                    moveCandidate = sideBuff;

            break;

            case CapabilityObservation.SelfHeal:

                foreach( var move in us.ActiveMoves )
                {
                    if( _ai.UnitSim.MoveIsSelfHeal( move ) )
                    {
                        moveCandidate = move;
                        break;
                    }
                }

            break;

            case CapabilityObservation.SideHeal:

                foreach( var move in us.ActiveMoves )
                {
                    if( _ai.UnitSim.MoveIsSideHeal( move ) )
                    {
                        moveCandidate = move;
                        break;
                    }
                }

            break;

            case CapabilityObservation.Reflect:

                if( TryExtractMoveFromPokemon( "Reflect", us, out var reflect ) )
                    moveCandidate = reflect;

            break;

            case CapabilityObservation.LightScreen:

                if( TryExtractMoveFromPokemon( "Light Screen", us, out var lightScreen ) )
                    moveCandidate = lightScreen;
            break;

            case CapabilityObservation.AuroraVeil:

                if( TryExtractMoveFromPokemon( "Aurora Veil", us, out var auroraVeil ) )
                    moveCandidate = auroraVeil;

            break;

            case CapabilityObservation.TidyUp:

                if( TryExtractMoveFromPokemon( "Tidy Up", us, out var tidyUp ) )
                    moveCandidate = tidyUp;

            break;

        }

        return new()
        {
            Type = type,
            Action = ActionType.SupportiveStatus,

            Actor = us.Pokemon,
            Target = them.Pokemon,

            MoveCandidate = moveCandidate,
            SwitchCandidate = null,

