#region "Response Actions"

    private Dictionary<CoordinationAction, CoordinationActionScores> GetAttackResponses( Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = _ai.GetRemainingPartyAs_IBattleAIUnits( ourActive[0].Pokemon ).Where( u => !ourActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = _ai.GetRemainingPartyAs_IBattleAIUnits( theirActive[0].Pokemon ).Where( u => !theirActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();
            var capabilitySets = ExtractUniqueCapabilities( ActionType.Attack, unit.Pokemon, pressureSets );

            if( capabilitySets?.Count <= 0 )
                continue;

            //--extract unique capabilities who have hashsets of pressures they are a response to.
            //--then, in  pressure fit, we can do score += coveredPressures.Count, naturally letting a response capability
            //--cover multiple options at once and rewarding it for doing so.
            foreach( var kvp in capabilitySets )
            {
                var capability = kvp.Key;
                var pressures = kvp.Value;

                foreach( var opp in theirActive )
                {
                    var candidate = GetAttackCandidate( capability, unit, opp, CoordinationActionType.Response );
                    candidate.RelevantPressures = pressures;
                    candidates.Add( candidate );
                }
            }

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var theirSP  = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                //----------------
                //--Pressure Fit--
                //----------------
                //--Capability's Pressure Coverage
                int pressureFitScore = candidate.RelevantPressures.Count;

                //--Family Compatability
                //--score += compatability look up helper

                foreach( var e in candidate.RelevantPressures )
                {
                    var ip = GetInteractionProfile( us, them, candidate, e );

                    var ourPTKO_Them = ip.AttackerPTKO;
                    var theirPTKO_Us = ip.TargetPTKO;
                    var attackerMovesFirst = ip.AttackerMovesFirst;

                    var theirAction = ip.TheirAction;
                    var theirActionResult = ip.TheirActionResult;
                    var theirMTR = theirActionResult is MoveThreatResult result ? result : null ;
                    var theirEDR = theirMTR != null ? theirMTR.EDR : default;

                    var theirAllyAction = ip.TheirAllyAction;
                    var theirAllyActionResult = ip.TheirAllyActionResult;
                    bool theirAllyHasIntent = ip.TheirAllyHasIntent;

                    var ourAlly = ip.AttackerAlly;
                    var theirAlly = ip.TargetAlly;

                    bool weHaveAlly = ourAlly != null;
                    bool theyHaveAlly = theirAlly != null;

                    var ourAllySP = weHaveAlly ? _ai.Projection.GetStrategicProfile( ourAlly ) : default;
                    var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                    bool theyAttack = theirAction == ActionType.Attack;
                    bool theySwitch = theirAction == ActionType.OffensiveSwitch || theirAction == ActionType.DefensiveSwitch;
                    bool theySetup = theirAction == ActionType.Setup;
                    bool theyStatus = theirAction == ActionType.OffensiveStatus || theirAction == ActionType.SupportiveStatus;
                    bool theyProtect = theirAction == ActionType.Protect;

                    bool theyUseAMove = theyAttack || theySetup || theyStatus || theyProtect;

                    var theirMove = theirActionResult.Move;

                    bool theyTargetUs = theirMove != null && theirActionResult.Targets.Any( u => u.Pokemon == us.Pokemon );
                    bool theyTargetOurAlly = theirMove != null && weHaveAlly && theirActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                    bool theirAllyAttacks = theirAllyHasIntent && theirAllyAction == ActionType.Attack;
                    bool theirAllySwitches = theirAllyHasIntent && ( theirAllyAction == ActionType.DefensiveSwitch || theirAllyAction == ActionType.OffensiveSwitch );
                    bool theirAllySetsup = theirAllyHasIntent && theirAllyAction == ActionType.Setup;
                    bool theirAllyStatuses = theirAllyHasIntent && ( theirAllyAction == ActionType.OffensiveStatus || theirAllyAction == ActionType.SupportiveStatus );
                    bool theirAllyProtects = theirAllyHasIntent && theirAllyAction == ActionType.Protect;

                    var theirAllyMove = theirAllyAttacks && theirAllyActionResult?.Move != null ? theirAllyActionResult.Move : null;
                    bool theirAllyUsesMove = theyHaveAlly && theirAllyMove != null;
                    bool theirAllyTargetsUs = theyHaveAlly && theirAllyHasIntent && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == u.Pokemon );
                    bool theirAllyTargetsOurAlly = theyHaveAlly && theirAllyHasIntent && weHaveAlly && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                    var ourAllyPTKO_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var ourAllyPTKO_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;

                    var theirAllyPTKO_Us = theirAllyTargetsUs ? ip.UsVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var theirAllyPTKO_OurAlly = theirAllyTargetsOurAlly ? ip.OurAllyVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                    var theirPTKO_OurAlly = weHaveAlly ? ip.OurAllyVsThem.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                    var ourAllyMove = ourAllyPTKO_Them > ourAllyPTKO_TheirAlly ? ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() : ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First();
                    
                    SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)theirActionResult : default;
                    var theirSwitch = theySwitch ? scr.Candidate : null;
                    bool theyHaveSwitch = theirSwitch != null;
                    var usVsSwitch = theyHaveSwitch && theirSwitch != null ? _ai.Projection.MakeUnitComparison( us, theirSwitch ) : default;

                    List<IBattleAIUnit> targetsTargets = ip.TheirActionResult.Targets != null && ip.TheirActionResult.Targets.Count > 0 ? ip.TheirActionResult.Targets : null;
                    bool targetsUs = targetsTargets != null && targetsTargets.Count > 0 && targetsTargets.Any( u => u.Pokemon == us.Pokemon );

                    bool targetCanProtect = _ai.CanUseProtect( them.Pokemon );
                    bool targetHasReasonToProtect = false;
                    bool targetHasReasonToSwitch = false;

                    Dictionary<IBattleAIUnit, Move> turnOrderUnits = new()
                    {
                        { us, candidate.MoveCandidate },
                        { them, theirMove },
                    };

                    if( ourAlly != null )
                        turnOrderUnits.Add( ourAlly, ourAllyMove );

                    if( theirAlly != null )
                        turnOrderUnits.Add( theirAlly, theirAllyMove );

                    var turnOrder = GetTurnOrder( turnOrderUnits, e, field );

                    WeatherConditionID targetsWeather = WeatherConditionID.None;
                    WeatherConditionID theirAllyWeather = WeatherConditionID.None;
                    WeatherConditionID switchesWeather = WeatherConditionID.None;

                    bool targetSetWeather = _ai.UnitSim.Pokemon_SetWeather( them.Pokemon, out targetsWeather, currentWeather );
                    bool allySetWeather = theyHaveAlly && _ai.UnitSim.Pokemon_SetWeather( theirAlly?.Pokemon, out theirAllyWeather, currentWeather );
                    bool switchChangesWeather = theyHaveSwitch && _ai.UnitSim.Switch_ChangesWeather( scr, out switchesWeather, null );

                    TerrainID targetsTerrain = TerrainID.None;
                    TerrainID theirAllyTerrain = TerrainID.None;
                    TerrainID switchesTerrain = TerrainID.None;

                    bool targetSetTerrain = _ai.UnitSim.Pokemon_SetTerrain( them.Pokemon, out targetsTerrain, currentTerrain );
                    bool allySetTerrain = theyHaveAlly && _ai.UnitSim.Pokemon_SetTerrain( theirAlly?.Pokemon, out theirAllyTerrain, currentTerrain );
                    bool switchChangesTerrain = theyHaveSwitch && _ai.UnitSim.Switch_ChangesTerrain( scr, out switchesTerrain, null );

                    //-------------
                    //--Board Fit--
                    //-------------
                    bool doTheyThreaten = false;
                    if( theirPTKO_Us >= PotentialToKO.Dangerous && ( !attackerMovesFirst || attackerMovesFirst && ourPTKO_Them <= PotentialToKO.Risky ) )
                        doTheyThreaten = true;

                    bool weCanReduceTheirThreat = false;
                    if( ourPTKO_Them >= PotentialToKO.Dangerous && attackerMovesFirst )
                    {
                        weCanReduceTheirThreat = true;
                        targetHasReasonToSwitch = true;

                        if( targetCanProtect )
                            targetHasReasonToProtect = true;
                    }

                    if( mainCapability == CapabilityObservation.FakeOut )
                        weCanReduceTheirThreat = true;

                    if( mainCapability == CapabilityObservation.KnockOff )
                    {
                        if( _ai.UnitSim.PokemonHasItem_Offensive( them ) )
                            weCanReduceTheirThreat = true;

                        if( them.RoleProfile.Traits.Contains( RoleTrait.RecoveryItem ) )
                            weCanReduceTheirThreat = true;
                        
                        if( TryExtractMoveFromPokemon( "Knock Off", us, out var knockOff ) )
                        {
                            var knockOffPTKO = ip.UsVsThem.Attacker.CurrentPTKOs[knockOff];

                            if( knockOffPTKO >= PotentialToKO.Dangerous )
                            {
                                weCanReduceTheirThreat = true;
                                targetHasReasonToSwitch = true;
                            }
                        }
                    }

                    if( mainCapability == CapabilityObservation.ThroatChop )
                    {
                        if( them.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                            weCanReduceTheirThreat = true;

                        if( TryExtractMoveFromPokemon( "Throat Chop", us, out var throatChop ) )
                        {
                            var throatChopPTKO = ip.UsVsThem.Attacker.CurrentPTKOs[throatChop];

                            if( throatChopPTKO >= PotentialToKO.Dangerous )
                            {
                                weCanReduceTheirThreat = true;
                                targetHasReasonToSwitch = true;
                            }
                        }
                    }

                    if( targetCanProtect && mainCapability == CapabilityObservation.FakeOut && them.Item == ItemBattleEffectID.FocusSash && them.BeginningHPR == 1f )
                        targetHasReasonToProtect = true;

                    if( TryExtractSwitchBasedPressures( candidate.RelevantPressures, out var switchBasedPressures ) )
                    {
                        if( StrategyPressureEvidenceContainsPressure( StrategyPressure.WeatherChange, switchBasedPressures ) && switchChangesWeather )
                        {
                            bool activeUnitAbusesWeather = false;
                            Pokemon theirWeatherAbuser = null;
                            WeatherConditionID incomingWeather = switchChangesWeather ? switchesWeather : WeatherConditionID.None;

                            foreach( var their in theirActive )
                            {
                                if( _ai.UnitSim.PokemonHasMove_AbusesWeather( their.Pokemon, incomingWeather ) )
                                {
                                    theirWeatherAbuser = their.Pokemon;
                                    activeUnitAbusesWeather = true;
                                    break;
                                }
                            }

                            if( activeUnitAbusesWeather && theirWeatherAbuser != candidate.Target )
                                targetHasReasonToSwitch = true;
                        }
                    }

                    if( doTheyThreaten && weCanReduceTheirThreat )
                        boardFit += 1;

                    if( weCanReduceTheirThreat )
                        boardFit += 1;

                    if( targetHasReasonToProtect )
                        boardFit += 1;

                    if( targetHasReasonToSwitch )
                        boardFit += 1;

                    //--Fake Out genuinely is rewardable for every single flag. It's just that strong.
                    if( mainCapability == CapabilityObservation.FakeOut )
                    {   
                        if( ip.TheyWant.FakeOut && targetsUs && MovesBefore( us, them, turnOrder ) )
                            boardFit += 1;
                        else if( ip.TheyWant.FakeOut && targetsUs && MovesBefore( them, us, turnOrder ) && !us.RoleProfile.Traits.Contains( RoleTrait.FakeOutImmune ) )
                            boardFit -= 1;
                        else if( ip.TheyWant.RawSwitch )
                            boardFit -= 2;
                        else
                            boardFit += 1;

                        if( them.Item == ItemBattleEffectID.FocusSash )
                            boardFit += 1;
                    }

                    bool knockOffImportantItem = false;
                    if( mainCapability == CapabilityObservation.KnockOff )
                    {
                        if( _ai.UnitSim.PokemonHasItem_Offensive( them ) )
                        {
                            boardFit += 1;
                            knockOffImportantItem = true;
                        }

                        if( them.Item == ItemBattleEffectID.AssaultVest )
                        {
                            boardFit += 1;
                            knockOffImportantItem = true;
                        }

                        if( them.Item == ItemBattleEffectID.Eviolite )
                        {
                            boardFit += 1;
                            knockOffImportantItem = true;
                        }

                        if( them.Item == ItemBattleEffectID.ChoiceScarf && MovesBefore( them, us, turnOrder ) )
                        {
                            boardFit += 1;

                            if( them.Speed / 2 < us.Speed )
                            {
                                boardFit += 1;
                                knockOffImportantItem = true;
                            }
                        }

                        if( them.RoleProfile.Traits.Contains( RoleTrait.RecoveryItem ) )
                        {
                            boardFit += 1;
                            knockOffImportantItem = true;
                        }
                    }

                    if( mainCapability == CapabilityObservation.ThroatChop )
                    {
                        if( them.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                            boardFit += 1;

                        if( them.Item == ItemBattleEffectID.ThroatSpray )
                            boardFit += 1;
                    }

                    if( theyHaveSwitch && IsSwitchBasedPressure( e.Pressure ) )
                    {
                        if( mainCapability == CapabilityObservation.FakeOut )
                            boardFit -= 2;

                        if( mainCapability == CapabilityObservation.KnockOff )
                            boardFit += 2;

                        if( mainCapability == CapabilityObservation.ThroatChop && theirSwitch != null && theirSwitch.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                            boardFit += 1;

                        if( mainCapability == CapabilityObservation.CoverageMove )
                            boardFit += 3;
                    }

                    if( ip.TheyWant.Protect )
                    {
                        //--Perhaps we reward fake out here because it forces them to protect. Forcing them to protect is effectively the same as causing them to flinch.
                        if( mainCapability == CapabilityObservation.FakeOut )
                            boardFit += 1;
                        else
                            boardFit -= 1;

                        if( mainCapability == CapabilityObservation.StrongestAttack || mainCapability == CapabilityObservation.CoverageMove )
                            boardFit -= 1;

                        if( e.Pressure == StrategyPressure.PreserveUnit )
                            boardFit -= 1;
                    }
                
                    //------------
                    //--Unit Fit--
                    //------------
                    //--Role Checks
                    switch( us.RoleProfile.PrimaryArchetype )
                    {
                        case RoleClassArchetype.Offensive:

                            //--All attack capabilities are offensive tools and should be rewarded flatly here.
                            unitFit += 1;

                            if( ourPTKO_Them >= PotentialToKO.Dangerous && attackerMovesFirst )
                            {
                                unitFit += 2;

                                if( mainCapability == CapabilityObservation.StrongestAttack || mainCapability == CapabilityObservation.CoverageMove )
                                    unitFit += 1;
                            }
                            else if( ourPTKO_Them >= PotentialToKO.Dangerous && theirPTKO_Us <= PotentialToKO.Risky )
                            {
                                unitFit += 1;

                                if( mainCapability == CapabilityObservation.StrongestAttack || mainCapability == CapabilityObservation.CoverageMove )
                                    unitFit += 1;
                            }

                        break;

                        case RoleClassArchetype.Defensive:

                            if( mainCapability == CapabilityObservation.FakeOut )
                                unitFit += 1;

                            if( mainCapability == CapabilityObservation.KnockOff )
                            {
                                if( ourPTKO_Them >= PotentialToKO.Risky )
                                    unitFit += 1;

                                if( knockOffImportantItem )
                                    unitFit += 1;

                                if( theirPTKO_Us <= PotentialToKO.TwoHKO && them.Item != ItemBattleEffectID.None )
                                    unitFit += 1;
                            }

                        break;

                        case RoleClassArchetype.Utility:

                            if( mainCapability == CapabilityObservation.FakeOut )
                                unitFit += 1;

                            if( mainCapability == CapabilityObservation.KnockOff )
                            {
                                if( knockOffImportantItem )
                                    unitFit += 1;
                            }

                            if( mainCapability == CapabilityObservation.ThroatChop && theyUseAMove && theirMove.MoveSO.Flags.Contains( MoveFlags.Sound ) )
                                unitFit += 1;

                        break;
                    }

                    //--Board Effect Compatability
                    if( _ai.UnitSim.PokemonAbilityMatchesWeather( us.Pokemon, currentWeather ) )
                    unitFit += 1;

                    var ourMove = candidate.MoveCandidate;
                    switch( currentWeather )
                    {
                        case WeatherConditionID.Sun:

                            if( ourMove.MoveType == PokemonType.Fire )
                                unitFit += 1;

                        break;

                        case WeatherConditionID.Rain:

                            if( ourMove.MoveType == PokemonType.Water )
                                unitFit += 1;

                        break;

                        case WeatherConditionID.Sand:

                            if( us.Ability == AbilityID.SandForce && ( ourMove.MoveType == PokemonType.Rock || ourMove.MoveType == PokemonType.Ground || ourMove.MoveType == PokemonType.Steel ) )
                                unitFit += 1;

                        break;

                        case WeatherConditionID.Snow:

                            if( ourMove.MoveType == PokemonType.Ice )
                                unitFit += 1;

                        break;
                    }

                    //------------
                    //--Plan Fit--
                    //------------
                    //--Game plan checks
                    bool targetIsTheirWincon = them.Pokemon == gp.TheirPrimaryWinCon;
                    bool targetIsBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                    bool targetIsEnabler = gp.TheirEnablers.Contains( them.Pokemon );
                    bool targetIsGamePlanUnit = targetIsTheirWincon || targetIsBlocker || targetIsEnabler;

                    if( ourPTKO_Them >= PotentialToKO.Dangerous && targetIsGamePlanUnit )
                        planFit += 1;

                    if( mainCapability == CapabilityObservation.FakeOut )
                    {
                        if( targetIsTheirWincon && theirPTKO_Us >= PotentialToKO.Risky )
                            planFit += 1;

                        if( targetIsEnabler )
                            planFit += 1;

                        if( theyHaveAlly )
                        {
                            bool theirAllyIsWincon = theirAlly.Pokemon == gp.TheirPrimaryWinCon;
                            bool theirAllyIsEnabler = gp.TheirEnablers.Contains( theirAlly.Pokemon );

                            if( targetIsTheirWincon && theirAllyIsEnabler || theirAllyIsWincon && targetIsEnabler )
                                planFit += 1;
                        }
                    }

                    if( mainCapability == CapabilityObservation.KnockOff )
                    {
                        if( targetIsGamePlanUnit && theirSP.DependsOnItem )
                            planFit += 1;
                    }

                    if( mainCapability == CapabilityObservation.ThroatChop )
                    {
                        if( targetIsTheirWincon && them.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                            planFit += 1;
                    }

                    //--Strategic Relevance
                    bool targetSupportsAlly = false;
                    bool allySupportsTarget = false;
                    bool switchCandidateSupportsAlly = false;
                    bool allySupportsSwitchCandidate = false;

                    //--Weather Core
                    if( targetSetWeather && theyHaveAlly )
                    {
                        if( targetsWeather == WeatherConditionID.Sun && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SunAbuser ) )
                            targetSupportsAlly = true;

                        if( targetsWeather == WeatherConditionID.Rain && theirAlly.RoleProfile.Traits.Contains( RoleTrait.RainAbuser ) )
                            targetSupportsAlly = true;

                        if( targetsWeather == WeatherConditionID.Sand && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SandAbuser ) )
                            targetSupportsAlly = true;

                        if( targetsWeather == WeatherConditionID.Snow && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SnowAbuser ) )
                            targetSupportsAlly = true;
                    }

                    if( allySetWeather )
                    {
                        if( theirAllyWeather == WeatherConditionID.Sun && them.RoleProfile.Traits.Contains( RoleTrait.SunAbuser ) )
                            allySupportsTarget = true;

                        if( theirAllyWeather == WeatherConditionID.Rain && them.RoleProfile.Traits.Contains( RoleTrait.RainAbuser ) )
                            allySupportsTarget = true;

                        if( theirAllyWeather == WeatherConditionID.Sand && them.RoleProfile.Traits.Contains( RoleTrait.SandAbuser ) )
                            allySupportsTarget = true;

                        if( theirAllyWeather == WeatherConditionID.Snow && them.RoleProfile.Traits.Contains( RoleTrait.SnowAbuser ) )
                            allySupportsTarget = true;
                    }

                    if( switchChangesWeather && theyHaveAlly )
                    {
                        if( switchesWeather == WeatherConditionID.Sun && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SunAbuser ) )
                            switchCandidateSupportsAlly = true;

                        if( switchesWeather == WeatherConditionID.Rain && theirAlly.RoleProfile.Traits.Contains( RoleTrait.RainAbuser ) )
                            switchCandidateSupportsAlly = true;

                        if( switchesWeather == WeatherConditionID.Sand && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SandAbuser ) )
                            switchCandidateSupportsAlly = true;

                        if( switchesWeather == WeatherConditionID.Snow && theirAlly.RoleProfile.Traits.Contains( RoleTrait.SnowAbuser ) )
                            switchCandidateSupportsAlly = true;
                    }

                    //--Terrain Support/Core
                    if( targetSetTerrain && theyHaveAlly )
                    {
                        if( targetsTerrain == TerrainID.Psychic && theirAlly.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) )
                            targetSupportsAlly = true;

                        if( targetsTerrain == TerrainID.Grassy && theirAlly.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) )
                            targetSupportsAlly = true;

                        // if( targetsTerrain == TerrainID.Blighted && theirAlly.RoleProfile.Traits.Contains( RoleTrait.))
                    }

                    if( allySetTerrain )
                    {
                        if( theirAllyTerrain == TerrainID.Psychic && them.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) )
                            allySupportsTarget = true;

                        if( theirAllyTerrain == TerrainID.Grassy && them.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) )
                            allySupportsTarget = true;
                    }

                    if( switchChangesTerrain && theyHaveAlly )
                    {
                        if( switchesTerrain == TerrainID.Psychic && theirAlly.RoleProfile.Traits.Contains( RoleTrait.PsychicTerrainAbuser ) )
                            switchCandidateSupportsAlly = true;

                        if( switchesTerrain == TerrainID.Grassy && theirAlly.RoleProfile.Traits.Contains( RoleTrait.GrassyTerrainAbuser ) )
                            switchCandidateSupportsAlly = true;
                    }

                    //--Redirection Support
                    if( ip.TheyWant.FollowMe || ip.TheyWant.RagePowder )
                    {
                        targetSupportsAlly = true;

                        //--Direct reward for fake out here because it has higher priority than redirection and is a direct means of shutting it down.
                        if( mainCapability == CapabilityObservation.FakeOut )
                        {
                            planFit += 1;
                        }
                    }

                    //--Trick Room Setter/Core
                    if( theirSP.DependsOnTrickRoom && theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.TrickRoomSetter ) )
                        allySupportsTarget = true;

                    if( theyHaveAlly && theirAllySP.DependsOnTrickRoom && them.RoleProfile.Traits.Contains( RoleTrait.TrickRoomSetter ) )
                    {
                        targetSupportsAlly = true;

                        if( ip.TheyWant.SetTrickRoom && ( mainCapability == CapabilityObservation.FakeOut || ourPTKO_Them >= PotentialToKO.Dangerous ) )
                            planFit += 2;
                    }

                    //--Tailwind Setter + Offensive Unit
                    if( them.RoleProfile.Traits.Contains( RoleTrait.TailwindAbuser ) && theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.TailwindSetter ) )
                        allySupportsTarget = true;

                    if( theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.TailwindAbuser ) && them.RoleProfile.Traits.Contains( RoleTrait.TailwindSetter ) )
                    {
                        targetSupportsAlly = true;

                        if( ip.TheyWant.SetTailwind && ( mainCapability == CapabilityObservation.FakeOut || ourPTKO_Them >= PotentialToKO.Dangerous && attackerMovesFirst ) )
                            planFit += 1;
                    }

                    if( theyHaveSwitch && theyHaveAlly )
                    {
                        if( theirSwitch.RoleProfile.Traits.Contains( RoleTrait.TailwindAbuser ) && theirAlly.RoleProfile.Traits.Contains( RoleTrait.TailwindSetter ) )
                        {
                            switchCandidateSupportsAlly = true;
                        }

                        if( theirSwitch.RoleProfile.Traits.Contains( RoleTrait.TailwindSetter ) && theirAlly.RoleProfile.Traits.Contains( RoleTrait.TailwindAbuser ) )
                        {
                            allySupportsSwitchCandidate = true;

                            if( !theirCourt.ContainsKey( CourtConditionID.Tailwind ) || theirCourt.TryGetValue( CourtConditionID.Tailwind, out var theirTW ) && theirTW <= 1 )
                            {
                                if( mainCapability == CapabilityObservation.KnockOff || mainCapability == CapabilityObservation.CoverageMove )
                                    planFit += 2;
                                else if( mainCapability != CapabilityObservation.FakeOut )
                                    planFit += 1;
                            }
                        }
                    }

                    //--Offensive Unit + Screens setter
                    if( them.RoleProfile.Traits.Contains( RoleTrait.ScreensAbuser ) && theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.ScreenSetter ) )
                        targetSupportsAlly = true;

                    if( them.RoleProfile.Traits.Contains( RoleTrait.ScreenSetter ) && theyHaveAlly && theirAlly.RoleProfile.Traits.Contains( RoleTrait.ScreensAbuser ) )
                    {
                        allySupportsTarget = true;
                    }

                    if( ip.TheyWant.SetReflect || ip.TheyWant.SetLightScreen || ip.TheyWant.SetAuroraVeil )
                    {
                        if( mainCapability == CapabilityObservation.FakeOut )
                        {
                            planFit += 1;
                        }

                        if( mainCapability == CapabilityObservation.BrickBreak || mainCapability == CapabilityObservation.PsychicFangs )
                        {
                            if( !attackerMovesFirst )
                                planFit += 1;
                            else if( theirCourt.ContainsKey( CourtConditionID.Reflect ) && ip.TheyWant.SetLightScreen )
                                planFit += 1;
                            else if( theirCourt.ContainsKey( CourtConditionID.LightScreen ) && ip.TheyWant.SetReflect )
                                planFit += 1;
                            else if( ( theirCourt.ContainsKey( CourtConditionID.Reflect ) || theirCourt.ContainsKey( CourtConditionID.LightScreen ) ) && ip.TheyWant.SetAuroraVeil )
                                planFit += 1;
                        }
                    }

                    if( theyHaveSwitch && theyHaveAlly )
                    {
                        if( theirSwitch.RoleProfile.Traits.Contains( RoleTrait.ScreensAbuser ) && theirAlly.RoleProfile.Traits.Contains( RoleTrait.ScreenSetter ) )
                            allySupportsSwitchCandidate = true;

                        if( theirSwitch.RoleProfile.Traits.Contains( RoleTrait.ScreenSetter ) && theirAlly.RoleProfile.Traits.Contains( RoleTrait.ScreensAbuser ) )
                            switchCandidateSupportsAlly = true;
                    }

                    //--General Offensive and Utility archetype Pair
                    if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive && theyHaveAlly && theirAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                        targetSupportsAlly = true;

                    if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility && theyHaveAlly && theirAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                        allySupportsTarget = true;

                    if( theyHaveAlly && theyHaveSwitch )
                    {
                        if( theirSwitch.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive && theirAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                            allySupportsSwitchCandidate = true;

                        if( theirSwitch.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility && theirAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                            switchCandidateSupportsAlly = true;
                    }

                    if( targetSupportsAlly )
                    {
                        if( mainCapability == CapabilityObservation.FakeOut )
                            planFit += 1;

                        if( them.Item != ItemBattleEffectID.None && theirSP.DependsOnItem && mainCapability == CapabilityObservation.KnockOff )
                            planFit += 1;
                    }

                    if( allySupportsTarget )
                    {
                        if( mainCapability == CapabilityObservation.FakeOut )
                            planFit += 1;

                        if( ourPTKO_Them == PotentialToKO.OHKO )
                            planFit += 1;
                    }

                    if( switchCandidateSupportsAlly )
                    {
                        if( mainCapability == CapabilityObservation.FakeOut )
                            planFit -= 2;

                        if( mainCapability == CapabilityObservation.KnockOff )
                            planFit += 1;

                        if( mainCapability == CapabilityObservation.ThroatChop && theirSwitch.RoleProfile.Traits.Contains( RoleTrait.SoundMoves ) )
                            planFit += 1;
                    }

                    if( allySupportsSwitchCandidate )
                    {
                        if( mainCapability == CapabilityObservation.CoverageMove )
                        {
                            if( theyHaveSwitch && usVsSwitch.Attacker.BestCurrentPTKO >= PotentialToKO.Dangerous )
                                planFit += 2;
                        }
                    }

                    //-------------
                    //--Cost/Risk--
                    //-------------
                    bool targetSurvives = ourPTKO_Them <= PotentialToKO.Risky;
                    if( targetSurvives )
                    {
                        if( !attackerMovesFirst )
                            costRisk += 1;

                        if( theirPTKO_Us >= PotentialToKO.Dangerous )
                            costRisk += 1;
                    }

                    //--Check their ally's target and expected action
                    if( theirAllyHasIntent )
                    {
                        bool theirAllyHasTargets = theirAllyActionResult.Targets != null && theirAllyActionResult.Targets.Count > 0;
                        PotentialToKO theirAllyPTKO = theirAllyTargetsUs && ip.UsVsTheirAlly.Target.CurrentPTKOs.ContainsKey( theirAllyActionResult.Move ) ? ip.UsVsTheirAlly.Target.CurrentPTKOs[theirAllyActionResult.Move] : default;

                        if( theirAllyAction == ActionType.Attack )
                        {
                            if( theirAllyTargetsUs && theirAllyPTKO >= PotentialToKO.Dangerous )
                            {
                                costRisk += 1;
                                
                                if( targetSurvives && ( mainCapability == CapabilityObservation.StrongestAttack || mainCapability == CapabilityObservation.CoverageMove ) && theirPTKO_Us >= PotentialToKO.Risky )
                                    costRisk += 1;
                            }

                            if( !theirAllyTargetsUs && weHaveAlly )
                            {
                                var allyVsTheirAlly = theyHaveAlly ? _ai.Projection.MakeUnitComparison( theirAllyActionResult.Top.Attacker, theirAllyActionResult.Top.Opponent ) : default;
                                if( theyHaveAlly && allyVsTheirAlly.Target.BestCurrentPTKO >= PotentialToKO.Dangerous && theirAllyPTKO <= PotentialToKO.Risky )
                                    costRisk += 1;
                            }
                        }
                    }

                    if( ip.TheyWant.Protect )
                        costRisk += 1;

                    if( ( ourPTKO_Them >= PotentialToKO.Dangerous || mainCapability == CapabilityObservation.FakeOut ) && usVsSwitch.Attacker.BestCurrentPTKO <= PotentialToKO.TwoHKO )
                        costRisk += 1;

                    if( ourPTKO_Them >= PotentialToKO.Dangerous && theirPTKO_Us >= PotentialToKO.Risky && !attackerMovesFirst )
                    {
                        //--If they survive our dangerous PTKO attack with the ability to do significant damage and move first
                        costRisk += 1;
                    }

                    // Could this unit instead use a much more strategically important capability? -> not realistic to check, this should be handled naturally by scoring
                    // Does attacking consume a one-time resource? -> not necessarily worth penalizing, especially in the case of fake out. not faking out is worse than consuming your fake out.
                    // Does attacking prevent us from establishing something important? -> again should be handled by scoring other capabilities
                    // Are we abandoning an important defensive action? -> again should be handled by scoring other capabilities
                }

                int finalScore = pressureFitScore + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    PressureFitScore = pressureFitScore,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,
                    FinalScore = finalScore,
                };
                
                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetSwitchResponses( Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = GetPokemonBench( ourActive[0].Pokemon ).ToList();

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = GetPokemonBench( theirActive[0].Pokemon ).ToList();
    
        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();
            Dictionary<CapabilityObservation, HashSet<StrategyPressureEvidence>> activeCapabilitySets = ExtractUniqueCapabilities( ActionType.DefensiveSwitch, unit.Pokemon, pressureSets );
            Dictionary<CapabilityObservation, HashSet<StrategyPressureEvidence>> benchCapabilitySets = new();

            foreach( var switchCandidate in ourBench )
            {
                // Debug.LogError( $"Getting unique capabilities for {switchCandidate.Name}" );
                //--We need to essentially check each unit's situation and how they measure up with each benched pokemon as their potential switch candidate
                //--i think that, simply, when building GetSwitchCandidates(), it should take in the active mon, the switch candidate, and pressureSets
                //--when building out the CoordinationAction for candidate scoring, we will then have access to the current Actor, and the SwitchCandidate
                //--which actually sounds very powerful. actively checking which active unit is best to switch out into which benched pokemon is best to handle
                //--the current situation as a response is quite nuanced and leaves no stone unturned.
                benchCapabilitySets = ExtractUniqueCapabilities( ActionType.DefensiveSwitch, switchCandidate.Pokemon, pressureSets );

                if( benchCapabilitySets?.Count <= 0 )
                    continue;

                foreach( var kvp in benchCapabilitySets )
                {
                    var capability = kvp.Key;
                    var pressures = kvp.Value;

                    foreach( var opp in theirActive )
                    {
                        var candidate = GetSwitchCandidate( capability, unit, switchCandidate, opp, CoordinationActionType.Response );
                        candidate.RelevantPressures = pressures;
                        candidates.Add( candidate );
                    }
                }
            }

            foreach( var candidate in candidates )
            {
                int pressureFit = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                int defensiveAlignment = 0;
                int offensiveAlignment = 0;

                var mainCapability = candidate.Capability;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );
                var ourSwitch = _ai.GetPokemonAs_IBattleAIUnit( candidate.SwitchCandidate );

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var ourSwitchSP = _ai.Projection.GetStrategicProfile( ourSwitch );
                var theirSP = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                //--Pressure Fit
                pressureFit += candidate.RelevantPressures.Count;
                //--Candidate x Pressure family relevance goes here

                foreach( var e in candidate.RelevantPressures )
                {
                    var usIP = GetInteractionProfile( us, them, candidate, e );

                    CoordinationAction switchCandidate = new()
                    {
                        Type = CoordinationActionType.SwitchCandidatePotential,
                        Actor = ourSwitch.Pokemon,
                        Action = ActionType.Attack,
                    };

                    var ourSwitchIP = GetInteractionProfile( ourSwitch, them, switchCandidate, e );

                    var ourPTKO = usIP.AttackerPTKO;
                    var ourSwitchPTKO = ourSwitchIP.AttackerPTKO;

                    var theirPTKO_Us = usIP.TargetPTKO;
                    var theirPTKO_OurSwitch = ourSwitchIP.TargetPTKO;

                    var theirAction = usIP.TheirAction;

                    bool theyUseAMove = theirAction != ActionType.OffensiveSwitch && theirAction != ActionType.DefensiveSwitch;
                    bool theySwitch = !theyUseAMove;

                    var theirMove = theyUseAMove && usIP.TheirActionResult.Move != null ? usIP.TheirActionResult.Move : null;
                    List<IBattleAIUnit> targetsTargets = usIP.TheirActionResult.Targets != null && usIP.TheirActionResult.Targets.Count > 0 ? usIP.TheirActionResult.Targets : null;
                    bool targetsUs = targetsTargets != null && targetsTargets?.Count > 0 && targetsTargets.Any( u => u.Pokemon == us.Pokemon );

                    SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)usIP.TheirActionResult : default;
                    var theirSwitch = theySwitch ? scr.Candidate : null;
                    bool theyHaveSwitch = theirSwitch != null;
                    var usVsSwitch = theyHaveSwitch && theirSwitch != null ? _ai.Projection.MakeUnitComparison( us, theirSwitch ) : default;

                    bool targetCanProtect = _ai.CanUseProtect( them.Pokemon );

                    bool weHaveAlly = TryGetAlly( us.Pokemon, out var ourAlly );
                    bool theyHaveAlly = TryGetOpponentAlly_FromStrategy( them.Pokemon, e, out IBattleAIUnit theirAlly );

                    bool targetsOurAlly = weHaveAlly && ourAlly != null && targetsTargets?.Count > 0 && targetsTargets.Any( u => u.Pokemon == ourAlly.Pokemon );

                    bool theirAllyHasIntent = TryGetOpponentAllyIntent_FromStrategy( them.Pokemon, e, out Intent theirAllyIntent );
                    var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                    var ourAllyVsThem = weHaveAlly ? _ai.Projection.MakeUnitComparison( ourAlly, them ) : default;
                    var usVsTheirAlly = theyHaveAlly ? _ai.Projection.MakeUnitComparison( us, theirAlly ) : default;
                    var ourAllyVsTheirAlly = theyHaveAlly && weHaveAlly ? _ai.Projection.MakeUnitComparison( ourAlly, theirAlly ) : default;
                    var ourSwitchVsTheirAlly = theyHaveAlly ? _ai.Projection.MakeUnitComparison( ourSwitch, theirAlly ) : default;

                    bool theyHavePrankster = them.Ability == AbilityID.Prankster;
                    bool theyAreUsingPrankster = theyUseAMove && theirMove != null && theirMove.MoveSO.MoveCategory == MoveCategory.Status;
                    bool theirPranksterIsOffensive = theyAreUsingPrankster && theirAction == ActionType.OffensiveStatus;
                    bool theirMoveHasPriority = theyUseAMove && theirMove != null && theirMove.Priority > MovePriority.Zero;

                    ActionType theirAllyAction = ActionType.Attack;
                    IActionResult theirAllyActionResult = default;
                    Move theirAllyMove = null;

                    PotentialToKO ourAllyPTKO_Them = ourAllyVsThem.Attacker.BestCurrentPTKO;
                    PotentialToKO ourAllyPTKO_TheirAlly = ourAllyVsTheirAlly.Attacker.BestCurrentPTKO;
                    PotentialToKO theirAllyPTKO_Us = usVsTheirAlly.Target.BestCurrentPTKO;
                    PotentialToKO theirAllyPTKO_OurAlly = ourAllyVsTheirAlly.Target.BestCurrentPTKO;
                    PotentialToKO theirAllyPTKO_OurSwitch = ourSwitchVsTheirAlly.Target.BestCurrentPTKO;
                    PotentialToKO theirPTKO_OurAlly = ourAllyVsThem.Target.BestCurrentPTKO;

                    Move ourAllyMove = ourAllyPTKO_Them > ourAllyPTKO_TheirAlly ? ourAllyVsThem.Attacker.CurrentPTKOs.Keys.First() : ourAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First();

                    bool theirAllyUsesMove = false;
                    bool theirAllyHasPrankster = theyHaveAlly && theirAlly.Ability == AbilityID.Prankster;
                    bool theirAllyIsUsingPrankster = false;
                    bool theirAllyPranksterIsOffensive = false;
                    bool theirAllyMoveHasPriority = false;

                    bool theirAllyTargetsUs = false;
                    bool theirAllyTargetsOurAlly = false;

                    if( theirAllyHasIntent )
                    {
                        theirAllyAction = theirAllyIntent.IntentResult.ActionType;
                        theirAllyActionResult = theirAllyIntent.IntentResult;
                        
                        theirAllyUsesMove = theirAllyAction != ActionType.DefensiveSwitch && theirAllyAction != ActionType.OffensiveSwitch;
                        theirAllyMove = theirAllyUsesMove && theirAllyActionResult.Move != null ? theirAllyActionResult.Move : null;

                        theirAllyIsUsingPrankster = theirAllyHasPrankster && theirAllyUsesMove && theirAllyMove.MoveSO.MoveCategory == MoveCategory.Status;
                        theirAllyPranksterIsOffensive = theirAllyIsUsingPrankster && theirAllyAction == ActionType.OffensiveStatus;
                        theirAllyMoveHasPriority = theirAllyUsesMove && theirAllyMove.Priority > MovePriority.Zero;

                        if( weHaveAlly )
                        {
                            if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets[0]?.Pokemon == us.Pokemon )
                                theirAllyTargetsUs = true;
                            else if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets[0]?.Pokemon == ourAlly.Pokemon )
                                theirAllyTargetsOurAlly = true;

                            if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 1 && theirAllyActionResult.Targets[1]?.Pokemon == us.Pokemon )
                                theirAllyTargetsUs = true;

                            if( theirAllyUsesMove && theirAllyActionResult.Targets?.Count > 1 && theirAllyActionResult.Targets[1]?.Pokemon == ourAlly.Pokemon )
                                theirAllyTargetsOurAlly = true;
                        }
                    }

                    Move ourMove = usIP.UsVsThem.Attacker.CurrentPTKOs.Keys.First();
                    Dictionary<IBattleAIUnit, Move> turnOrderUnits = new()
                    {
                        { us, ourMove },
