                    };

                    if( ourAlly != null )
                        turnOrderUnits.Add( ourAlly, ourAllyMove );

                    if( theirAlly != null )
                        turnOrderUnits.Add( theirAlly, theirAllyMove );

                    var turnOrder = GetTurnOrder( turnOrderUnits, e, field );

                    WeatherConditionID targetsWeather = WeatherConditionID.None;
                    WeatherConditionID theirAllyWeather = WeatherConditionID.None;
                    WeatherConditionID switchesWeather = WeatherConditionID.None;

                    bool targetSetWeather = _ai.UnitSim.Pokemon_SetWeather( them.Pokemon, out targetsWeather, currentWeather );
                    bool allySetWeather = theyHaveAlly && _ai.UnitSim.Pokemon_SetWeather( theirAlly?.Pokemon, out theirAllyWeather, currentWeather );
                    bool switchChangesWeather = theyHaveSwitch && _ai.UnitSim.Switch_ChangesWeather( scr, out switchesWeather, null );

                    TerrainID targetsTerrain = TerrainID.None;
                    TerrainID theirAllyTerrain = TerrainID.None;
                    TerrainID switchesTerrain = TerrainID.None;

                    bool targetSetTerrain = _ai.UnitSim.Pokemon_SetTerrain( them.Pokemon, out targetsTerrain, currentTerrain );
                    bool allySetTerrain = theyHaveAlly && _ai.UnitSim.Pokemon_SetTerrain( theirAlly?.Pokemon, out theirAllyTerrain, currentTerrain );
                    bool switchChangesTerrain = theyHaveSwitch && _ai.UnitSim.Switch_ChangesTerrain( scr, out switchesTerrain, null );

                    //--Board Fit
                    //--If an active unit has a relevant capability that can respond to current pressures, it may be worth preserving as the returning pokemon
                    if( CheckIfPokemonHasRelevantSwitchCapability( us.Pokemon, activeCapabilitySets ) )
                        boardFit += 1;

                    foreach( var kvp in activeCapabilitySets )
                    {
                        var cap = kvp.Key;
                        var activePressureSets = kvp.Value;

                        foreach( var spe in activePressureSets )
                        {
                            if( CheckIfPressureResponse( e.Pressure, cap ) )
                            {
                                if( mainCapability == CapabilityObservation.RawSwitch )
                                    boardFit += 1;

                                if( cap == CapabilityObservation.Intimidate || cap == CapabilityObservation.Demoralize || cap == CapabilityObservation.Hospitality )
                                    boardFit += 2;

                                if( cap == CapabilityObservation.WeatherSetAbility )
                                {
                                    if( usIP.TheyWant.SetAbilityWeather )
                                        boardFit += 2;

                                    if( theirSP.DependsOnCurrentWeather || ( theyHaveAlly && theirAllySP.DependsOnCurrentWeather ) )
                                    {
                                        if( currentWeather != _ai.UnitSim.GetWeatherFrom_Ability( us.Pokemon ) )
                                            boardFit += 2; 
                                    }

                                    if( usIP.TheyWant.SetMoveWeather || usIP.TheyWant.SetAbilityWeather )
                                        boardFit += 2;

                                    if( theyHaveSwitch && switchChangesWeather )
                                    {
                                        var ourWeather = _ai.UnitSim.GetWeatherFrom_Ability( us.Pokemon );
                                        if( ourWeather != WeatherConditionID.None && ourWeather != switchesWeather )
                                            boardFit += 3;

                                        if( spe.SourceStrategy.Strategy == PairStrategy.WeatherPivot )
                                            boardFit += 2;
                                    }
                                }

                                if( cap == CapabilityObservation.TerrainSetAbility )
                                {
                                    if( usIP.TheyWant.SetAbilityTerrain )
                                        boardFit += 1;

                                    if( theirSP.DependsOnCurrentTerrain || ( theyHaveAlly && theirAllySP.DependsOnCurrentTerrain ) )
                                    {
                                        if( currentTerrain != _ai.UnitSim.GetTerrainFrom_Ability( us.Pokemon ) )
                                            boardFit += 1; 
                                    }

                                    if( usIP.TheyWant.SetMoveTerrain|| usIP.TheyWant.SetAbilityTerrain)
                                        boardFit += 1;
                                }

                                if( cap == CapabilityObservation.BatonPass )
                                {
                                    var statStages = us.StatStages;
                                    int boosts = 0;
                                    int reductions = 0;
                                    foreach( var sc in statStages )
                                    {
                                        if( sc.Value > 0 )
                                            boosts += sc.Value;
                                        else if( sc.Value < 0 )
                                            reductions += sc.Value;
                                    }

                                    if( boosts > 3 )
                                        boardFit += 3;
                                    else if( boosts > 1 )
                                        boardFit += 2;
                                    else if( boosts > 0 )
                                        boardFit += 1;

                                    if( reductions > 0 && boosts <= 0 )
                                        boardFit -= 2;
                                }
                            }
                        }
                    }

                    //--Results of immediate entry effects, and their interactions/match up improvements. does setting rain dynamically increase speed or create a better ptko? does intimidate reduce a threatening ptko?
                    if( mainCapability == CapabilityObservation.AbilityPriorityBlock )
                    {
                        if( theirPranksterIsOffensive || theirMoveHasPriority )
                            boardFit += 2;

                        if( weHaveAlly && !targetsUs )
                            boardFit += 1;

                        if( targetsUs )
                            boardFit += 1;

                        if( theirAllyHasIntent )
                        {
                            if( theirAllyPranksterIsOffensive || theirAllyMoveHasPriority )
                            {
                                boardFit += 2;

                                if( theirAllyTargetsOurAlly )
                                    boardFit += 1;

                                if( theirAllyTargetsUs )
                                    boardFit += 1;
                            }
                        }

                        if( usIP.TheyWant.FakeOut )
                            boardFit += 1;

                        if( theyHaveAlly && ( _ai.CanUseFakeOut( theirAlly, us ) || ( weHaveAlly && _ai.CanUseFakeOut( theirAlly, ourAlly ) ) ) )
                            boardFit += 1;

                        defensiveAlignment++;
                    }

                    if( mainCapability == CapabilityObservation.Intimidate )
                    {
                        if( them.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                            boardFit += 1;

                        if( theyUseAMove && theirMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                        {
                            defensiveAlignment++;

                            boardFit += 1;

                            if( targetsUs )
                                boardFit += 1;

                            if( weHaveAlly && !targetsUs )
                                boardFit += 1;

                            if( theirMove.MoveSO.Name != "Foul Play" && theirMove.MoveSO.Name != "Body Press" )
                            {
                                Dictionary<Stat, int> intimidate = new(){ { Stat.Attack, -1 } };
                                var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                                var theirEDR = theirMTR.EDR;

                                if( targetsUs )
                                {
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat: Stat.Attack, attackerStatStageChanges: intimidate );

                                    if( adjustedPTKO < theirPTKO_Us )
                                    {
                                        boardFit += 1;

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                            boardFit += 1;
                                    }
                                }

                                if( weHaveAlly && ourAlly != null && !targetsUs )
                                {
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, attackStat: Stat.Attack, attackerStatStageChanges: intimidate );

                                    if( adjustedPTKO < theirPTKO_OurAlly )
                                    {
                                        boardFit += 1;

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_OurAlly - adjustedPTKO >= 2 )
                                            boardFit += 1;
                                    }
                                }
                            }
                        }

                        if( theirAllyHasIntent && theirAlly != null )
                        {
                            if( theirAlly.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                boardFit += 1;

                            if( theirAllyUsesMove && theirAllyMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                            {
                                defensiveAlignment++;

                                boardFit += 1;

                                if( theirAllyTargetsUs )
                                    boardFit += 1;

                                if( theirAllyTargetsOurAlly )
                                    boardFit += 1;

                                if( theirAllyMove?.MoveSO.Name != "Foul Play" && theirAllyMove?.MoveSO.Name != "Body Press" )
                                {
                                    Dictionary<Stat, int> intimidate = new(){ { Stat.Attack, -1 } };
                                    var theirAllyMTR = (MoveThreatResult)theirAllyActionResult;
                                    var theirAllyEDR = theirAllyMTR.EDR;

                                    if( theirAllyTargetsUs )
                                    {
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat: Stat.Attack, attackerStatStageChanges: intimidate );

                                        if( adjustedPTKO < theirPTKO_Us )
                                        {
                                            boardFit += 1;

                                            if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                                boardFit += 1;
                                        }
                                    }

                                    if( weHaveAlly && ourAlly != null && theirAllyTargetsOurAlly )
                                    {
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, ourAlly, attackStat: Stat.Attack, attackerStatStageChanges: intimidate );

                                        if( adjustedPTKO < theirAllyPTKO_OurAlly )
                                        {
                                            boardFit += 1;

                                            if( adjustedPTKO <= PotentialToKO.TwoHKO || theirAllyPTKO_OurAlly - adjustedPTKO >= 2 )
                                                boardFit += 1;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if( mainCapability == CapabilityObservation.Demoralize )
                    {
                        if( them.RoleProfile.Biases.Contains( RoleBias.Special ) )
                            boardFit += 1;

                        if( theyUseAMove && theirMove?.MoveSO.MoveCategory == MoveCategory.Special )
                        {
                            defensiveAlignment++;
                            boardFit += 1;

                            if( targetsUs )
                                boardFit += 1;

                            if( weHaveAlly && !targetsUs )
                                boardFit += 1;

                            Dictionary<Stat, int> demoralize = new(){ { Stat.SpAttack, -1 } };
                            var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                            var theirEDR = theirMTR.EDR;

                            if( targetsUs )
                            {
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat: Stat.SpAttack, attackerStatStageChanges: demoralize );

                                if( adjustedPTKO < theirPTKO_Us )
                                {
                                    boardFit += 1;

                                    if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                        boardFit += 1;
                                }
                            }

                            if( weHaveAlly && ourAlly != null && !targetsUs )
                            {
                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, attackStat: Stat.SpAttack, attackerStatStageChanges: demoralize );

                                if( adjustedPTKO < theirPTKO_OurAlly )
                                {
                                    boardFit += 1;

                                    if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_OurAlly - adjustedPTKO >= 2 )
                                        boardFit += 1;
                                }
                            }
                        }

                        if( theirAllyHasIntent && theirAlly != null )
                        {
                            if( theirAlly.RoleProfile.Biases.Contains( RoleBias.Special ) )
                                boardFit += 1;

                            if( theirAllyUsesMove && theirAllyMove?.MoveSO.MoveCategory == MoveCategory.Special )
                            {
                                defensiveAlignment++;
                                boardFit += 1;

                                if( theirAllyTargetsUs )
                                    boardFit += 1;

                                if( theirAllyTargetsOurAlly )
                                    boardFit += 1;

                                Dictionary<Stat, int> demoralize = new(){ { Stat.SpAttack, -1 } };
                                var theirAllyMTR = (MoveThreatResult)theirAllyActionResult;
                                var theirAllyEDR = theirAllyMTR.EDR;

                                if( theirAllyTargetsUs )
                                {
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat: Stat.SpAttack, attackerStatStageChanges: demoralize );

                                    if( adjustedPTKO < theirPTKO_Us )
                                    {
                                        boardFit += 1;

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                            boardFit += 1;
                                    }
                                }

                                if( weHaveAlly && ourAlly != null && theirAllyTargetsOurAlly )
                                {
                                    var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, ourAlly, attackStat: Stat.SpAttack, attackerStatStageChanges: demoralize );

                                    if( adjustedPTKO < theirAllyPTKO_OurAlly )
                                    {
                                        boardFit += 1;

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirAllyPTKO_OurAlly - adjustedPTKO >= 2 )
                                            boardFit += 1;
                                    }
                                }
                            }
