                    }

                    if( mainCapability == CapabilityObservation.WeatherSetAbility || mainCapability == CapabilityObservation.CloudNine )
                    {
                        var ourCandidateWeather = _ai.UnitSim.GetWeatherFrom_Ability( ourSwitch.Pokemon );

                        bool theyDependOnCurrentWeather = theirSP.DependsOnCurrentWeather;
                        bool theirAllyDependsOnCurrentWeather = theyHaveAlly && theirAllySP.DependsOnCurrentWeather;
                        bool theyWantChangeWeather = usIP.TheyWant.SetMoveWeather || usIP.TheyWant.SetAbilityWeather;

                        if( theyDependOnCurrentWeather || theirAllyDependsOnCurrentWeather )
                            boardFit += 1;

                        if( weHaveAlly && ourAlly != null )
                        {
                            if( ourCandidateWeather == WeatherConditionID.Sun && ourAlly.RoleProfile.Traits.Contains( RoleTrait.SunAbuser ) )
                            {
                                boardFit += 1;
                                offensiveAlignment++;
                            }

                            if( ourCandidateWeather == WeatherConditionID.Rain && ourAlly.RoleProfile.Traits.Contains( RoleTrait.RainAbuser ) )
                            {
                                boardFit += 1;
                                offensiveAlignment++;
                            }

                            if( ourCandidateWeather == WeatherConditionID.Sand && ourAlly.RoleProfile.Traits.Contains( RoleTrait.SandAbuser ) )
                            {
                                boardFit += 1;
                                offensiveAlignment++;
                            }

