                            {
                                boardFit += 1;
                                offensiveAlignment++;
                            }
                        }

                        if( theyWantChangeWeather )
                        {
                            if( theySwitch && them.Speed > us.Speed )
                                boardFit += 1;

                            if( currentWeather != ourCandidateWeather && currentWeather != WeatherConditionID.None )
                            {
                                if( currentWeather == WeatherConditionID.Sun )
                                {
                                    if( theyUseAMove && theirMove != null && theirMove.MoveType == PokemonType.Fire && theirMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirMTR = (MoveThreatResult)usIP.TheirActionResult;
                                        var theirEDR = theirMTR.EDR;

                                        if( ourCandidateWeather == WeatherConditionID.Rain )
                                            boardFit += 2;

                                        if( _ai.UnitSim.PokemonHasMove_AbusesWeather( them.Pokemon, currentWeather ) )
                                            boardFit += 1;

                                        Stat attackStat = theirMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeSunModifier = 1.5f;
                                        float addRainModifier = ourCandidateWeather == WeatherConditionID.Rain ? 0.5f : 1f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackStat, defenseStat, removeModifier: removeSunModifier, addModifier: addRainModifier );

                                        if( adjustedPTKO < theirPTKO_Us )
                                        {
