                                    if( theirAllyHasIntent && theirAllyUsesMove && theirAllyMove != null && theirAllyMove.MoveType == PokemonType.Fire && theirAllyMove.MoveSO.MoveCategory != MoveCategory.Status )
                                    {
                                        var theirAllyMTR = (MoveThreatResult)theirAllyActionResult;
                                        var theirAllyEDR = theirAllyMTR.EDR;

