                                            boardFit += 1;

                                        Stat attackStat = theirAllyMove.MoveSO.MoveCategory == MoveCategory.Physical ? Stat.Attack : Stat.SpAttack;
                                        Stat defenseStat = attackStat == Stat.Attack ? Stat.Defense : Stat.SpDefense;

                                        float removeSunModifier = 1.5f;
                                        float addRainModifier = ourCandidateWeather == WeatherConditionID.Rain ? 0.5f : 1f;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirAllyEDR, theirAlly, us, attackStat, defenseStat, removeModifier: removeSunModifier, addModifier: addRainModifier );

                                        if( adjustedPTKO < theirAllyPTKO_Us )
                                        {
                                            boardFit += 1;
                                            defensiveAlignment++;
                                        }

