                                    boardFit += 1;

                                if( theyTargetOurAlly && theirPTKO_OurAlly >= PotentialToKO.Risky )
                                    boardFit += 1;

                                if( ourPTKO >= PotentialToKO.TwoHKO )
                                    boardFit += 1;

                                if( ourAlly != null && ourAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive && ourAllyPTKO_Them >= PotentialToKO.TwoHKO )
                                    boardFit += 1;
