                    }

                    //--Disruption
                    if( disruption )
                    {
                        if( mainCapability == CapabilityObservation.Taunt )
                        {
                            //--you need to come up with a way to determine the intrinstic usefulness of taunt on the current target
                            //--a pokemon with 3 attacks + protect is not necessarily a rich taunt target. preventing protect is fine
                            //--but realistically it shouldn't out perform other options.

                            if( theirAction != ActionType.Attack )
                            {
                                boardFit += 1;
                            }
                            else
                            {
                                boardFit -= 3;
                            }

                            if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                            {
                                boardFit += 1;

                                if( theirAction != ActionType.Attack && theirAction == ActionType.DefensiveSwitch && theirAction != ActionType.OffensiveSwitch )
                                {
                                    boardFit += 1;
                                    wePreventTheirAction = true;
