                            if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                            {
                                boardFit += 1;
                                weCrippleTheirSupport = true;
                            }

                            if( them.RoleProfile.Signals.StatusMoveCount >= 3 )
                                weLockThemDown = true;
                            else if( them.RoleProfile.Signals.StatusMoveCount >= 1 )
                                boardFit -= 5;
                            else if( them.RoleProfile.Signals.StatusMoveCount < 1 )
                                boardFit -= 10;

                            if( them.RoleProfile.PrimaryRole == RoleClass.SetupSweeper || them.RoleProfile.PrimaryRole == RoleClass.DefensiveSetup )
                                boardFit += 1;

                            if( ip.TheyCan.FollowMe || ip.TheyCan.RagePowder )
                                boardFit += 1;

                            if( ip.TheyCan.HelpingHand )
                                boardFit += 1;

                            if( theirSP.ProvidesSupport || theirSP.CriticalSupport )
                                boardFit += 1;

                            if( theirSP.CriticalDisruptor )
                                boardFit += 1;

                            if( ( weLockThemDown || weCrippleTheirSupport ) && theirBench.Count <= 0 )
                                boardFit += 2;
                        }

                        if( mainCapability == CapabilityObservation.Encore )
                        {
                            if( theirPTKO_Us <= PotentialToKO.TwoHKO )
                            {
                                if( theirAction == ActionType.Attack && ( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) ) )
                                {
                                    boardFit += 1;
                                    weLockThemDown = true;
                                }

                                if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                {
                                    var theirBattleUnit = _ai.GetBattleUnit( them.Pokemon );
                                    if( theirBattleUnit != null && theirBattleUnit.Pokemon == them.Pokemon && theirBattleUnit.LastUsedMove != null )
                                    {
                                        if( theirBattleUnit.LastUsedMove.MoveSO.MoveCategory == MoveCategory.Status )
                                        {
                                            boardFit += 1;
                                            weLockThemDown = true;

                                            if( theirBattleUnit.LastUsedMove.MoveSO.Name == "Trick Room" && field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                                                boardFit += 1;

                                            if( _ai.UnitSim.MoveIsSetup( theirBattleUnit.LastUsedMove ) )
                                                boardFit += 1;
                                        }
                                        else if( theirPTKO_Us <= PotentialToKO.Safe )
                                        {
                                            boardFit += 1;
                                            weLockThemDown = true;
                                        }
                                    }
                                }
                            }

                            if( ourAlly != null && theirPTKO_OurAlly <= PotentialToKO.TwoHKO )
                            {
                                if( theirAction == ActionType.Attack && ( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) ) )
                                {
                                    boardFit += 1;
                                    weLockThemDown = true;
                                }

                                if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                {
                                    var theirBattleUnit = _ai.GetBattleUnit( them.Pokemon );
                                    if( theirBattleUnit != null && theirBattleUnit.Pokemon == them.Pokemon && theirBattleUnit.LastUsedMove != null )
                                    {
                                        if( theirBattleUnit.LastUsedMove.MoveSO.MoveCategory == MoveCategory.Status )
                                        {
                                            boardFit += 1;
                                            weLockThemDown = true;

                                            if( theirBattleUnit.LastUsedMove.MoveSO.Name == "Trick Room" && field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                                                boardFit += 1;

                                            if( _ai.UnitSim.MoveIsSetup( theirBattleUnit.LastUsedMove ) )
                                                boardFit += 1;
                                        }
                                        else if( theirPTKO_OurAlly <= PotentialToKO.Safe )
                                        {
                                            boardFit += 1;
                                            weLockThemDown = true;
                                        }
                                    }
                                }
                            }

                            if( theirAction == ActionType.OffensiveStatus || theirAction == ActionType.Setup )
                                boardFit += 1;

                            if( theirAction == ActionType.Attack && ( ( theyTargetUs && theirPTKO_Us <= PotentialToKO.TwoHKO ) || ( theyTargetOurAlly && theirPTKO_OurAlly <= PotentialToKO.TwoHKO ) ) )
                                boardFit += 1;

                            if( weLockThemDown && theirBench.Count <= 0 )
                                boardFit += 2;
                        }

                        if( mainCapability == CapabilityObservation.Disable )
                        {
                            var theirBattleUnit = _ai.GetBattleUnit( them.Pokemon );
                            if( theirBattleUnit != null && theirBattleUnit.Pokemon == them.Pokemon && us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                            {
                                if( theirAction == ActionType.Attack && theirBattleUnit.LastUsedMove.MoveSO.Name == theirMTR?.Move.MoveSO.Name )
                                {
                                    boardFit += 1;
                                    wePreventTheirAction = true;

                                    if( theyTargetUs && theirPTKO_Us >= PotentialToKO.Dangerous )
                                    {
                                        boardFit += 1;
                                        weReducePTKO = true;
                                    }

                                    if( theyTargetOurAlly && theirPTKO_OurAlly >= PotentialToKO.Dangerous )
                                    {
                                        boardFit += 1;
                                        weReducePTKO = true;
                                    }
                                }
                            }

                            if( theirBattleUnit != null && theirBattleUnit.LastUsedMove != null && _ai.UnitSim.MoveIsRedirection( theirBattleUnit.LastUsedMove ) )
                            {
                                boardFit += 1;
                                weCrippleTheirSupport = true;

                                if( ( ip.TheyWant.FollowMe || ip.TheyWant.RagePowder ) && us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                {
                                    boardFit += 1;
                                    wePreventTheirAction = true;
                                }
                            }

