                                if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                {
                                    boardFit += 2;
                                    wePreventTheirAction = true;
                                }
                            }

                            if( theirBattleUnit != null && theirBattleUnit.LastUsedMove == null && ( ( them.Speed > us.Speed && us.Ability != AbilityID.Prankster ) || ( us.Ability == AbilityID.Prankster && theyBlockPrankster ) ) )
                            {
                                //--take advantage of being slower to disable their incoming move
                                if( theirMTR != null && theirAttack != null )
                                {
                                    if( theyTargetUs && theirPTKO_Us <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( theyTargetOurAlly && theirPTKO_OurAlly <= PotentialToKO.Risky )
                                        boardFit +=1;

                                    if( theyTargetUs && theyTargetOurAlly && theirPTKO_Us <= PotentialToKO.Risky )
                                        boardFit += 1;

                                    if( ( ip.TheyWant.FollowMe || ip.TheyWant.RagePowder ) && them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                                        boardFit += 1;

                                    if( ( theirAction == ActionType.OffensiveStatus || theirAction == ActionType.SupportiveStatus ) && them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                                        boardFit += 1;
                                }
                            }
                        }

                        if( mainCapability == CapabilityObservation.Torment )
                        {
                            //--Torment in general is pretty damaging to the opponent
                            //--Not being able to use the same move twice in a row can be tedious as hell
                            boardFit += 2;

                            var theirBattleUnit = _ai.GetBattleUnit( them.Pokemon );
                            if( theirBattleUnit != null && theirBattleUnit.LastUsedMove != null && _ai.UnitSim.MoveIsRedirection( theirBattleUnit.LastUsedMove ) )
                            {
                                boardFit += 1;
                                weCrippleTheirSupport = true;
                            }

                            if( theirBattleUnit != null && theirBattleUnit.LastUsedMove != null && them.Pokemon.VolatileStatuses.ContainsKey( VolatileConditionID.ChoiceLocked ) )
                            {
                                boardFit += 2;
                                weLockThemDown = true;
                            }

                            if( theirAction == ActionType.Attack && theirAttack != null )
                            {
                                if( theyTargetUs && theirPTKO_Us <= PotentialToKO.Risky )
                                    boardFit += 1;

                                if( theyTargetOurAlly && theirPTKO_OurAlly <= PotentialToKO.Risky )
                                    boardFit += 1;

                                if( theyTargetUs && theyTargetOurAlly && theirPTKO_Us <= PotentialToKO.Risky )
                                    boardFit += 1;
                            }

                            if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility && them.RoleProfile.Signals.StatusMoveCount >= 2 )
                            {
                                boardFit += 1;
                                weCrippleTheirSupport = true;
                            }
                        }

                        if( mainCapability == CapabilityObservation.Imprison )
                        {
                            foreach( var ourMove in us.ActiveMoves )
                            {
                                foreach( var themMove in them.ActiveMoves )
                                {
                                    if( ourMove.MoveSO.Name == themMove.MoveSO.Name )
                                    {
                                        boardFit += 1;

                                        if( ( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) ) && themMove.MoveSO.Name == theirAttack?.MoveSO.Name )
                                            wePreventTheirAction = true;

                                        var move = themMove.MoveSO.Name;

                                        if( move == "Trick Room" )
                                        {
                                            if( ip.TheyWant.SetTrickRoom && !field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                                                boardFit += 5;
                                            else if( ip.TheyCan.SetTrickRoom && !field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                                                boardFit += 3;
                                        }

                                        if( move == "Tailwind" )
                                        {
                                            if( ip.TheyWant.SetTailwind && !theirCourt.ContainsKey( CourtConditionID.Tailwind ) )
                                                boardFit += 3;
                                            else if( ip.TheyCan.SetTailwind && !theirCourt.ContainsKey( CourtConditionID.Tailwind ) )
                                                boardFit += 2;
                                        }

                                        if( move == "Reflect" )
                                        {
                                            if( ip.TheyWant.SetReflect )
                                                boardFit += 2;
                                            else if( ip.TheyCan.SetReflect )
                                                boardFit += 1;
                                        }

                                        if( move == "Light Screen" )
                                        {
                                            if( ip.TheyWant.SetLightScreen )
                                                boardFit += 2;
                                            else if( ip.TheyCan.SetLightScreen )
                                                boardFit += 1;
                                        }

                                        if( move == "Aurora Veil" )
                                        {
                                            if( ip.TheyWant.SetAuroraVeil )
                                                boardFit += 2;
                                            else if( ip.TheyCan.SetAuroraVeil )
                                                boardFit += 1;
                                        }

                                        if( move == "Helping Hand" || move == "Follow Me" || move == "Rage Powder" )
                                        {
                                            boardFit += 2;
                                        }

                                        if( move == "Fake Out" && ( _ai.CanUseFakeOut( them, us ) || ( ourAlly != null && _ai.CanUseFakeOut( them, ourAlly ) ) ) )
                                        {
                                            boardFit += 3;
                                        }

                                        if( move == "Protect" )
                                        {
                                            boardFit += 3;
                                        }
                                    }
                                }

                                if( theirAlly != null )
                                {
                                    foreach( var themMove in theirAlly.ActiveMoves )
                                    {
                                        if( ourMove.MoveSO.Name == themMove.MoveSO.Name )
                                        {
                                            boardFit += 2;

                                            if( ( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) ) && themMove.MoveSO.Name == theirAllyMove?.MoveSO.Name )
                                                wePreventTheirAction = true;

                                            var move = themMove.MoveSO.Name;

                                            if( move == "Trick Room" )
                                            {
                                                if( ip.TheyWant.SetTrickRoom && !field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                                                    boardFit += 5;
                                                else if( ip.TheyCan.SetTrickRoom && !field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                                                    boardFit += 3;
                                            }

                                            if( move == "Tailwind" )
                                            {
                                                if( ip.TheyWant.SetTailwind && !theirCourt.ContainsKey( CourtConditionID.Tailwind ) )
                                                    boardFit += 3;
                                                else if( ip.TheyCan.SetTailwind && !theirCourt.ContainsKey( CourtConditionID.Tailwind ) )
                                                    boardFit += 2;
                                            }

                                            if( move == "Reflect" )
                                            {
                                                if( ip.TheyWant.SetReflect )
                                                    boardFit += 2;
                                                else if( ip.TheyCan.SetReflect )
                                                    boardFit += 1;
                                            }

                                            if( move == "Light Screen" )
                                            {
                                                if( ip.TheyWant.SetLightScreen )
                                                    boardFit += 2;
                                                else if( ip.TheyCan.SetLightScreen )
                                                    boardFit += 1;
                                            }

                                            if( move == "Aurora Veil" )
                                            {
                                                if( ip.TheyWant.SetAuroraVeil )
                                                    boardFit += 2;
                                                else if( ip.TheyCan.SetAuroraVeil )
                                                    boardFit += 1;
                                            }

                                            if( move == "Helping Hand" || move == "Follow Me" || move == "Rage Powder" )
                                            {
                                                boardFit += 2;
                                            }

                                            if( move == "Fake Out" && ( _ai.CanUseFakeOut( them, us ) || ( ourAlly != null && _ai.CanUseFakeOut( them, ourAlly ) ) ) )
                                            {
                                                boardFit += 3;
                                            }

                                            if( move == "Protect" )
                                            {
                                                boardFit += 3;
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        if( mainCapability == CapabilityObservation.HealBlock )
                        {
                            if( them.RoleProfile.Traits.Contains( RoleTrait.RecoveryMove ) )
                            {
                                boardFit += 1;
                            }

                            if( theirAttack?.MoveSO.HealType != HealType.None )
                            {
                                boardFit += 1;

                                if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                    boardFit += 2;

                                if( theirAction == ActionType.SupportiveStatus )
                                {
                                    var str = (StatusThreatResult)theirActionResult;
                                    if( str.SupportiveStatusType == SupportiveStatusType.Recovery )
                                    {
                                        boardFit += 1;

                                        if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                            boardFit += 2;
                                    }

                                    if( str.SupportiveStatusType == SupportiveStatusType.AllyProtection )
                                    {
                                        boardFit += 1;

                                        if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                            boardFit += 2;
                                    }
                                }

                                if( theirAction == ActionType.Attack )
                                {
                                    boardFit += 1;
                                    
                                    if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                                        boardFit += 2;
                                }

                                if( them.BeginningHPR <= 0.33f && ( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) ) )
                                    boardFit += 3;
                                else if( them.BeginningHPR <= 0.33f )
                                    boardFit += 2;
                                else if( them.BeginningHPR <= 0.66f )
                                    boardFit += 1;
                            }
                        }

                        if( mainCapability == CapabilityObservation.PerishSong )
                        {
                            if( ourBench.Count > 0 || ( ourAlly != null && ourAlly.Ability == AbilityID.Soundproof ) )
                            {
                                if( theirBench.Count < ourBench.Count )
                                    boardFit += 1;

                                if( theirBench.Count <= 0 )
                                    boardFit += 1;

                                if( ourBench.Count > 0 && ( us.RoleProfile.Traits.Contains( RoleTrait.TrappingAbility ) || ( ourAlly != null && ourAlly.RoleProfile.Traits.Contains( RoleTrait.TrappingAbility ) ) ) )
                                {
                                    boardFit += 3;
                                }

                                if( them.Pokemon.BindingStatuses?.Count > 0 || theirAlly?.Pokemon.BindingStatuses?.Count > 0 )
                                {
                                    boardFit += 1;

                                    if( them.Pokemon.BindingStatuses?.Count > 0 && theirAlly?.Pokemon.BindingStatuses?.Count > 0 )
                                        boardFit += 2;
                                }

