                            if( them.Ability == AbilityID.Soundproof || ( theirAlly != null && theirAlly.Ability == AbilityID.Soundproof ) )
                            {
                                boardFit -= 3;
                            }
                        }
                    }

                    //--Entry Hazard
                    if( entryHazard )
                    {
                        //--Hazards aren't particularly good in vgc style doubles due to the small teams
                        //--I'll give some flat rewards + some minor checks

                        if( _ai.Round <= 2 )
                            boardFit += 2;

                        if( theirBench.Count >= 2 )
                            boardFit += 1;

                        switch( candidate.MoveCandidate.MoveSO.MoveEffects.CourtCondition )
                        {
                            case CourtConditionID.LeechSeed:

                                int fireTypes = 0;
                                foreach( var kvp in _ai.Blackboard.TheirTeamAdapters )
                                {
                                    var mon = kvp.Key;
                                    if( mon.CurrentHP > 0 && mon.CheckTypes( PokemonType.Fire ) )
                                        fireTypes++;
                                }

                                if( fireTypes == 0 )
                                    boardFit += 1;

                                //--Passive healing is useful even in short battles
                                boardFit += 1;

                            break;

                            case CourtConditionID.StealthRock:

                                foreach( var mon in theirBench )
                                {
                                    if( TypeChart.GetTotalEffectiveness( PokemonType.Rock, mon.Type.One, mon.Type.Two ) > 1f )
                                        boardFit += 1;
                                }

                            break;

                            case CourtConditionID.ToxicSpikes:

                                int poisonTypes = 0;
                                foreach( var kvp in _ai.Blackboard.TheirTeamAdapters )
                                {
                                    var mon = kvp.Key;
                                    if( mon.CurrentHP > 0 && mon.CheckTypes( PokemonType.Poison ) )
                                        poisonTypes++;
                                }

                                if( poisonTypes == 0 )
                                    boardFit += 1;

                            break;

                            case CourtConditionID.StickyWeb:

                                foreach( var mon in theirBench )
                                {
                                    if( mon.RoleProfile.Biases.Contains( RoleBias.MiddlingSpeed ) || mon.RoleProfile.Biases.Contains( RoleBias.FastSpeed ) )
                                        boardFit += 1;
                                }

                            break;
                        }
                    }

                    //--Stat Debuff
                    if( statDebuff )
                    {
                        if( candidate.MoveCandidate != null )
                        {
                            var statStages = candidate.MoveCandidate.MoveSO.MoveEffects.StatChangeList;

                            if( statStages?.Count > 0 )
                            {
                                bool weAreFaster = us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster );
                                foreach( var sc in statStages )
                                {
                                    Dictionary<Stat, int> changes = new(){ { sc.Stat, sc.Change } };

                                    if( sc.Change < 0 )
                                    {
                                        //-------------------
                                        //--Offensive Stats--
                                        //-------------------
                                        if( sc.Stat == Stat.Attack || sc.Stat == Stat.SpAttack )
                                        {
                                            bool attackAlignsWithReduction = ( sc.Stat == Stat.Attack && theirAttack?.MoveSO.MoveCategory == MoveCategory.Physical ) || ( sc.Stat == Stat.SpAttack && theirAttack?.MoveSO.MoveCategory == MoveCategory.Special );

                                            if( sc.Stat == Stat.Attack )
                                            {
                                                if( them.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                                {
                                                    boardFit += 1;

                                                    if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                                        boardFit += 1;
                                                }

                                                if( theirAttack?.MoveSO.MoveCategory == MoveCategory.Physical )
                                                {
                                                    boardFit += 1;

                                                    if( weAreFaster )
                                                        boardFit += 1;
                                                }
                                            }

                                            if( sc.Stat == Stat.SpAttack )
                                            {
                                                if( them.RoleProfile.Biases.Contains( RoleBias.Special ) )
                                                {
                                                    boardFit += 1;

                                                    if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                                        boardFit += 1;
                                                }

                                                if( theirAttack?.MoveSO.MoveCategory == MoveCategory.Special )
                                                {
                                                    boardFit += 1;

                                                    if( weAreFaster )
                                                        boardFit += 1;
                                                }
                                            }

                                            var theirEDR = theirMTR.EDR;

                                            if( theyTargetUs && attackAlignsWithReduction )
                                            {
                                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackerStatStageChanges: changes );
                                                boardFit += 1;

                                                if( adjustedPTKO < theirPTKO_Us )
                                                {
                                                    boardFit += 1;
                                                    weReducePTKO = true;
                                                }

                                                if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                                    boardFit += 1;

                                                if( weAreFaster )
                                                    boardFit += 1;
                                            }

                                            if( theyTargetOurAlly && ourAlly != null && attackAlignsWithReduction )
                                            {
                                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, attackerStatStageChanges: changes );
                                                boardFit += 1;

                                                if( adjustedPTKO < theirPTKO_Us )
                                                {
                                                    boardFit += 1;
                                                    weReducePTKO = true;
                                                }
                                                    
                                                if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                                    boardFit += 1;

                                                if( weAreFaster )
                                                    boardFit += 1;
                                            }
                                        }

                                        //-------------------
                                        //--Defensive Stats--
                                        //-------------------
                                        if( sc.Stat == Stat.Defense )
                                        {
                                            if( them.RoleProfile.Biases.Contains( RoleBias.PhysicallyBulky ) )
                                            {
                                                boardFit += 1;

                                                if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Defensive || them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                                                    boardFit += 1;
                                            }

                                            if( us.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                                boardFit += 1;

                                            if( ourAlly != null && ourAlly.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                                boardFit += 1;

                                            if( ip.UsVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Physical )
                                                boardFit += 1;

                                            if( ourAlly != null && ourAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Physical )
                                                boardFit += 1;

                                            if( weAreFaster )
                                                boardFit += 1;
                                        }

                                        if( sc.Stat == Stat.SpDefense )
                                        {
                                            if( them.RoleProfile.Biases.Contains( RoleBias.SpeciallyBulky ) )
                                            {
                                                boardFit += 1;

                                                if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Defensive || them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                                                    boardFit += 1;
                                            }

                                            if( us.RoleProfile.Biases.Contains( RoleBias.Special ) )
                                                boardFit += 1;

                                            if( ourAlly != null && ourAlly.RoleProfile.Biases.Contains( RoleBias.Special ) )
                                                boardFit += 1;

                                            if( ip.UsVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Special )
                                                boardFit += 1;

                                            if( ourAlly != null && ourAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Special )
                                                boardFit += 1;

                                            if( weAreFaster )
                                                boardFit += 1;
                                        }

                                        //-------------------
                                        //--Speed Stat-------
                                        //-------------------
                                        if( sc.Stat == Stat.Speed )
                                        {
                                            if( them.Speed > us.Speed && us.Speed > them.Speed / _stageModifier[sc.Change] )
                                            {
                                                boardFit += sc.Change;

                                                if( theirPTKO_Us <= PotentialToKO.Risky && ourPTKO >= PotentialToKO.Risky )
                                                    boardFit += 1;
                                            }

                                            if( them.Speed > ourAlly?.Speed && ourAlly?.Speed > them.Speed / _stageModifier[sc.Change] )
                                            {
                                                boardFit += sc.Change;

                                                if( ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                                {
                                                    boardFit += 1;

                                                    if( weAreFaster )
                                                        boardFit += 1;
                                                }
                                            }
                                        }

                                        if( sc.Stat == Stat.Accuracy || sc.Stat == Stat.Evasion )
                                        {
                                            boardFit += sc.Change;

                                            if( sc.Stat == Stat.Accuracy && ( theirPTKO_Us >= PotentialToKO.Risky || theirPTKO_OurAlly >= PotentialToKO.Risky) )
                                                boardFit += 1;

                                            if( sc.Stat == Stat.Evasion && ourAlly != null && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                                boardFit += 1;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    //--Phaze
                    if( phaze )
                    {
                        if( us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster ) )
                        {
                            wePreventTheirAction = theirAction != ActionType.DefensiveSwitch && theirAction != ActionType.OffensiveSwitch;

                            if( theirAction == ActionType.Attack )
                                weReducePTKO = true;

                            if( ip.TheyWant.SetTailwind )
                                boardFit += 3;

                            if( ip.TheyWant.SetReflect || ip.TheyWant.SetLightScreen || ip.TheyWant.SetAuroraVeil )
                                boardFit += 2;

                            if( ip.TheyWant.SetMoveWeather || ip.TheyWant.SetMoveTerrain )
                                boardFit += 2;

                            if( theirAction == ActionType.OffensiveStatus || theirAction == ActionType.Setup )
                                boardFit += 2;
                        }

                        //--Trick Room always goes last
                        if( ip.TheyWant.SetTrickRoom )
                            boardFit += 3;
                        
                        //--It's always good to remove a trapper
                        if( them.RoleProfile.Traits.Contains( RoleTrait.TrappingAbility ) || ( them.RoleProfile.Traits.Contains( RoleTrait.TrappingMove ) && us.Bindings?.Count > 0 ) )
                            boardFit += 2;

                        int boosts = 0;
                        foreach( var sc in them.StatStages )
                        {
                            if( sc.Value > 0 )
                                boosts++;
                        }

                        if( boosts >= 3 )
                            boardFit += 3;
                        else
                            boardFit += boosts;
                    }

                    if( wePreventTheirAction )
                    {
                        boardFit += 1;

                        if( ip.TheyWant.SetTailwind )
                            boardFit += 1;

                        if( ip.TheyWant.SetTrickRoom )
                            boardFit += 1;

                        if( ip.TheyWant.SetReflect || ip.TheyWant.SetLightScreen || ip.TheyWant.SetAuroraVeil )
                            boardFit += 1;
                    }

                    if( weReducePTKO )
                        boardFit += 1;

                    if( weCrippleTheirSupport )
                    {
                        boardFit += 1;
                    }

                    //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    //--Unit Fit----------------------------------------------------------------------------------------------------------------------------------------------------------
                    //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    if( us.Speed > them.Speed || us.Ability == AbilityID.Prankster )
                        unitFit += 1;

                    if( us.Speed > theirAlly?.Speed || ( theirAlly != null && us.Ability == AbilityID.Prankster ) )
                        unitFit += 1;

                    if( us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                        unitFit += 1;

                    if( statusEffect && us.RoleProfile.Biases.Contains( RoleBias.SupportFocused ) )
                        unitFit += 1;

                    if( ( disruption || phaze ) && ( us.RoleProfile.Biases.Contains( RoleBias.Disruptive ) || us.RoleProfile.PrimaryRole == RoleClass.Disrupter ) )
                        unitFit += 1;

                    bool reapplyable = mainCapability == CapabilityObservation.Paralysis || mainCapability == CapabilityObservation.Sleep || disruption || statDebuff || phaze;
                    if( ( us.RoleProfile.Biases.Contains( RoleBias.FastSpeed ) || us.Ability == AbilityID.Prankster ) && reapplyable )
                        unitFit += 1;

                    if( us.Item == ItemBattleEffectID.FocusSash || ( us.Item != ItemBattleEffectID.None && us.RoleProfile.Traits.Contains( RoleTrait.RecoveryItem ) ) )
                        unitFit += 1;

                    if( ourAlly != null && ( ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) || _ai.CanUseFakeOut( ourAlly, them ) ) )
                        unitFit += 1;

                    //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    //--Plan Fit----------------------------------------------------------------------------------------------------------------------------------------------------------
                    //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    bool theyAreWincon = them.Pokemon == gp.TheirPrimaryWinCon;
                    bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon );
                    bool theyAreEnabler = gp.TheirEnablers.Contains( them.Pokemon );

                    bool weAreWincon = us.Pokemon == gp.OurPrimaryWinCon;
                    bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                    bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                    bool ourAllyIsWincon = ourAlly?.Pokemon == gp.OurPrimaryWinCon;

                    if( theyAreWincon && ( weReducePTKO || wePreventTheirAction ) )
                        planFit += 1;

                    if( theyAreBlocker || theyAreEnabler )
                    {
                        if( wePreventTheirAction )
                            planFit += 1;
                        
                        if( weCrippleTheirSupport )
                            planFit += 1;
                    }

                    if( weAreBlocker )
                    {
                        planFit += 1;

                        if( weReducePTKO )
                            planFit += 1;

                        if( wePreventTheirAction )
                            planFit += 1;

                        if( weCrippleTheirSupport )
                            planFit += 1;
                    }

                    if( weAreEnabler && ourAllyIsWincon )
                    {
                        planFit += 1;

                        if( weCrippleTheirSupport )
                            planFit += 1;
                    }

                    //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    //--Cost/Risk---------------------------------------------------------------------------------------------------------------------------------------------------------
                    //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                    if( theirPTKO_Us >= PotentialToKO.Dangerous )
                    {
                        costRisk += 1;
                        
                        if( !weReducePTKO && theyTargetUs )
                            costRisk += 2;
                    }

                    if( theirAllyPTKO_Us >= PotentialToKO.Dangerous )
                    {
                        costRisk += 1;

                        if( !weReducePTKO && theirAllyTargetsUs )
                            costRisk += 2;
                    }

                    if( !weReducePTKO && theyTargetUs && theirAllyTargetsUs )
                        costRisk += 2;

                    if( ip.TheyCan.Taunt )
                        costRisk += 1;

                    if( ip.TheyCan.Encore && theyOutSpeedStatus )
                        costRisk += 1;

                    if( ip.TheyWant.Taunt && theyOutSpeedStatus )
                        costRisk += 2;

                    if( ip.TheyWant.Disable && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                        costRisk += 1;

                    if( ip.TheyWant.FakeOut && !weBlockPriority )
                        costRisk += 2;

                    if( ip.TheyWant.TWave && !us.RoleProfile.Traits.Contains( RoleTrait.ThunderWaveImmune ) )
                        costRisk += 1;

                    if( ( ip.TheyWant.SleepPowder || ip.TheyWant.Spore ) && ( !us.RoleProfile.Traits.Contains( RoleTrait.PowderImmune ) || !us.RoleProfile.Traits.Contains( RoleTrait.SleepImmune ) ) )
                        costRisk += 1;

                    if( ip.TheyWant.CraftyShield || ( us.Ability == AbilityID.Prankster && ip.TheyWant.QuickGuard ) )
                        costRisk += 2;

                    if( ip.TheyWant.RagePowder || ip.TheyWant.FollowMe )
                        costRisk += 1;

                    if( mainCapability == CapabilityObservation.Taunt && theirAction != ActionType.OffensiveStatus && theirAction != ActionType.SupportiveStatus )
                    {
                        costRisk += 2;

                        if( theirAction == ActionType.Attack && theirAttack != null && theirPTKO_Us >= PotentialToKO.Dangerous )
                            costRisk += 2;
                    }
                }

                int finalScore = pressureFit + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    PressureFitScore = pressureFit,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                responses.Add( candidate, scores );
            }
        }

        return responses;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetSupportiveStatusResponses( Dictionary<StrategyPressure, StrategyPressureEvidence> pressureSets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> responses = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = _ai.GetRemainingPartyAs_IBattleAIUnits( ourActive[0].Pokemon ).Where( u => !ourActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = _ai.GetRemainingPartyAs_IBattleAIUnits( theirActive[0].Pokemon ).Where( u => !theirActive.Any( a => a.Pokemon != u.Pokemon ) && u.Pokemon.CurrentHP > 0 ).ToList();

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();
            var capabilitySets = ExtractUniqueCapabilities( ActionType.SupportiveStatus, unit.Pokemon, pressureSets );

            if( capabilitySets?.Count <= 0 )
                continue;

            //--extract unique capabilities who have hashsets of pressures they are a response to.
            //--then, in  pressure fit, we can do score += coveredPressures.Count, naturally letting a response capability
            //--cover multiple options at once and rewarding it for doing so.
            foreach( var kvp in capabilitySets )
            {
                var capability = kvp.Key;
                var pressures = kvp.Value;

                foreach( var opp in theirActive )
                {
                    var candidate = GetSupportiveStatusCandidate( capability, unit, opp, CoordinationActionType.Response );
                    candidate.RelevantPressures = pressures;
                    candidates.Add( candidate );
                }
            }

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int pressureFit = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                bool recovery = false;
                bool forceMultiplier = false;
                bool battlefieldControl = false;
                bool allyProtection = false;

                bool reflectable = candidate.MoveCandidate != null && candidate.MoveCandidate.MoveSO.Flags != null && candidate.MoveCandidate.MoveSO.Flags.Count > 0 && candidate.MoveCandidate.MoveSO.Flags.Contains( MoveFlags.Reflectable );
                bool theyReflect = candidate.Target?.AbilityID == AbilityID.MagicBounce;
                // bool theyBlock = candidate.Target?.AbilityID == AbilityID.MagicGuard || candidate.Target?.AbilityID == AbilityID.GoodAsGold;

                // if( theyBlock )
                //     continue;

                if( reflectable && theyReflect )
                    continue;

                if( candidate.Actor.VolatileStatuses.ContainsKey( VolatileConditionID.Taunt ) )
                    continue;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                switch( mainCapability )
                {
                    //--Recovery
                    case CapabilityObservation.SelfHeal:
                        recovery = true;
                    break;

                    //--Force Multiplier
                    case CapabilityObservation.Tailwind:

                        if( ourCourt.ContainsKey( CourtConditionID.Tailwind ) )
                            continue;
                        else
                            forceMultiplier = true;
                        break;

                    case CapabilityObservation.Reflect:

                        if( ourCourt.ContainsKey( CourtConditionID.Reflect ) )
                            continue;
                        else
                            forceMultiplier = true;
                        break;

                    case CapabilityObservation.LightScreen:

                        if( ourCourt.ContainsKey( CourtConditionID.LightScreen ) )
                            continue;
                        else
                            forceMultiplier = true;
                        break;

                    case CapabilityObservation.AuroraVeil:

                        if( ourCourt.ContainsKey( CourtConditionID.AuroraVeil ) )
                            continue;
                        else
                            forceMultiplier = true;
                        break;

                    case CapabilityObservation.SideStatBuff:
                    case CapabilityObservation.HelpingHand:
                    case CapabilityObservation.AfterYou:
                        forceMultiplier = true;
                    break;

                    //--Battlefield Control
                    case CapabilityObservation.WeatherSetMove:
                        
                        if( _ai.UnitSim.GetWeatherFrom_Move( candidate.MoveCandidate ) is var candWeather && candWeather == currentWeather )
                            continue;
                        else
                            battlefieldControl = true;
                        break;

                    case CapabilityObservation.TerrainSetMove:
                        
                        if( _ai.UnitSim.GetTerrainFrom_Move( candidate.MoveCandidate ) is var candTerrain && candTerrain == currentTerrain )
                            continue;
                        else
                            battlefieldControl = true;
                        break;

                    case CapabilityObservation.TrickRoom:
                    case CapabilityObservation.TidyUp:
                    case CapabilityObservation.Defog:
                        battlefieldControl = true;
                    break;

                    //--Ally Protection
                    case CapabilityObservation.Redirection:
                    case CapabilityObservation.SideHeal:
                    case CapabilityObservation.StatReset:
                    case CapabilityObservation.AllySwitch:
                        allyProtection = true;
                    break;
                }

                var ourSP = _ai.Projection.GetStrategicProfile( us );
                var theirSP  = _ai.Projection.GetStrategicProfile( them );

                var gp = _ai.Blackboard.GamePlan;
                
                //----------------
                //--Pressure Fit--
                //----------------
                //--Capability's Pressure Coverage
                int pressureFitScore = candidate.RelevantPressures.Count;

                foreach( var e in candidate.RelevantPressures )
                {
                    var ip = GetInteractionProfile( us, them, candidate, e );
                    var ourPTKO_Them = ip.AttackerPTKO;

                    const float SCREENS_MODIFIER = 0.66796875f;
                    const float AURORA_VEIL_MODIFIER = 0.6669921875f;

                    var theirPTKO_Us = ip.TargetPTKO;
                    var theirAction = ip.TheirAction;
                    var theirActionResult = ip.TheirActionResult;
                    var theirMTR = theirActionResult is MoveThreatResult result ? result : null ;
                    var theirEDR = theirMTR != null ? theirMTR.EDR : default;
                    
                    var theirAllyAction = ip.TheirAllyAction;
                    var theirAllyActionResult = ip.TheirAllyActionResult;
                    bool theirAllyHasIntent = ip.TheirAllyHasIntent;

                    var ourAlly = ip.AttackerAlly;
                    var theirAlly = ip.TargetAlly;

                    bool weHaveAlly = ourAlly != null;
                    bool theyHaveAlly = theirAlly != null;

                    var ourAllySP = weHaveAlly ? _ai.Projection.GetStrategicProfile( ourAlly ) : default;
                    var theirAllySP = theyHaveAlly ? _ai.Projection.GetStrategicProfile( theirAlly ) : default;

                    bool theyAttack = theirAction == ActionType.Attack;
                    bool theySwitch = theirAction == ActionType.OffensiveSwitch || theirAction == ActionType.DefensiveSwitch;
                    bool theySetup = theirAction == ActionType.Setup;
                    bool theyStatus = theirAction == ActionType.OffensiveStatus || theirAction == ActionType.SupportiveStatus;
                    bool theyProtect = theirAction == ActionType.Protect;

                    bool theyUseAMove = theyAttack || theySetup || theyStatus || theyProtect;

                    var theirMove = theirActionResult.Move;

                    bool theyTargetUs = theirMove != null && theirActionResult.Targets.Any( u => u.Pokemon == us.Pokemon );
                    bool theyTargetOurAlly = theirMove != null && weHaveAlly && theirActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                    bool theirAllyAttacks = theirAllyHasIntent && theirAllyAction == ActionType.Attack;
                    bool theirAllySwitches = theirAllyHasIntent && ( theirAllyAction == ActionType.DefensiveSwitch || theirAllyAction == ActionType.OffensiveSwitch );
                    bool theirAllySetsup = theirAllyHasIntent && theirAllyAction == ActionType.Setup;
                    bool theirAllyStatuses = theirAllyHasIntent && ( theirAllyAction == ActionType.OffensiveStatus || theirAllyAction == ActionType.SupportiveStatus );
                    bool theirAllyProtects = theirAllyHasIntent && theirAllyAction == ActionType.Protect;

                    var theirAllyMove = theirAllyAttacks && theirAllyActionResult?.Move != null ? theirAllyActionResult.Move : null;
                    bool theirAllyUsesMove = theirAllyMove != null;
                    bool theirAllyTargetsUs = theyHaveAlly && theirAllyHasIntent && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == u.Pokemon );
                    bool theirAllyTargetsOurAlly = theyHaveAlly && theirAllyHasIntent && weHaveAlly && theirAllyActionResult.Targets?.Count > 0 && theirAllyActionResult.Targets.Any( u => u.Pokemon == ourAlly?.Pokemon );

                    var ourAllyPTKO_Them = weHaveAlly ? ip.OurAllyVsThem.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var ourAllyPTKO_TheirAlly = weHaveAlly && theyHaveAlly ? ip.OurAllyVsTheirAlly.Attacker.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var theirAllyPTKO_Us = theirAllyTargetsUs ? ip.UsVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                    var theirAllyPTKO_OurAlly = theirAllyTargetsOurAlly ? ip.OurAllyVsTheirAlly.Target.BestCurrentPTKO : PotentialToKO.Untouchable;

                    var theirPTKO_OurAlly = weHaveAlly ? ip.OurAllyVsThem.Target.BestCurrentPTKO : PotentialToKO.Untouchable;
                    
                    SwitchCandidateResult scr = theySwitch ? (SwitchCandidateResult)theirActionResult : default;
                    var theirSwitch = theySwitch ? scr.Candidate : null;

                    bool theyHaveSwitch = theirSwitch != null;

                    bool weReducePTKO = false;
                    bool weAlterTurnOrder = false;
                    bool weImproveOurOffense = false;
                    bool weImproveOurDefense = false;
                    bool weImproveOurField = false;
                    bool weReduceTheirField = false;

                    //-------------
                    //--Board Fit--
                    //-------------
                    if( recovery && mainCapability == CapabilityObservation.SelfHeal )
                    {
                        if( us.BeginningHPR <= 0.5f )
                            boardFit += 1;

                        if( theyTargetUs )
                        {
                            if( theirAction == ActionType.Attack )
                            {
                                if( MovesBefore( us, them, ip.TurnOrder ) )
                                {
                                    boardFit += 1;

                                    if( theirPTKO_Us >= PotentialToKO.Dangerous )
                                    {
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, newHPR: us.BeginningHPR + 0.5f );

                                        if( adjustedPTKO < theirPTKO_Us )
                                        {
                                            boardFit += 1;
                                            weReducePTKO = true;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;
                                    }
                                }
                                else
                                {
                                    if( theirPTKO_Us >= PotentialToKO.Dangerous )
                                        boardFit -= 5;
                                    else if( theirPTKO_Us <= PotentialToKO.Risky )
                                        boardFit += 1;
                                }
                            }
                            else if( theirAction == ActionType.OffensiveStatus )
                            {
                                if( MovesBefore( them, us, ip.TurnOrder ) )
                                {
                                    if( theirMove?.MoveSO.Name == "Taunt" )
                                        boardFit -= 5;

                                    if( theirMove?.MoveSO.Name == "Encore" )
                                        boardFit -= 3;

                                    if( theirMove?.MoveSO.Name == "Disable" && _ai.GetBattleUnit( us.Pokemon ).LastUsedMove is Move lastMove && lastMove != null && lastMove.MoveSO.Name != candidate.MoveCandidate.MoveSO.Name )
                                        boardFit += 1;
                                    else if( theirMove?.MoveSO.Name == "Disable" && _ai.GetBattleUnit( us.Pokemon ).LastUsedMove != null )
                                        boardFit -= 5;
                                }
                            }
                            else
                            {
                                if( us.BeginningHPR <= 0.33f )
                                    boardFit += 2;
                                else if( us.BeginningHPR <= 0.66f )
                                    boardFit += 1;
                            }
                        }

                        if( theyHaveAlly && theirAllyTargetsUs && theirAllyMove != null )
                        {
                            if( theirAllyAction == ActionType.Attack )
                            {
                                if( MovesBefore( us, theirAlly, ip.TurnOrder ) )
                                {
                                    boardFit += 1;

                                    if( theirPTKO_Us >= PotentialToKO.Dangerous )
                                    {
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, theirAlly, us, newHPR: us.BeginningHPR + 0.5f );

                                        if( adjustedPTKO < theirPTKO_Us )
                                        {
                                            boardFit += 1;
                                            weReducePTKO = true;
                                        }

                                        if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                            boardFit += 1;
                                    }
                                }
                                else
                                {
                                    if( theirPTKO_Us >= PotentialToKO.Dangerous )
                                        boardFit -= 5;
                                    else if( theirPTKO_Us <= PotentialToKO.Risky )
                                        boardFit += 1;
                                }
                            }
                            else if( theirAllyAction == ActionType.OffensiveStatus )
                            {
                                if( MovesBefore( theirAlly, us, ip.TurnOrder ) )
                                {
                                    if( theirAllyMove.MoveSO.Name == "Taunt" )
                                        boardFit -= 5;

                                    if( theirAllyMove.MoveSO.Name == "Encore" )
                                        boardFit -= 3;

                                    if( theirAllyMove.MoveSO.Name == "Disable" && _ai.GetBattleUnit( us.Pokemon ).LastUsedMove is Move lastMove && lastMove != null && lastMove.MoveSO.Name != candidate.MoveCandidate.MoveSO.Name )
                                        boardFit += 1;
                                    else if( theirAllyMove.MoveSO.Name == "Disable" && _ai.GetBattleUnit( us.Pokemon ).LastUsedMove != null )
                                        boardFit -= 5;
                                }
                            }
                            else
                            {
                                if( us.BeginningHPR <= 0.33f )
                                    boardFit += 2;
                                else if( us.BeginningHPR <= 0.66f )
                                    boardFit += 1;
                            }
                        }
                    }

                    if( forceMultiplier )
                    {
                        if( mainCapability == CapabilityObservation.Tailwind && !ourCourt.ContainsKey( CourtConditionID.Tailwind ) && !field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                        {
                            weImproveOurField = true;

                            bool theyOutspeedUs = them.Speed > us.Speed;
                            bool theyOutspeedOurAlly = them.Speed > ourAlly?.Speed;
                            bool theirAllyOutspeedsUs = theirAlly?.Speed > us.Speed;
                            bool theirAllyOutspeedsOurAlly = theirAlly?.Speed > ourAlly?.Speed;

                            const int tailwind = 2;
                            int ourTailwindSpeed = us.Speed * tailwind;
                            int ourAllyTailwindSpeed = weHaveAlly ? ourAlly.Speed * tailwind : 0;

                            bool weOutspeedThemAfter = ourTailwindSpeed > them.Speed;
                            bool weOutspeedTheirAllyAfter = ourTailwindSpeed > theirAlly?.Speed;
                            bool ourAllyOutspeedsThemAfter = ourAllyTailwindSpeed > them.Speed;
                            bool ourAllyOutspeedsTheirAllyAfter = ourAllyTailwindSpeed > theirAlly?.Speed;

                            if( !theirCourt.ContainsKey( CourtConditionID.Tailwind ) )
                            {
                                if( theyOutspeedUs && weOutspeedThemAfter )
                                {
                                    boardFit += 1;
                                    weAlterTurnOrder = true;
                                }

                                if( theyOutspeedOurAlly && ourAllyOutspeedsThemAfter )
                                {
                                    boardFit += 1;
                                    weAlterTurnOrder = true;
                                }

                                if( theirAllyOutspeedsUs && weOutspeedTheirAllyAfter )
                                {
                                    boardFit += 1;
                                    weAlterTurnOrder = true;
                                }

                                if( theirAllyOutspeedsOurAlly && ourAllyOutspeedsTheirAllyAfter )
                                {
                                    boardFit += 1;
                                    weAlterTurnOrder = true;
                                }

                                if( us.Ability == AbilityID.Prankster || !theyOutspeedUs || MovesBefore( us, them, ip.TurnOrder ) )
                                {
                                    if( theyOutspeedOurAlly && ourAllyOutspeedsThemAfter )
                                    {
                                        if( theyTargetUs && theirMove != null && theirPTKO_Us >= PotentialToKO.Dangerous )
                                        {
                                            if( ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                            {
                                                boardFit += 1;
                                                weImproveOurOffense = true;

                                                if( ourAllyPTKO_Them == PotentialToKO.OHKO )
                                                    boardFit += 1;
                                            }

                                            if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.ParalysisPressure ) || ourAlly.RoleProfile.Traits.Contains( RoleTrait.SleepPressure ) )
                                                boardFit += 2;

                                            if( ourAlly.RoleProfile.Traits.Contains( RoleTrait.BurnPressure ) && theirMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                                            {
                                                boardFit += 1;

                                                var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, changeBrnOrFbt: 0.5f );

                                                if( adjustedPTKO < theirPTKO_Us )
                                                {
                                                    boardFit += 1;
                                                    weImproveOurDefense = true;
                                                }

                                                if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO > 2 )
                                                    boardFit += 1;
