                            {
                                var switchesWeather = _ai.UnitSim.GetWeatherFrom_Ability( theirSwitch.Pokemon );
                                if( theyHaveAlly && _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( theirAlly.Pokemon, switchesWeather ) )
                                    boardFit += 2;
                            }

                            if( ip.TheyWant.SetMoveWeather && theirMove?.MoveSO.MoveEffects.Weather != WeatherConditionID.None )
                            {
                                var movesWeather = _ai.UnitSim.GetWeatherFrom_Move( theirMove );
                                if( _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( them.Pokemon, movesWeather ) )
                                    boardFit += 2;

                                if( theyHaveAlly && _ai.UnitSim.PokemonHas_MatchingWeatherSpeedAbility( theirAlly.Pokemon, movesWeather ) )
                                    boardFit += 2;
                            }

