                        if( mainCapability == CapabilityObservation.Reflect )
                        {
                            if( theirAction == ActionType.Attack && theirMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                            {
                                boardFit += 1;
                                weImproveOurField = true;
                                weImproveOurDefense = true;

                                bool weMoveFirst = MovesBefore( us, them, ip.TurnOrder );

                                var adjustedPTKO_Us = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, addModifier: SCREENS_MODIFIER );
    
                                if( theyTargetUs )
                                {
                                    bool weAreSafeish = theirPTKO_Us <= PotentialToKO.Risky;
                                    bool weCanSetup = weMoveFirst || weAreSafeish;

