                                        boardFit += 1;

                                    if( adjustedPTKO_Us < theirPTKO_Us )
                                    {
                                        boardFit += weCanSetup ? 2 : 1;
                                        weReducePTKO = true;
                                    }

                                    if( adjustedPTKO_Us <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO_Us > 2 )
                                        boardFit += weCanSetup ? 2 : 1;
                                }

                                if( weHaveAlly && theyTargetOurAlly )
                                {
                                    var adjustedPTKO_OurAlly = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, addModifier: SCREENS_MODIFIER );

                                    if( weMoveFirst )
                                        boardFit += 2;

                                    if( adjustedPTKO_OurAlly < theirPTKO_OurAlly )
                                    {
                                        boardFit += weMoveFirst ? 3 : 1;
                                        weReducePTKO = true;
                                    }

                                    if( adjustedPTKO_OurAlly <= PotentialToKO.TwoHKO || theirPTKO_OurAlly - adjustedPTKO_OurAlly > 2 )
                                        boardFit += weMoveFirst ? 3 : 1;
                                }
