                        if( mainCapability == CapabilityObservation.AuroraVeil )
                        {
                            if( theirAction == ActionType.Attack && ( theirMove?.MoveSO.MoveCategory == MoveCategory.Physical || theirMove?.MoveSO.MoveCategory == MoveCategory.Special ) )
                            {
                                boardFit += 1;
                                weImproveOurField = true;
                                weImproveOurDefense = true;

                                bool weMoveFirst = MovesBefore( us, them, ip.TurnOrder );

                                var adjustedPTKO_Us = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, addModifier: AURORA_VEIL_MODIFIER );
    
                                if( theyTargetUs )
                                {
                                    bool ourAllyRedirects = weHaveAlly && ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove );
                                    bool weAreSafeish = theirPTKO_Us <= PotentialToKO.Risky;

                                    bool weCanSetup = weMoveFirst || weAreSafeish;

                                    if( weCanSetup )
                                        boardFit += 1;

                                    if( adjustedPTKO_Us < theirPTKO_Us )
                                    {
                                        boardFit += weCanSetup ? 2 : 1;
                                        weReducePTKO = true;
                                    }

                                    if( adjustedPTKO_Us <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO_Us > 2 )
