                        if( mainCapability == CapabilityObservation.SideStatBuff && weHaveAlly )
                        {
                            int atkBoosts = 0;
                            int defBoosts = 0;
                            int spatkBoosts = 0;
                            int spdefBoosts = 0;
                            int speBoosts = 0;
                            var statStages = candidate.MoveCandidate.MoveSO.MoveEffects.StatChangeList;

                            if( statStages != null && statStages.Count > 0 )
                            {
                                foreach( var sc in statStages )
                                {
                                    if( sc.Change > 0 )
                                    {
                                        switch( sc.Stat )
                                        {
                                            case Stat.Attack: atkBoosts += sc.Change; break;
                                            case Stat.Defense: defBoosts += sc.Change; break;
                                            case Stat.SpAttack: spatkBoosts += sc.Change; break;
                                            case Stat.SpDefense: spdefBoosts += sc.Change; break;
                                            case Stat.Speed: speBoosts += sc.Change; break;
                                        }
                                    }
                                }

                                int totalBoosts = atkBoosts + defBoosts + spatkBoosts + spdefBoosts + speBoosts;

                                if( candidate.MoveCandidate.MoveSO.Name == "Howl" )
                                {
                                    if( us.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                        boardFit += 2;

                                    if( _ai.CanUseProtect( ourAlly.Pokemon ) )
                                        boardFit += 1;
                                }

                                if( totalBoosts > 3 )
                                    boardFit += 3;
                                else if( totalBoosts > 1 )
                                    boardFit += 2;
                                else if( totalBoosts > 0 )
                                    boardFit += 1;

                                if( totalBoosts > 0 && MovesBefore( us, ourAlly, ip.TurnOrder ) )
                                    boardFit += 1;

                                Dictionary<Stat, int> statBoosts = new()
                                {
                                    { Stat.Attack, atkBoosts },
                                    { Stat.Defense, defBoosts },
                                    { Stat.SpAttack, spatkBoosts },
                                    { Stat.SpDefense, spdefBoosts },
                                    { Stat.Speed, speBoosts },
                                };

                                if( ( atkBoosts > 0 && ourAlly.RoleProfile.Biases.Contains( RoleBias.Physical ) ) || ( spatkBoosts > 0 && ourAlly.RoleProfile.Biases.Contains( RoleBias.Special ) ) )
                                {
                                    boardFit += 1;

                                    if( ourAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                        boardFit += 1;

                                    bool physical_Them = ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Physical && atkBoosts > 0;
                                    bool special_Them = ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Special && spatkBoosts > 0;
                                    if( physical_Them || special_Them )
                                    {
