                                    bool physical_TheirAlly = ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Physical && atkBoosts > 0;
                                    bool special_TheirAlly = ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Special && spatkBoosts > 0;
                                    if( theyHaveAlly && ( physical_TheirAlly || special_TheirAlly ) )
                                    {
                                        var edr = ip.OurAllyVsTheirAlly.Attacker.BestEDR;
                                        var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( edr, ourAlly, them, attackerStatStageChanges: statBoosts );

                                        if( adjustedPTKO > ourAllyPTKO_TheirAlly )
                                        {
                                            boardFit += 1;
                                            weImproveOurOffense = true;

                                            if( adjustedPTKO - ourAllyPTKO_TheirAlly > 2 )
                                                boardFit += 1;

                                            if( ( adjustedPTKO >= PotentialToKO.Dangerous && ourAllyPTKO_TheirAlly <= PotentialToKO.Risky ) || ( adjustedPTKO == PotentialToKO.OHKO && ourAllyPTKO_TheirAlly == PotentialToKO.Dangerous ) )
                                            {
                                                boardFit += 1;

                                                if( adjustedPTKO == PotentialToKO.OHKO )
                                                    boardFit += 1;
                                            }
                                        }
                                    }

                                    if( theyHaveAlly && ourAlly.RoleProfile.Traits.Contains( RoleTrait.SpreadAttack ) )
                                        boardFit += 1;
                                }

