                                    if( theyTargetOurAlly && MovesBefore( us, them, ip.TurnOrder ) && ( ( theirMove?.MoveSO.MoveCategory == MoveCategory.Physical && defBoosts > 0 ) || ( theirMove?.MoveSO.MoveCategory == MoveCategory.Special && spdefBoosts > 0 )  ) )
                                    {
                                        boardFit += 1;

