                        if( mainCapability == CapabilityObservation.HelpingHand && weHaveAlly )
                        {
                            if( ourAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                boardFit += 1;

                            bool allyAttacksThem = ourAllyPTKO_Them > ourAllyPTKO_TheirAlly;
                            bool allyAttacksTheirAlly = theyHaveAlly && ourAllyPTKO_TheirAlly >= ourAllyPTKO_Them;

                            bool ourAllyHasSpread = ourAlly.RoleProfile.Traits.Contains( RoleTrait.SpreadAttack );
                            bool ourAllyUsesSpread = _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() ) || ( theyHaveAlly && _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() ) );
                            bool ourAllyBestBothIsSpread = theyHaveAlly && _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() ) && _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() );
                            bool ourAllySpreadIsBigDamage = ourAllyBestBothIsSpread && ourAllyPTKO_Them >= PotentialToKO.Risky && ourAllyPTKO_TheirAlly >= PotentialToKO.Risky;

