                            var adjustedPTKO_TheirAlly = theyHaveAlly || ourAllyBestBothIsSpread ? _ai.Projection.Get_InteractionModifiedPTKO( ip.OurAllyVsTheirAlly.Attacker.BestEDR, ourAlly, theirAlly, addModifier: 1.5f ) : PotentialToKO.Untouchable;

