                            if( ourAllyHasSpread )
                            {
                                boardFit += 1;

                                if( ourAllyUsesSpread )
                                    boardFit += 1;

                                if( ourAllyBestBothIsSpread )
                                    boardFit += 1;

                                if( ourAllySpreadIsBigDamage )
                                    boardFit += 2;

                                if( ourAllyMovesBefore_Both )
                                    boardFit += 2;
                            }

                            if( ( allyAttacksThem || ourAllyBestBothIsSpread ) && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                            {
                                //--This is just the "we remove them regardless of what they want to do" bonus
                                boardFit += 1;

                                if( ip.TheyWant.SetTailwind || ip.TheyWant.SetTrickRoom )
                                    boardFit += 2;

                                if( ( ip.TheyWant.SetReflect || ip.TheyWant.Wisp ) && ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Physical )
                                    boardFit += 1;

                                if( ( ip.TheyWant.SetLightScreen || ip.TheyWant.Hoarfrost ) && ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Special )
                                    boardFit += 1;

                                if( ip.TheyWant.SetAuroraVeil )
                                    boardFit += 1;

                                if( ip.TheyWant.SelfSetup || ip.TheyWant.StatDebuff )
                                    boardFit += 1;

                                if( ip.TheyWant.Taunt || ip.TheyWant.Spore || ip.TheyWant.SleepPowder || ip.TheyWant.TWave )
                                    boardFit += 1;
                            }

                            if( ( allyAttacksTheirAlly || ourAllyBestBothIsSpread ) && ourAllyPTKO_TheirAlly >= PotentialToKO.Dangerous )
                            {
                                boardFit += 1;

                                if( ip.TheyWant.HelpingHand )
                                    boardFit += 1;

                                if( theirAllyHasIntent )
                                    boardFit += 1;
                            }
                        }

                        if( mainCapability == CapabilityObservation.AfterYou && weHaveAlly )
                        {
                            if( ourAlly.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                boardFit += 1;

                            bool allyAttacksThem = ourAllyPTKO_Them > ourAllyPTKO_TheirAlly;
                            bool allyAttacksTheirAlly = theyHaveAlly && ourAllyPTKO_TheirAlly >= ourAllyPTKO_Them;

                            bool ourAllyHasSpread = ourAlly.RoleProfile.Traits.Contains( RoleTrait.SpreadAttack );
                            bool ourAllyUsesSpread = _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() ) || ( theyHaveAlly && _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() ) );
                            bool ourAllyBestBothIsSpread = theyHaveAlly && _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First() ) && _ai.UnitSim.MoveIsSpreadAttack( ip.OurAllyVsTheirAlly.Attacker.CurrentPTKOs.Keys.First() );
                            bool ourAllySpreadIsBigDamage = ourAllyBestBothIsSpread && ourAllyPTKO_Them >= PotentialToKO.Risky && ourAllyPTKO_TheirAlly >= PotentialToKO.Risky;

                            bool ourAllyAfter_Them = MovesBefore( them, ourAlly, ip.TurnOrder );
