                                    }
                                }
                            }

                            if( theirAction == ActionType.Attack )
                            {
                                boardFit += 1;
                                
                                if( MovesBefore( us, them, ip.TurnOrder ) )
                                    boardFit += 2;
                            }

                            if( them.BeginningHPR <= 0.33f && MovesBefore( us, them, ip.TurnOrder ) )
                                boardFit += 3;
                            else if( them.BeginningHPR <= 0.33f )
                                boardFit += 2;
                            else if( them.BeginningHPR <= 0.66f )
                                boardFit += 1;

                            if( them.BeginningHPR <= 0.66f && weHaveAlly && ourAllyPTKO_Them >= PotentialToKO.Dangerous && MovesBefore( us, them, ip.TurnOrder ) && MovesBefore( us, ourAlly, ip.TurnOrder ) )
                            {
                                boardFit += 2;
                                weCanEnableOurAlly = true;
                            }
                        }
                    }

                    if( mainCapability == CapabilityObservation.PerishSong )
                    {
                        if( ourBench.Count > 0 || ( ourAlly != null && ourAlly.Ability == AbilityID.Soundproof ) )
                        {
                            if( theirBench.Count < ourBench.Count )
                                boardFit += 1;

                            if( theirBench.Count <= 0 )
                                boardFit += 1;

                            if( ourBench.Count > 0 && ( us.RoleProfile.Traits.Contains( RoleTrait.TrappingAbility ) || ( ourAlly != null && ourAlly.RoleProfile.Traits.Contains( RoleTrait.TrappingAbility ) ) ) )
                            {
                                boardFit += 3;

                                weCanCreateBoardAdvantage = true;

                                if( ourAlly != null && ourAlly.RoleProfile.Traits.Contains( RoleTrait.TrappingAbility ) )
                                    weCanEnableOurAlly = true;
                            }

                            if( them.Pokemon.BindingStatuses?.Count > 0 || theirAlly?.Pokemon.BindingStatuses?.Count > 0 )
                            {
                                boardFit += 1;

                                if( them.Pokemon.BindingStatuses?.Count > 0 && theirAlly?.Pokemon.BindingStatuses?.Count > 0 )
                                    boardFit += 2;
                            }

                            if( ourAlly != null && _ai.UnitSim.PokemonHasMove_Trapping( ourAlly.Pokemon ) )
                            {
                                boardFit += 1;
                            }

                            if( theirAction != ActionType.OffensiveSwitch && theirAction != ActionType.DefensiveSwitch )
                                boardFit += 2;
                        }

                        if( them.Ability == AbilityID.Soundproof )
                            boardFit -= 2;

                        if( theirAlly != null && theirAlly.Ability == AbilityID.Soundproof )
                            boardFit -= 2;
                    }
                }

                if( entryHazard )
                {
                    //--Hazards aren't particularly good in vgc style doubles due to the small teams
                    //--I'll give some flat rewards + some minor checks

                    if( _ai.Round <= 2 )
                        boardFit += 2;

                    if( theirBench.Count >= 2 )
                        boardFit += 1;

                    weCanThreatenUtilityPressure = true;

                    switch( candidate.MoveCandidate.MoveSO.MoveEffects.CourtCondition )
                    {
                        case CourtConditionID.LeechSeed:

                            int fireTypes = 0;
                            foreach( var kvp in _ai.Blackboard.TheirTeamAdapters )
                            {
                                var mon = kvp.Key;
                                if( mon.CurrentHP > 0 && mon.CheckTypes( PokemonType.Fire ) )
                                    fireTypes++;
                            }

                            if( fireTypes == 0 )
                                boardFit += 1;

                            //--Passive healing is useful even in short battles
                            boardFit += 1;

                        break;

                        case CourtConditionID.StealthRock:

                            foreach( var mon in theirBench )
                            {
                                if( TypeChart.GetTotalEffectiveness( PokemonType.Rock, mon.Type.One, mon.Type.Two ) > 1f )
                                    boardFit += 1;
                            }

                        break;

                        case CourtConditionID.ToxicSpikes:

                            int poisonTypes = 0;
                            foreach( var kvp in _ai.Blackboard.TheirTeamAdapters )
                            {
                                var mon = kvp.Key;
                                if( mon.CurrentHP > 0 && mon.CheckTypes( PokemonType.Poison ) )
                                    poisonTypes++;
                            }

                            if( poisonTypes == 0 )
                                boardFit += 1;

                        break;

                        case CourtConditionID.StickyWeb:

                            foreach( var mon in theirBench )
                            {
                                if( mon.RoleProfile.Biases.Contains( RoleBias.MiddlingSpeed ) || mon.RoleProfile.Biases.Contains( RoleBias.FastSpeed ) )
                                    boardFit += 1;
                            }

                        break;
                    }
                }

                if( statDebuff )
                {
                    if( candidate.MoveCandidate != null )
                    {
                        var statStages = candidate.MoveCandidate.MoveSO.MoveEffects.StatChangeList;

                        if( statStages?.Count > 0 )
                        {
                            weCanThreatenUtilityPressure = true;
                            bool weAreFaster = us.Speed > them.Speed || ( us.Ability == AbilityID.Prankster && !theyBlockPrankster );
                            foreach( var sc in statStages )
                            {
                                Dictionary<Stat, int> changes = new(){ { sc.Stat, sc.Change } };

                                if( sc.Change < 0 )
                                {
                                    //-------------------
                                    //--Offensive Stats--
                                    //-------------------
                                    if( sc.Stat == Stat.Attack || sc.Stat == Stat.SpAttack )
                                    {
                                        bool attackAlignsWithReduction = ( sc.Stat == Stat.Attack && theirMove?.MoveSO.MoveCategory == MoveCategory.Physical ) || ( sc.Stat == Stat.SpAttack && theirMove?.MoveSO.MoveCategory == MoveCategory.Special );

                                        if( sc.Stat == Stat.Attack )
                                        {
                                            if( them.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                            {
                                                boardFit += 1;

                                                if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                                    boardFit += 1;
                                            }

                                            if( theirMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                                            {
                                                boardFit += 1;

                                                if( weAreFaster )
                                                    boardFit += 1;
                                            }
                                        }

                                        if( sc.Stat == Stat.SpAttack )
                                        {
                                            if( them.RoleProfile.Biases.Contains( RoleBias.Special ) )
                                            {
                                                boardFit += 1;

                                                if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive )
                                                    boardFit += 1;
                                            }

                                            if( theirMove?.MoveSO.MoveCategory == MoveCategory.Special )
                                            {
                                                boardFit += 1;

                                                if( weAreFaster )
                                                    boardFit += 1;
                                            }
                                        }

                                        if( theyTargetUs && attackAlignsWithReduction )
                                        {
                                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, us, attackerStatStageChanges: changes );
                                            boardFit += 1;

                                            if( adjustedPTKO < theirPTKO_Us )
                                            {
                                                boardFit += 1;
                                                weReducePTKO = true;
                                            }

                                            if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                                boardFit += 1;

                                            if( weAreFaster )
                                                boardFit += 1;
                                        }

                                        if( theyTargetOurAlly && ourAlly != null && attackAlignsWithReduction )
                                        {
                                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( theirEDR, them, ourAlly, attackerStatStageChanges: changes );
                                            boardFit += 1;

                                            if( adjustedPTKO < theirPTKO_Us )
                                            {
                                                boardFit += 1;
                                                weReducePTKO = true;
                                            }
                                                
                                            if( adjustedPTKO <= PotentialToKO.TwoHKO || theirPTKO_Us - adjustedPTKO >= 2 )
                                                boardFit += 1;

                                            if( weAreFaster )
                                                boardFit += 1;
                                        }
                                    }

                                    //-------------------
                                    //--Defensive Stats--
                                    //-------------------
                                    if( sc.Stat == Stat.Defense )
                                    {
                                        if( them.RoleProfile.Biases.Contains( RoleBias.PhysicallyBulky ) )
                                        {
                                            boardFit += 1;

                                            if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Defensive || them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                                                boardFit += 1;
                                        }

                                        if( us.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                            boardFit += 1;

                                        if( ourAlly != null && ourAlly.RoleProfile.Biases.Contains( RoleBias.Physical ) )
                                            boardFit += 1;

                                        if( ip.UsVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Physical )
                                        {
                                            boardFit += 1;

                                            var ourEDR = ip.UsVsThem.Attacker.BestEDR;
                                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( ourEDR, us, them, targetStatStageChanges: changes );

                                            if( adjustedPTKO > ourPTKO_Them )
                                            {
                                                boardFit += 1;
                                                weCanCreateBoardAdvantage = true;

                                                if( adjustedPTKO >= PotentialToKO.Dangerous || ( adjustedPTKO - ourPTKO_Them > 2 ) )
                                                {
                                                    boardFit += 1;
                                                }
                                            }
                                        }

                                        if( ourAlly != null && ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Physical )
                                        {
                                            boardFit += 1;

                                            var ourAllyEDR = ip.OurAllyVsThem.Attacker.BestEDR;
                                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( ourAllyEDR, ourAlly, them, targetStatStageChanges: changes );

                                            if( adjustedPTKO > ourPTKO_TheirAlly )
                                            {
                                                boardFit += 1;
                                                weCanCreateBoardAdvantage = true;
                                                
                                                if( MovesBefore( us, ourAlly, ip.TurnOrder ) )
                                                    weCanEnableOurAlly = true;

                                                if( adjustedPTKO >= PotentialToKO.Dangerous || ( adjustedPTKO - ourPTKO_TheirAlly > 2 ) )
                                                {
                                                    boardFit += 1;
                                                }
                                            }
                                        }

                                        if( weAreFaster )
                                            boardFit += 1;
                                    }

                                    if( sc.Stat == Stat.SpDefense )
                                    {
                                        if( them.RoleProfile.Biases.Contains( RoleBias.SpeciallyBulky ) )
                                        {
                                            boardFit += 1;

                                            if( them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Defensive || them.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                                                boardFit += 1;
                                        }

                                        if( us.RoleProfile.Biases.Contains( RoleBias.Special ) )
                                            boardFit += 1;

                                        if( ourAlly != null && ourAlly.RoleProfile.Biases.Contains( RoleBias.Special ) )
                                            boardFit += 1;

                                        if( ip.UsVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Special )
                                        {
                                            boardFit += 1;

                                            var ourEDR = ip.UsVsThem.Attacker.BestEDR;
                                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( ourEDR, us, them, targetStatStageChanges: changes );

                                            if( adjustedPTKO > ourPTKO_Them )
                                            {
                                                boardFit += 1;
                                                weCanCreateBoardAdvantage = true;

                                                if( adjustedPTKO >= PotentialToKO.Dangerous || ( adjustedPTKO - ourPTKO_Them > 2 ) )
                                                {
                                                    boardFit += 1;
                                                }
                                            }
                                        }

                                        if( ourAlly != null && ip.OurAllyVsThem.Attacker.CurrentPTKOs.Keys.First().MoveSO.MoveCategory == MoveCategory.Special )
                                        {
                                            boardFit += 1;

                                            var ourAllyEDR = ip.OurAllyVsThem.Attacker.BestEDR;
                                            var adjustedPTKO = _ai.Projection.Get_InteractionModifiedPTKO( ourAllyEDR, ourAlly, them, targetStatStageChanges: changes );

                                            if( adjustedPTKO > ourPTKO_TheirAlly )
                                            {
                                                boardFit += 1;
                                                weCanCreateBoardAdvantage = true;
                                                
                                                if( MovesBefore( us, ourAlly, ip.TurnOrder ) )
                                                    weCanEnableOurAlly = true;

                                                if( adjustedPTKO >= PotentialToKO.Dangerous || ( adjustedPTKO - ourPTKO_TheirAlly > 2 ) )
                                                {
                                                    boardFit += 1;
                                                }
                                            }
                                        }

                                        if( weAreFaster )
                                            boardFit += 1;
                                    }

                                    //-------------------
                                    //--Speed Stat-------
                                    //-------------------
                                    if( sc.Stat == Stat.Speed )
                                    {
                                        if( them.Speed > us.Speed && us.Speed > them.Speed / _stageModifier[sc.Change] )
                                        {
                                            boardFit += sc.Change;
                                            weCanCreateBoardAdvantage = true;

                                            if( theirPTKO_Us <= PotentialToKO.Risky && ourPTKO_Them >= PotentialToKO.Risky )
                                                boardFit += 1;
                                        }

                                        if( them.Speed > ourAlly?.Speed && ourAlly?.Speed > them.Speed / _stageModifier[sc.Change] )
                                        {
                                            boardFit += sc.Change;
                                            weCanCreateBoardAdvantage = true;
                                            weCanEnableOurAlly = true;

                                            if( ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                            {
                                                boardFit += 1;

                                                if( weAreFaster )
                                                    boardFit += 1;
                                            }
                                        }
                                    }

                                    if( sc.Stat == Stat.Accuracy || sc.Stat == Stat.Evasion )
                                    {
                                        boardFit += sc.Change;

                                        if( sc.Stat == Stat.Accuracy && ( theirPTKO_Us >= PotentialToKO.Risky || theirPTKO_OurAlly >= PotentialToKO.Risky) )
                                            boardFit += 1;

                                        if( sc.Stat == Stat.Evasion && ourAlly != null && ourAllyPTKO_Them >= PotentialToKO.Dangerous )
                                            boardFit += 1;
                                    }
                                }
                            }
                        }
                    }
                }

                //--Phaze
                if( phaze )
                {
                    if( MovesBefore( us, them, ip.TurnOrder ) )
                    {
                        wePreventTheirAction = theirAction != ActionType.DefensiveSwitch && theirAction != ActionType.OffensiveSwitch;

                        if( theirAction == ActionType.Attack )
                            weReducePTKO = true;

                        if( ip.TheyCan.SetTailwind && !theirCourt.ContainsKey( CourtConditionID.Tailwind ) )
                        {
                            boardFit += 2;
                            weCanRemoveTheirResources = true;
                        }

                        if( ( ip.TheyCan.SetReflect && !theirCourt.ContainsKey( CourtConditionID.Reflect ) ) || ( ip.TheyCan.SetLightScreen && !theirCourt.ContainsKey( CourtConditionID.LightScreen ) ) || ( ip.TheyCan.SetAuroraVeil && !theirCourt.ContainsKey( CourtConditionID.AuroraVeil ) ) )
                        {
                            boardFit += 1;
                            weCanRemoveTheirResources = true;
                        }

                        if( ip.TheyCan.SetMoveWeather || ip.TheyCan.SetMoveTerrain )
                        {
                            boardFit += 1;
                            weCanRemoveTheirResources = true;
                        }

                        if( theirAction == ActionType.OffensiveStatus || theirAction == ActionType.Setup )
                            boardFit += 1;
                    }

                    //--Trick Room always goes last
                    if( ip.TheyCan.SetTrickRoom && ( theirSP.DependsOnTrickRoom || theirAllySP.DependsOnTrickRoom ) && !field.FieldConditions.ContainsKey( FieldConditionID.TrickRoom ) )
                    {
                        boardFit += 5;
                        weCanRemoveTheirResources = true;
                        weCanReduceTheirThreat = true;
                    }
                    
                    //--It's always good to remove a trapper
                    if( them.RoleProfile.Traits.Contains( RoleTrait.TrappingAbility ) || ( them.RoleProfile.Traits.Contains( RoleTrait.TrappingMove ) && us.Bindings?.Count > 0 ) )
                    {
                        boardFit += 3;
                        weCanReduceTheirThreat = true;
                    }

                    int boosts = 0;
                    foreach( var sc in them.StatStages )
                    {
                        if( sc.Value > 0 )
                            boosts++;
                    }

                    if( boosts >= 3 )
                        boardFit += 3;
                    else
                        boardFit += boosts;

                    if( boosts > 0 )
                    {
                        weCanReduceTheirThreat = true;
                        weCanRemoveTheirResources = true;
                    }

                    if( MovesBefore( us, them, ip.TurnOrder ) && boosts >= 1 )
                    {
                        boardFit += 2;

                        if( boosts >= 3 )
                            boardFit += 1;
                    }

                    if( weCanReduceTheirThreat || weCanRemoveTheirResources || wePreventTheirAction )
                        weCanThreatenUtilityPressure = true;
                }

                if( wePreventTheirAction )
                {
                    boardFit += 1;

                    if( ip.TheyWant.SetTailwind )
                        boardFit += 1;

                    if( ip.TheyWant.SetTrickRoom )
                        boardFit += 1;

                    if( ip.TheyWant.SetReflect || ip.TheyWant.SetLightScreen || ip.TheyWant.SetAuroraVeil )
                        boardFit += 1;
                }

                if( weReducePTKO )
                    boardFit += 1;

                if( weCrippleTheirSupport )
                {
                    boardFit += 1;
                }

                //-------------
                //--Creations--
                //-------------
                if( weCanReduceTheirThreat )
                    creations += 1;

                if( weCanEnableOurAlly )
                    creations += 1;

                if( weCanCoverOurAlly )
                    creations += 1;

                if( weCanThreatenBigDamageAcrossTheBoard )
                    creations += 1;

                if( weCanThreatenUtilityPressure )
                    creations += 1;

                if( weCanRemoveTheirResources )
                    creations += 1;

                if( weCanCreateBoardAdvantage )
                    creations += 1;


                //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                //--Unit Fit----------------------------------------------------------------------------------------------------------------------------------------------------------
                //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                if( us.Speed > them.Speed || us.Ability == AbilityID.Prankster )
                    unitFit += 1;

                if( MovesBefore( us, them, ip.TurnOrder ) )
                    unitFit += 1;

                if( theyHaveAlly && MovesBefore( us, theirAlly, ip.TurnOrder ))

                if( us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                    unitFit += 1;

                if( statusEffect && us.RoleProfile.Biases.Contains( RoleBias.SupportFocused ) )
                    unitFit += 1;

                if( ( disruption || phaze ) && ( us.RoleProfile.Biases.Contains( RoleBias.Disruptive ) || us.RoleProfile.PrimaryRole == RoleClass.Disrupter ) )
                    unitFit += 1;

                bool reapplyable = mainCapability == CapabilityObservation.Paralysis || mainCapability == CapabilityObservation.Sleep || disruption || statDebuff || phaze;
                if( ( us.RoleProfile.Biases.Contains( RoleBias.FastSpeed ) || us.Ability == AbilityID.Prankster ) && reapplyable )
                    unitFit += 1;

                if( us.Item == ItemBattleEffectID.FocusSash || ( us.Item != ItemBattleEffectID.None && us.RoleProfile.Traits.Contains( RoleTrait.RecoveryItem ) ) )
                    unitFit += 1;

                if( ourAlly != null && ( ourAlly.RoleProfile.Traits.Contains( RoleTrait.RedirectionMove ) || _ai.CanUseFakeOut( ourAlly, them ) ) )
                    unitFit += 1;

                //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                //--Plan Fit----------------------------------------------------------------------------------------------------------------------------------------------------------
                //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                // bool theyAreWincon = them.Pokemon == gp.TheirPrimaryWinCon; //--these are declared in the initial data gathering block
                // bool theyAreBlocker = gp.TheirBlockers.Contains( them.Pokemon ); //--these are declared in the initial data gathering block
                bool theyAreEnabler = gp.TheirEnablers.Contains( them.Pokemon );

                bool weAreWincon = us.Pokemon == gp.OurPrimaryWinCon;
                bool weAreBlocker = gp.OurBlockers.Contains( us.Pokemon );
                bool weAreEnabler = gp.OurEnablers.Contains( us.Pokemon );

                bool ourAllyIsWincon = ourAlly?.Pokemon == gp.OurPrimaryWinCon;

                if( theyAreWincon && ( weReducePTKO || wePreventTheirAction ) )
                    planFit += 1;

                if( theyAreBlocker || theyAreEnabler )
                {
                    if( wePreventTheirAction )
                        planFit += 1;
                    
                    if( weCrippleTheirSupport )
                        planFit += 1;
                }

                if( weAreBlocker )
                {
                    planFit += 1;

                    if( weReducePTKO )
                        planFit += 1;

                    if( wePreventTheirAction )
                        planFit += 1;

                    if( weCrippleTheirSupport )
                        planFit += 1;
                }

                if( weAreEnabler && ourAllyIsWincon )
                {
                    planFit += 1;

                    if( weCrippleTheirSupport )
                        planFit += 1;
                }

                //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                //--Cost/Risk---------------------------------------------------------------------------------------------------------------------------------------------------------
                //--------------------------------------------------------------------------------------------------------------------------------------------------------------------
                if( theirPTKO_Us >= PotentialToKO.Dangerous )
                {
                    costRisk += 1;
                    
                    if( !weReducePTKO && theyTargetUs )
                        costRisk += 2;
                }

                if( theirAllyPTKO_Us >= PotentialToKO.Dangerous )
                {
                    costRisk += 1;

                    if( !weReducePTKO && theirAllyTargetsUs )
                        costRisk += 2;
                }

                if( !weReducePTKO && theyTargetUs && theirAllyTargetsUs )
                    costRisk += 2;

                if( ip.TheyCan.Taunt )
                    costRisk += 1;

                if( ip.TheyCan.Encore && theyOutSpeedStatus )
                    costRisk += 1;

                if( ip.TheyCan.Taunt && theyOutSpeedStatus )
                    costRisk += 2;

                if( ip.TheyCan.Disable && us.RoleProfile.PrimaryArchetype == RoleClassArchetype.Utility )
                    costRisk += 1;

                if( ip.TheyCan.FakeOut && !weBlockPriority )
                    costRisk += 2;

                if( ip.TheyCan.TWave && !us.RoleProfile.Traits.Contains( RoleTrait.ThunderWaveImmune ) )
                    costRisk += 1;

                if( ( ip.TheyCan.SleepPowder || ip.TheyCan.Spore ) && ( !us.RoleProfile.Traits.Contains( RoleTrait.PowderImmune ) || !us.RoleProfile.Traits.Contains( RoleTrait.SleepImmune ) ) )
                    costRisk += 1;

                if( ip.TheyCan.CraftyShield || ( us.Ability == AbilityID.Prankster && ip.TheyCan.QuickGuard ) )
                    costRisk += 2;

                if( ip.TheyCan.RagePowder || ip.TheyCan.FollowMe )
                    costRisk += 1;

                if( mainCapability == CapabilityObservation.Taunt && theirAction != ActionType.OffensiveStatus && theirAction != ActionType.SupportiveStatus )
                {
                    costRisk += 2;

                    if( theirAction == ActionType.Attack && theirMove != null && theirPTKO_Us >= PotentialToKO.Dangerous )
                    {
                        costRisk += 2;

                        if( theirPTKO_Us >= PotentialToKO.OHKO )
                            costRisk += 1;

                        if( MovesBefore( them, us, ip.TurnOrder ) )
                            costRisk += 1;
                    }
                }

                int finalScore = creations + boardFit + unitFit + planFit - costRisk;

                CoordinationActionScores scores = new()
                {
                    CreationScore = creations,
                    BoardFitScore = boardFit,
                    UnitFitScore = unitFit,
                    PlanFitScore = planFit,
                    CostRiskScore = costRisk,

                    FinalScore = finalScore,
                };

                capabilityCandidates.Add( candidate, scores );
            }
        }

        return capabilityCandidates;
    }

    private Dictionary<CoordinationAction, CoordinationActionScores> GetSupportiveStatusOpportunities( Dictionary<Pokemon, HashSet<CapabilityObservation>> capabilitySets )
    {
        Dictionary<CoordinationAction, CoordinationActionScores> capabilityCandidates = new();

        List<IBattleAIUnit> ourActive = _ai.Blackboard.OurActiveBattleAIUnits;
        List<IBattleAIUnit> ourBench = GetPokemonBench( ourActive[0].Pokemon );

        List<IBattleAIUnit> theirActive = _ai.Blackboard.TheirActiveBattleAIUnits;
        List<IBattleAIUnit> theirBench = GetPokemonBench( theirActive[0].Pokemon );

        foreach( var unit in ourActive )
        {
            List<CoordinationAction> candidates = new();
            var baseCapabilities = ExtractBaseCapabilities( ActionType.SupportiveStatus, unit.Pokemon );

            if( capabilitySets.TryGetValue( unit.Pokemon, out var monCapabilities ) )
            {
                if( baseCapabilities.TryGetValue( unit.Pokemon, out var bcs ) )
                {
                    foreach( var bc in bcs )
                        monCapabilities.Add( bc );
                }

                foreach( var capability in monCapabilities )
                {
                    if( GetCapabilityActionType( capability ) != ActionType.SupportiveStatus )
                        continue;

                    foreach( var opp in theirActive )
                    {
                        var candidate = GetSupportiveStatusCandidate( capability, unit, opp, CoordinationActionType.Opportunity );
                        candidates.Add( candidate );
                    }
                }
            }

            if( candidates?.Count <= 0 )
                continue;

            foreach( var candidate in candidates )
            {
                //--Scoreboard
                int creations = 0;
                int boardFit = 0;
                int unitFit = 0;
                int planFit = 0;
                int costRisk = 0;

                var mainCapability = candidate.Capability;

                bool recovery = false;
                bool forceMultiplier = false;
                bool battlefieldControl = false;
                bool allyProtection = false;

                bool reflectable = candidate.MoveCandidate != null && candidate.MoveCandidate.MoveSO.Flags != null && candidate.MoveCandidate.MoveSO.Flags.Count > 0 && candidate.MoveCandidate.MoveSO.Flags.Contains( MoveFlags.Reflectable );
                bool theyReflect = candidate.Target?.AbilityID == AbilityID.MagicBounce;

                if( reflectable && theyReflect )
                    continue;

                if( candidate.Actor.VolatileStatuses.ContainsKey( VolatileConditionID.Taunt ) )
                    continue;

                var us = _ai.GetPokemonAs_IBattleAIUnit( candidate.Actor );
                var them = _ai.GetPokemonAs_IBattleAIUnit( candidate.Target );

                var field = _ai.Blackboard.CurrentFieldSnapshot;
                var currentWeather = field.Weather;
                var currentTerrain = field.Terrain;

                var ourCourt = us.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;
                var theirCourt = them.CourtLocation == CourtLocation.TopCourt ? field.TopCourtConditions : field.BottomCourtConditions;

                switch( mainCapability )
                {
                    //--Recovery
                    case CapabilityObservation.SelfHeal:
                        recovery = true;
                    break;

                    //--Force Multiplier
                    case CapabilityObservation.Tailwind:

                        if( ourCourt.ContainsKey( CourtConditionID.Tailwind ) )
                            continue;
                        else
                            forceMultiplier = true;
                        break;

                    case CapabilityObservation.Reflect:

                        if( ourCourt.ContainsKey( CourtConditionID.Reflect ) )
                            continue;
                        else
                            forceMultiplier = true;
                        break;

                    case CapabilityObservation.LightScreen:

                        if( ourCourt.ContainsKey( CourtConditionID.LightScreen ) )
                            continue;
                        else
                            forceMultiplier = true;
