                            foreach( var se in secondaryEffects2 )
                            {
                                if( se.SevereStatus != SevereConditionID.None || se.VolatileStatus == VolatileConditionID.Yawn )
                                {
                                    pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );
                                    pair.Synergies.Add( CoordinationSynergy.ImprovesBoardDefense );
                                }
                            }
                        }
                    }

                    if( movesTerrain == TerrainID.Psychic )
                    {
                        bool priority1 = action1.TargetsMove?.Priority > MovePriority.Zero || ( action1.TargetsAction == ActionType.OffensiveStatus && action1.Target?.AbilityID == AbilityID.Prankster ) || ( action1.TargetsMove?.MoveSO.MoveCategory != MoveCategory.Status && action1.TargetsMove?.MoveType == PokemonType.Flying && action1.Target?.CurrentHP == action1.Target?.MaxHP && action1.Target?.AbilityID == AbilityID.GaleWings );
                        bool priority2 = action2.TargetsMove?.Priority > MovePriority.Zero || ( action2.TargetsAction == ActionType.OffensiveStatus && action2.Target?.AbilityID == AbilityID.Prankster ) || ( action2.TargetsMove?.MoveSO.MoveCategory != MoveCategory.Status && action2.TargetsMove?.MoveType == PokemonType.Flying && action2.Target?.CurrentHP == action2.Target?.MaxHP && action2.Target?.AbilityID == AbilityID.GaleWings );

                        if( priority1 || priority2 )
                        {
                            pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );
                            pair.Synergies.Add( CoordinationSynergy.ImprovesBoardDefense );
                        }
                    }
                }
            }

            if( action1.Capability == CapabilityObservation.Tailwind )
            {
                bool speedChanges = ( action2.Actor.Speed < action1.Target?.Speed && action2.Actor.Speed * tailwind > action1.Target?.Speed ) || ( action2.Actor.Speed < action2.Target?.Speed && action2.Actor.Speed * tailwind > action2.Target?.Speed );
                
                if( speedChanges )
                {
                    pair.Synergies.Add( CoordinationSynergy.ImprovesAllyTurnOrder );

                    if( action2.Action != ActionType.DefensiveSwitch && action2.Action != ActionType.OffensiveSwitch )
                    {
                        pair.Synergies.Add( CoordinationSynergy.EnablesAlly );

                        if( action2.Action == ActionType.Attack )
                            pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyOffense );
                        else if( action2.Action == ActionType.SupportiveStatus || action2.Action == ActionType.Setup )
                            pair.Synergies.Add( CoordinationSynergy.EnablesSetup );
                    }
                }
            }

            if( action1.Capability == CapabilityObservation.TrickRoom )
            {
                bool speedReverses = action2.Actor.Speed > action1.Target?.Speed || action2.Actor.Speed > action2.Target?.Speed;
                
                if( speedReverses )
                {
                    pair.Synergies.Add( CoordinationSynergy.ImprovesAllyTurnOrder );

                    var actor2 = _ai.GetPokemonAs_IBattleAIUnit( action2.Actor );
                    if( actor2.RoleProfile.PrimaryArchetype == RoleClassArchetype.Offensive && ( actor2.RoleProfile.PrimaryRole == RoleClass.TrickRoomAbuser || actor2.RoleProfile.Biases.Contains( RoleBias.SlowSpeed ) || actor2.RoleProfile.Biases.Contains( RoleBias.TrickRoomSpeed ) ) )
                    {
                        pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyOffense );
                        pair.Synergies.Add( CoordinationSynergy.ImprovesBoardOffense );
                    }
                }
            }

            if( action1.Capability == CapabilityObservation.StatReset )
            {
                var targetStatStages = action2.Target.StatStages;
                var actor2StatStages = action2.Actor.StatStages;

                if( action2.Action == ActionType.Attack && action1.Actor.Speed > action2.Actor.Speed )
                {
                    foreach( var sc in targetStatStages )
                    {
                        if( ( sc.Key == Stat.Defense && action2.MoveCandidate?.MoveSO.MoveCategory == MoveCategory.Physical && actor2StatStages[Stat.Attack] <= 0 ) || ( sc.Key == Stat.SpDefense && action2.MoveCandidate?.MoveSO.MoveCategory == MoveCategory.Special && actor2StatStages[Stat.SpAttack] <= 0 ) )
                            pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyOffense );

                        if( action2.TargetsAction == ActionType.Attack )
                        {
                            if( ( sc.Key == Stat.Attack && action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Physical && actor2StatStages[Stat.Defense] < 0 ) || ( sc.Key == Stat.SpAttack && action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Special && actor2StatStages[Stat.SpDefense] < 0 ) )
                                pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyDefense );
                        }
                    }
                }

                if( action2.TargetsAction == ActionType.Attack )
                {
                    foreach( var sc in targetStatStages )
                    {
                        if( ( sc.Key == Stat.Attack && action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Physical && actor2StatStages[Stat.Defense] < 0 ) || ( sc.Key == Stat.SpAttack && action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Special && actor2StatStages[Stat.SpDefense] < 0 ) )
                            pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyDefense );
                    }
                }

                if( action2.Target.Speed > action2.Actor.Speed && ( actor2StatStages[Stat.Speed] < 0 && action2.Actor.Speed * _stageModifier[0] > action2.Target.Speed ) || ( targetStatStages[Stat.Speed] > 0 && action2.Actor.Speed > action2.Target.Speed * _stageModifier[0] ) )
                    pair.Synergies.Add( CoordinationSynergy.ImprovesAllyTurnOrder );
            }

            if( action1.Capability == CapabilityObservation.Defog )
            {
                if( action2.Action == ActionType.DefensiveSwitch || action2.Action == ActionType.OffensiveSwitch )
                {
                    pair.Synergies.Add( CoordinationSynergy.CoversInvestment );
                    pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );
                }
            }

            if( action1.Capability == CapabilityObservation.SideStatBuff )
            {
                var targetStatStages = action2.Target.StatStages;
                var actor2StatStages = action2.Actor.StatStages;
                var moveStatStages = action1.MoveCandidate.MoveSO.MoveEffects.StatChangeList;

                if( moveStatStages?.Count > 0 )
                {
                    foreach( var sc in moveStatStages )
                    {
                        if( action2.Action == ActionType.Attack )
                        {
                            if( ( sc.Stat == Stat.Attack && action2.MoveCandidate?.MoveSO.MoveCategory == MoveCategory.Physical ) || ( sc.Stat == Stat.SpAttack && action2.MoveCandidate?.MoveSO.MoveCategory == MoveCategory.Special ) )
                            {
                                pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyOffense );
                                pair.Synergies.Add( CoordinationSynergy.ImprovesBoardOffense );
                            }
                        }

                        if( action2.TargetsAction == ActionType.Attack )
                        {
                            if( ( sc.Stat == Stat.Defense && action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Physical ) || ( sc.Stat == Stat.SpDefense && action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Special ) )
                            {
                                pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyDefense );
                                pair.Synergies.Add( CoordinationSynergy.ImprovesBoardDefense );
                            }
                        }

                        if( sc.Stat == Stat.Speed )
                        {
                            if( action2.Target.Speed > action2.Actor.Speed && action2.Actor.Speed * _stageModifier[sc.Change] > action2.Target.Speed )
                            {
                                pair.Synergies.Add( CoordinationSynergy.ImprovesAllyTurnOrder );
                            }
                        }
                    }
                }
            }

            if( action1.Capability == CapabilityObservation.SelfHeal )
            {
                if( action2.Action == ActionType.DefensiveSwitch || action2.Action == ActionType.OffensiveSwitch )
                {
                    pair.Synergies.Add( CoordinationSynergy.CoversInvestment );
                    pair.Synergies.Add( CoordinationSynergy.ProtectAndSwitch );
                }
            }

            if( action1.Capability == CapabilityObservation.SideHeal )
            {
                if( action2.Action == ActionType.DefensiveSwitch || action2.Action == ActionType.OffensiveSwitch )
                {
                    pair.Synergies.Add( CoordinationSynergy.CoversInvestment );

                    var switchCand = _ai.GetPokemonAs_IBattleAIUnit( action2.SwitchCandidate );
                    if( switchCand?.BeginningHPR <= 0.66f )
                        pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );
                }
                else
                {
                    if( action1.Actor.Speed > action2.Actor.Speed || action1.Actor.AbilityID == AbilityID.Prankster || action1.Actor.AbilityID == AbilityID.Triage )
                    {
                        pair.Synergies.Add( CoordinationSynergy.CoversInvestment );
                        var ally = _ai.GetPokemonAs_IBattleAIUnit( action2.Actor );

                        if( ally.BeginningHPR <= 0.66f )
                            pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );
                    }
                }
            }

            if( action1.Capability == CapabilityObservation.Reflect )
            {
                pair.Synergies.Add( CoordinationSynergy.ImprovesBoardDefense );

                if( action1.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Physical || action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Physical )
                    pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );

                if( ( action1.Actor.Speed > action2.Actor.Speed || action1.Actor.AbilityID == AbilityID.Prankster ) && ( action2.Action == ActionType.Setup || action2.Action == ActionType.OffensiveStatus || action2.Action == ActionType.SupportiveStatus ) )
                {
                    pair.Synergies.Add( CoordinationSynergy.EnablesSetup );
                    pair.Synergies.Add( CoordinationSynergy.CoversInvestment );
                }
            }

            if( action1.Capability == CapabilityObservation.LightScreen )
            {
                pair.Synergies.Add( CoordinationSynergy.ImprovesBoardDefense );

                if( action1.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Special || action2.TargetsMove?.MoveSO.MoveCategory == MoveCategory.Special )
                    pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );

                if( ( action1.Actor.Speed > action2.Actor.Speed || action1.Actor.AbilityID == AbilityID.Prankster ) && ( action2.Action == ActionType.Setup || action2.Action == ActionType.OffensiveStatus || action2.Action == ActionType.SupportiveStatus ) )
                {
                    pair.Synergies.Add( CoordinationSynergy.EnablesSetup );
                    pair.Synergies.Add( CoordinationSynergy.CoversInvestment );
                }
            }

            if( action1.Capability == CapabilityObservation.AuroraVeil )
            {
                pair.Synergies.Add( CoordinationSynergy.ImprovesBoardDefense );

                if( action1.TargetsMove?.MoveSO.MoveCategory != MoveCategory.Status || action2.TargetsMove?.MoveSO.MoveCategory != MoveCategory.Status )
                    pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );

                if( ( action1.Actor.Speed > action2.Actor.Speed || action1.Actor.AbilityID == AbilityID.Prankster ) && ( action2.Action == ActionType.Setup || action2.Action == ActionType.OffensiveStatus || action2.Action == ActionType.SupportiveStatus ) )
                {
                    pair.Synergies.Add( CoordinationSynergy.EnablesSetup );
                    pair.Synergies.Add( CoordinationSynergy.CoversInvestment );
                }
            }

            if( action1.Capability == CapabilityObservation.TidyUp )
            {
                if( action2.Action == ActionType.DefensiveSwitch || action2.Action == ActionType.OffensiveSwitch )
                {
                    pair.Synergies.Add( CoordinationSynergy.CoversInvestment );
                    pair.Synergies.Add( CoordinationSynergy.ProtectsAlly );
                }

                if( ( action2.Action == ActionType.Attack || action2.Action == ActionType.OffensiveStatus ) && action1.Actor.Speed > action2.Actor.Speed && action2.MoveCandidate?.Priority <= MovePriority.Zero )
                {
                    if( action2.Target.VolatileStatuses.ContainsKey( VolatileConditionID.Substitute ) )
                    {
                        pair.Synergies.Add( CoordinationSynergy.ReinforcesAllyOffense );
                        pair.Synergies.Add( CoordinationSynergy.EnablesAlly );
                        pair.Synergies.Add( CoordinationSynergy.EnablesAttack );
                    }
                }
            }
        }
    }

